async function jumpTo(page, q) {
  const p0 = Math.max(1, (page | 0) || 1);
  if (pageMode === 'paged') {
    if (!pdfDoc) return;
    const p = Math.min(p0, pdfDoc.numPages);
    if (p !== curPage) { curPage = p; await rerender(); }
    if (!(q && highlightSnippet(p, q))) flashPage();
    return;
  }
