   \"ai-assistant\",\n    \"rag\",\n    \"translation\"\n  ],\n  \"dependencies\": {\n    \"@typesafe-ai/sdk\": \"^0.6.0\",\n    \"pdfjs-dist\": \"^6.3.289\",\n    \"undici\": \"^8.10.2\"\n  },\n  \"peerDependencies\": {\n    \"@deepseek-ai/cordis\": \"^4.0.2\",\n    \"@deepseek-ai/dsh-tools\": \">=0.2.0-rc.2 <0.3.0-0\"\n  },\n  \"devDependencies\": {\n    \"@deepseek-ai/cordis\": \"^4.0.2\",\n    \"@deepseek-ai/dsh-tools\": \"0.2.0-rc.2\",\n    \"@types/node\": \"^22.10.0\",\n    \"typescript\": \"^5.6.0\"\n  }\n}\n"
