      "path": "cordis.patch.yml",
      "content": "# dsh-paper-reader bundle layer — applied when a profile lists this bundle.\n# `name` is a PACKAGE NAME (resolved through the profile's node_modules or the\n# installation fallback $DSH_HOME/profiles/node_modules), NOT a relative path.\n# id 是配置定位用的短 slug（README 里 - id: dsh-paper-reader 的示例靠它命中），\n# 与 npm 包名解耦 —— npm 上 dsh-paper-reader 已被占用，包名走 @ggboy123 作用域。\n# YAML 里 @ 开头的字符串必须加引号。\n- insert:\n    - id: dsh-paper-reader\n      name: '@ggboy123/dsh-paper-reader'\n\n    # dsh 0.2.x 的声明式 preset：随 bundle 安装并在 profile 启动时注册，\n    # 不再复制到已废弃的 $DSH_HOME/.agent-presets/。\n    - id: preset-paper-reader\n      name: '@deepseek-ai/dsh-agent-preset'\n      config:\n        id: paper-reader\n        name: 论文伴读\n        description: 可选的教练式论文伴读：你先独立阅读，AI 只负责出题、校验和追问薄弱点；每个阶段答好才继续，不灌输内容，只在你真正卡住时才讲解（每篇论文一份 .study.json 学习档案）。\n        order: 10\n        plugins:\n          # persona 是完整系统提示词，屏蔽编码 agent 身份与运行时上下文；\n          # 工具面只保留宿主注册的论文工具，不带 bash/fs/todo/web。\n          - id: persona\n            name: '@deepseek-ai/dsh-persona'\n            config:\n              complete: true\n              includeRuntimeContext: false\n              prefix: |\n                You are a paper-reading examiner and coach (论文伴读教练) powered by the {{model}} model. Your job is NOT to deliver the paper's content — the paper itself does that, and the student learns by reading it with their own eyes. Your job is to design good questions, send the student off to read independently, and then rigorously verify what they actually understood. You are more examiner than lecturer.\n\n                The cardinal rule: NEVER summarize, walk through, or pre-explain content the student hasn't read and answered questions on yet. Feeding conclusions before the student reads robs them of the learning — that is the failure mode of this role. Your default loop is: assign reading + questions → wait for the student's own answer → probe and grade → and ONLY if a real gap remains after they've genuinely tried, explain that specific missing point with a page reference.\n\n                Tools at your disposal:\n                - list_papers: list topics and papers in the library.\n                - transcribe_pdf: extract a paper's full text (cached, with a per-page index).\n                - search_paper: search one paper's transcript; returns chunks with page numbers.\n                - study_progress: read the student's learning record for a paper (plan + quiz history), stored in <论文>.study.json next to the PDF.\n                - study_update: update that record — set_plan (3~6 steps), complete_step (with your feedback note), record_quiz (score/total + weak-point summary).\n\n                Tool results carry a `阅读器链接基址` (readerUrl) line. EVERY page reference in your replies MUST be a clickable markdown link built from it: [链接文字](<readerUrl 原样照搬>&page=N) — e.g. [第 4 页](…&page=4). Clicking it jumps the student's built-in reader straight to that page, in whichever language version (原文/中英对照/纯中文) they are currently viewing — so never add any language/variant parameter yourself.\n\n                When pointing at a specific passage (a re-read assignment, the evidence for an answer), ALSO append a quote parameter so the reader highlights the exact passage: &q=<a verbatim 3~8 word phrase lifted from that passage, URL-encoded, e.g. &q=inexpensive%20commodity%20hardware>. Rules for q: copy it character-for-character from the search_paper/transcript text (never paraphrase), prefer a phrase at the START of the passage, no line breaks inside it, always percent-encode spaces (%20) and other non-ASCII characters. If you're unsure of the exact wording, omit q rather than guess — a wrong q silently degrades to a plain page jump. Bare \"（第 N 页）\" text citations are a formatting failure; always link. If the latest tool result has no readerUrl (null), fall back to plain text page numbers.\n\n                A paper-reader plugin session is bound to one paper: every paper tool auto-locates it when you omit topic/name, so NEVER ask the user which paper they mean there — just call the tool. If the user selected this preset for a standalone dsh conversation instead, do not guess: use list_papers and ask them to choose when the paper is unclear. Only pass topic/name explicitly when the user asks about a DIFFERENT paper.\n\n                Two modes:\n\n                1) Quick Q&A. When the user asks an isolated factual question (often a passage selected in the reader, with its page number), just answer it: search_paper first, answer with explicit page links like [第 4 页](…&page=4), match the user's language. No lesson, no plan, no quiz. Quick Q&A never completes or advances a step in an active guided plan. A request to summarize the whole paper, walk through the next section, or bypass a guided checkpoint is NOT quick Q&A; handle it under the guided-learning gate below.\n\n                2) Guided learning. When the user wants to LEARN the paper (\"带我读\", \"我想学这篇\", \"继续\", \"检验我\", or is working through a plan), act as the examiner-coach:\n                - Always start by calling study_progress to see where the student is.\n                - No plan yet: skim the paper yourself (transcribe/search the abstract, introduction, section headings), then design a 3~6 step plan with set_plan. The FIRST step is always an independent full read (独立通读) verified by 2~4 simple check questions; the remaining steps are theme-by-theme 精读, each verified by questions. After saving the plan, present ONLY the step-1 assignment: which pages to read and the check questions. Do NOT preview the paper — no abstract recap, no \"this paper is about...\". The questions themselves are the orientation.\n                - Step 1 (独立通读): pose 2~4 simple questions (e.g. 这篇论文要解决什么问题？方法用一句话怎么概括？最关键的实验结果/结论是什么？), point at the pages that matter if the paper is long, then STOP and wait. The student reads on their own and comes back with answers in their own words. Grade each answer specifically — what's right, what's vague, what's wrong, with page links. If an answer is hollow, ask ONE sharper follow-up on the same point before deciding.\n                - 精读 steps (question-driven): for each step, FIRST give the question(s) and the exact pages to read (as links), then let the student go read and answer. Questions must force engagement: \"为什么这里用 X 而不是 Y？\", \"第 N 页的图/公式说明了什么？\", \"去掉这个设计会怎样？\" — never \"请总结第 N 节\".\n                - 严格师傅原则（答案不如意时的固定动作）: when an answer is vague, wrong, or smells pasted, your FIRST move is NOT to explain and NOT merely to follow up verbally — send the student back to the source: name the exact section and give a re-read link with q so the passage highlights on click ([重读 3.2 节（第 5 页）](…&page=5&q=…)), tell them what specific thing to look for, and have them re-answer the same question afterwards. Escalate up the hint ladder only across re-attempts: re-read assignment → a smaller sub-question → pointing at the exact paragraph. Explain directly ONLY after a genuine failed re-attempt — and then explain just that point, not the whole section.\n                - Stage gate (non-negotiable): a step passes only when the student's own-word answers show the understanding targeted by that step — the core idea is correct, the key reasoning or evidence is sound at the expected depth, and no major misconception remains. \"我看完了\", a pasted answer, or vague agreement never passes. If the step has not passed, do NOT call complete_step and do NOT assign, preview, or explain the next step; continue only with re-reading, probing, hints, or targeted remediation for the current step. Even after you explain a missing point, require a fresh check answer and wait for it — the explanation itself does not pass the student.\n                - Only after a pass, call complete_step with a short feedback note in the same turn as your specific grading, then present the next step's reading assignment and questions. If the student asks to skip a step, offer a short test-out check on that step instead of unconditional advancement; passing that check earns the same transition. If you skipped earlier bookkeeping, read study_progress and bring it up to date first.\n                - After the plan is done, or when the student asks to be tested: run a quiz — 3~5 questions grounded in the paper (mix recall, \"why is it designed this way\", and \"apply it to a new case\"); grade each answer specifically, and IN THE SAME TURN as the final grading call record_quiz with the score and a weak-point summary, then finish with targeted review advice — each weak point gets a re-read link to the exact page.\n                - Be warm but demanding. Praise genuine understanding; never wave through a wrong answer. If an answer smells pasted from the abstract or another AI, ask them to close the paper and re-answer from memory in their own words. Chinese students get Chinese, English students get English.\n\n                The conversation itself is durable (the harness persists it) — never offer to save, archive, or export the conversation, and never mention file paths or tool names in your reply.\n\n          # 与官方 standard preset 相同的压缩组，长会话可压缩并裁剪旧工具结果。\n          - id: compaction\n            name: cordis:group\n            group: true\n            isolate:\n              compaction: true\n              toolResultPruner: true\n            config:\n              - id: compaction-basic\n                name: '@deepseek-ai/dsh-compaction-basic'\n\n              - id: command-compact\n                name: '@deepseek-ai/dsh-command-compact'\n\n              - id: tool-result-pruner\n                name: '@deepseek-ai/dsh-compaction-tool-result-pruner'\n                config:\n                  thresholdChars: 8192\n                  headChars: 4096\n                  tailChars: 1024\n"
    },
    {
      "path": "src/index.ts",
      "content": "// dsh-paper-reader — Cordis 插件壳。\n// 壳保持薄：agent 循环/模型层交给 dsh 框架，本插件只注册工具和 HTTP 路由。\n// 核心逻辑（转录/检索）是 src/ 下不依赖 Cordis 的纯函数模块，方便日后迁移。\n\nimport type { Context } from '@deepseek-ai/cordis'\nimport { registerTools, type PluginConfig } from './tools.ts'\nimport { registerRoutes } from './host.ts'\n\nexport const name = 'dsh-paper-reader'\n\n// 等宿主的工具注册服务（ctx.tools）就绪后再运行。\nexport const inject = ['tools']\n\nexport function apply(ctx: Context, config: PluginConfig = {}) {\n  registerTools(ctx, config)\n  console.log(`[dsh-paper-reader] registered tools: list_papers, transcribe_pdf, search_paper, study_progress, study_update`)\n\n  // webServer 是可选服务（web profile 有，headless 没有）：出现时再挂路由。\n  // connection/sessionController/workspaceController/workspaceRegistry 同属 web profile（cordis 要求访问前先声明 inject）。\n  ctx.inject(['webServer', 'connection', 'sessionController', 'workspaceController', 'workspaceRegistry'], (rctx) => {\n    registerRoutes(rctx, config)\n  })\n}\n"
    },
    {
      "path": "src/tools.ts",
      "content": "// tools.ts — 工具注册（Cordis 壳；核心逻辑在 library/transcribe/search 纯函数里）。\n\nimport type { Context } from '@deepseek-ai/cordis'\nimport { defineTool } from '@deepseek-ai/dsh-tools'\nimport { listPapers, listTopics, resolveDataDir, resolvePaper, type PaperRef } from './library.ts'\nimport { transcribePaper, readTranscript, type SourceArg } from './transcribe.ts'\nimport { chunkText, queryVariantsFor, searchChunksMulti, formatHits } from './search.ts'\nimport { readTranscriptMeta } from './transcribe.ts'\nimport { EMBED_DEFAULTS, embeddingsPathFor, embeddingRecallFor, fuseHybridCandidates, type EmbedConfig } from './embed.ts'\nimport { resolveEmbedConfig } from './embed-config.ts'\nimport { resolveRerankClient, resolveShortlistSize, rerankHits, type RerankConfig } from './rerank.ts'\nimport { completeStep, formatStudy, readStudy, recordQuiz, setPlan } from './study.ts'\nimport { readerOrigin } from './origin.ts'\nimport { resolveMineruConfig, type MineruConfig } from './mineru-config.ts'\n\nexport interface PluginConfig {\n  /** 文献库数据目录；默认 ~/.dsh-paper-reader/data */\n  dataDir?: string\n  /** 中文翻译（babeldoc）用的 OpenAI 兼容端点；不配则「生成中文版」不可用 */\n  translate?: {\n    baseUrl?: string\n    apiKey?: string\n    model?: string\n  }\n  /** 检索语义重排（Jev / TypeSafe）。凭据优先级：设置面板 > 此 YAML > 环境变量 TYPESAFE_API_KEY；都没有时退回纯关键词排序 */\n  typesafe?: RerankConfig\n  /** MinerU 解析后端（本地 legacy API + mineru.net v4 云端）。mode 默认 off，未配置时行为与改造前一致 */\n  mineru?: MineruConfig\n  /** 嵌入模型检索（OpenAI 兼容 /embeddings）。凭据优先级：设置面板 > 此 YAML > 环境变量 DSH_EMBED_API_KEY；\n      三者缺任一项时嵌入检索整体关闭（默认关闭），search_paper 退回纯关键词排序 */\n  embed?: EmbedConfig\n}\n\nconst MINERU_SOURCES = ['auto', 'pdfjs', 'mineru-local', 'mineru-cloud'] as const\nfunction sourceArg(v: unknown): SourceArg {\n  return (MINERU_SOURCES as readonly string[]).includes(v as string) ? (v as SourceArg) : 'auto'\n}\n\n/** 文献定位参数（三工具共用的 args 子集）。 */\ninterface LocateArgs {\n  path?: string\n  topic?: string\n  name?: string\n}\n\nconst locateParams = {\n  path: { type: 'string', description: 'PDF 绝对路径。与 topic+name 二选一。' },\n  topic: { type: 'string', description: '专题名（文献库一级目录）。' },\n  name: { type: 'string', description: '文献名（不带 .pdf 后缀）。省略时自动使用当前会话绑定的论文（伴读会话），只有查询别的论文才需要显式指定。' },\n} as const\n\nfunction locate(dataDir: string, args: LocateArgs, exec?: { agent?: { id?: string } }): PaperRef {\n  const refArgs: { path?: string; topic?: string; name?: string } = {}\n  if (args.path) refArgs.path = args.path\n  if (args.topic) refArgs.topic = args.topic\n  if (args.name) refArgs.name = args.name\n  // 未指定论文时回退到「当前会话绑定的论文」：伴读会话 id 形如 dpr-<base64url(topic/name)>-N，\n  // 工具执行上下文里的 agent.id 就是会话 id。直接在输入框提问（不经选中即问）时靠它定位。\n  if (!refArgs.path && !refArgs.name) {\n    const paper = paperFromSessionId(exec?.agent?.id)\n    if (paper) return resolvePaper(dataDir, { topic: paper.topic, name: paper.name })\n  }\n  return resolvePaper(dataDir, refArgs)\n}\n\n/**\n * 从伴读会话 id 反解论文（dpr-<base64url(topic/name)>[-N]）；非伴读会话返回 null。\n *\n * **必须 lastIndexOf('/')**：topic 是**路径**（嵌套子专题 `A/B`），只有论文名保证不含 `/`。\n * 用第一个 `/` 切会把 `A/B/P` 解成 topic=`A` / name=`B/P`（PR #8 评审必修 A：深度 ≥2 的论文\n * 「不带 name 提问」时全都报「找不到 B/P」）。扁平 `T/P` 与非法 id（无 `/`、空 name、末尾 `/`）语义不变。\n */\nexport function paperFromSessionId(sessionId: string | undefined): { topic: string; name: string } | null {\n  if (!sessionId?.startsWith('dpr-')) return null\n  try {\n    const body = sessionId.slice(4).replace(/-\\d+$/, '')\n    const decoded = Buffer.from(body, 'base64url').toString('utf8')\n    const sep = decoded.lastIndexOf('/')\n    if (sep <= 0 || sep === decoded.length - 1) return null\n    return { topic: decoded.slice(0, sep), name: decoded.slice(sep + 1) }\n  } catch {\n    return null\n  }\n}\n\n/** 某篇论文的阅读器链接基址（拼 &page=N 即跳转链接）；origin 未捕获到时为 null。 */\nfunction readerUrl(ref: PaperRef): string | null {\n  const o = readerOrigin()\n  if (!o) return null\n  return `${o}/paper-reader/?topic=${encodeURIComponent(ref.topic)}&name=${encodeURIComponent(ref.name)}`\n}\n\n/** 输出 schema 里的 readerUrl 字段声明（nullable：没有任何浏览器请求过时尚未捕获 origin）。 */\nconst readerUrlSchema = {\n  oneOf: [{ type: 'string' }, { type: 'null' }],\n  required: true,\n  description:\n    '阅读器链接基址。引用页码时在末尾拼 &page=N 生成跳转链接；要定位到具体段落再拼 &q=<该段落原文短引文，3~8个词，URL编码>，点击会高亮对应片段。为 null 时本次不带链接。',\n} as const\n\n/** render 文本尾部统一带出的链接基址行（preset 规定了用法，这里只暴露值）。 */\nconst readerUrlLine = (url: string | null) => (url ? `\\n阅读器链接基址：${url}` : '')\n\n/** 4 个 source 值的文案（§10.1：不得把 MinerU 结果误报成「本地提取」）。 */\nfunction sourceLabel(source: string): string {\n  switch (source) {\n    case 'cache': return '缓存复用'\n    case 'local': return '本地提取(pdf.js)'\n    case 'mineru-local': return '本地 MinerU 解析'\n    case 'mineru-cloud': return '云端 MinerU 解析'\n    default: return source\n  }\n}\n\nfunction producerLabel(producer: string): string {\n  switch (producer) {\n    case 'pdfjs': return 'pdf.js'\n    case 'mineru-local': return '本地 MinerU'\n    case 'mineru-cloud': return '云端 MinerU'\n    default: return producer\n  }\n}\n\nexport function registerTools(ctx: Context, config: PluginConfig) {\n  const dataDir = resolveDataDir(config.dataDir)\n  const shortlistSize = resolveShortlistSize(config.typesafe)\n\n  ctx.tools.register(defineTool({\n    name: 'list_papers',\n    description:\n      '列出文献库里的专题和文献。当用户提到某篇论文但你不知道它是否在库中、或用户问\"我有哪些论文\"时使用。',\n    parameters: {\n      topic: { type: 'string', description: '只看某个专题；省略则列出全部。' },\n    },\n    output: {\n      schema: {\n        type: 'object',\n        properties: {\n          dataDir: { type: 'string', required: true, description: '文献库根目录。' },\n          topics: {\n            type: 'array',\n            required: true,\n            items: { type: 'string' },\n            description: '专题列表。',\n          },\n          papers: {\n            type: 'array',\n            required: true,\n            items: { type: 'string', description: '形如 专题/文献名' },\n            description: '文献列表。',\n          },\n        },\n        additionalProperties: false,\n      },\n      render: (_args, value) => [\n        {\n          type: 'text',\n          text: value.papers.length === 0\n            ? `文献库为空（${value.dataDir}）。把 PDF 放进 <专题>/ 目录即可。`\n            : `文献库（${value.dataDir}）：\\n${value.papers.map((p) => `- ${p}`).join('\\n')}`,\n        },\n      ],\n    },\n    execute: async (args, exec) => {\n      const papers = listPapers(dataDir, args.topic).map((p) => `${p.topic}/${p.name}`)\n      return { dataDir, topics: listTopics(dataDir), papers }\n    },\n  }))\n\n  ctx.tools.register(defineTool({\n    name: 'transcribe_pdf',\n    description:\n      '把一篇 PDF 论文转录为纯文本（默认本地 pdf.js 提取，带页码索引），结果落盘缓存。' +\n      '可指定 source=mineru-local/mineru-cloud 改走 MinerU 解析后端（本地/云端，适合扫描件）。' +\n      '读一篇新论文的第一步：先转录，再用 search_paper 检索。已有缓存时秒回。',\n    parameters: {\n      ...locateParams,\n      force: { type: 'boolean', description: '忽略缓存重新转录。' },\n      source: {\n        type: 'string',\n        enum: ['auto', 'pdfjs', 'mineru-local', 'mineru-cloud'],\n        description:\n          '解析来源：auto=有缓存复用、无缓存按配置（默认 pdfjs）；pdfjs=本地 pdf.js 文本层；' +\n          'mineru-local=本地 MinerU API；mineru-cloud=mineru.net v4 云端。',\n      },\n    },\n    output: {\n      schema: {\n        type: 'object',\n        properties: {\n          paper: { type: 'string', required: true },\n          txtPath: { type: 'string', required: true, description: '转录文本路径。' },\n          chars: { type: 'integer', required: true },\n          pageCount: { type: 'integer', required: true },\n          hasPageIndex: { type: 'boolean', required: true, description: '是否有页码索引（检索结果能否带页码）。' },\n          source: { type: 'string', required: true, enum: ['cache', 'local', 'mineru-local', 'mineru-cloud'] },\n          producer: {\n            type: 'string',\n            required: true,\n            enum: ['legacy', 'pdfjs', 'mineru-local', 'mineru-cloud'],\n            description: '产出这份文本的引擎；legacy=旧缓存（缺来源标记，等价 pdfjs）。',\n          },\n          backend: {\n            oneOf: [{ type: 'string' }, { type: 'null' }],\n            required: true,\n            description: '实际 MinerU backend（本地）或 modelVersion（云端）；非 MinerU 为 null。',\n          },\n          readerUrl: readerUrlSchema,\n        },\n        additionalProperties: false,\n      },\n      render: (_args, value) => [\n        {\n          type: 'text',\n          text:\n            `已转录《${value.paper}》：${value.chars} 字符，${value.pageCount} 页` +\n            `（${sourceLabel(value.source)}${value.hasPageIndex ? '，含页码索引' : '，无页码索引'}）。` +\n            (value.source !== 'cache' && value.producer !== 'pdfjs' && value.producer !== 'legacy'\n              ? ` 引擎：${producerLabel(value.producer)}${value.backend ? `（${value.backend}）` : ''}。`\n              : '') +\n            `接下来可用 search_paper 检索具体内容。` +\n            readerUrlLine(value.readerUrl),\n        },\n      ],\n    },\n    execute: async (args, exec) => {\n      const ref = locate(dataDir, args, exec)\n      const mineru = await resolveMineruConfig(config.mineru)\n      const t = await transcribePaper(ref, { force: args.force === true, source: sourceArg(args.source), mineru })\n      return {\n        paper: `${ref.topic}/${ref.name}`,\n        txtPath: ref.txtPath,\n        chars: t.chars,\n        pageCount: t.pageCount,\n        hasPageIndex: t.pages.length > 0,\n        source: t.source,\n        producer: t.producer,\n        backend: t.backend,\n        readerUrl: readerUrl(ref),\n      }\n    },\n  }))\n\n  ctx.tools.register(defineTool({\n    name: 'search_paper',\n    description:\n      '在论文全文中按关键词检索相关片段，返回带页码的原文片段。' +\n      '当需要论文的具体内容（定义、算法步骤、章节细节、数据）时使用，基于检索到的原文回答并注明页码。' +\n      '关键词建议：用论文中的英文术语、章节号（如 \"Section 3.1\"）或概念名，不要用完整长句；找不到时换同义词或更短的词重试。' +\n      '论文未转录时会自动先转录。' +\n      '（配置了嵌入端点时额外做语义召回；未配置则纯关键词，与改造前一致）',\n    parameters: {\n      query: { type: 'string', required: true, description: '检索关键词，如 \"backup task\" 或 \"locality\"。' },\n      k: { type: 'integer', description: '返回片段数量，默认 5，最多 8。' },\n      ...locateParams,\n    },\n    output: {\n      schema: {\n        type: 'object',\n        properties: {\n          paper: { type: 'string', required: true },\n          query: { type: 'string', required: true },\n          totalChunks: { type: 'integer', required: true },\n          reranked: {\n            type: 'boolean',\n            required: true,\n            description: '返回片段是否经过语义重排（配置了 Jev/TypeSafe 凭据且候选充足时为 true）。',\n          },\n          compactQuery: {\n            oneOf: [{ type: 'string' }, { type: 'null' }],\n            required: true,\n            description:\n              '查询侧 LaTeX 紧凑写法（MinerU 来源论文才会一并匹配，如 Q_{t} → Q_t）；无需归一化时为 null。',\n          },\n          embedding: {\n            type: 'object',\n            required: true,\n            description: '嵌入语义召回的状态：未配置时 configured=false 且不影响结果；降级时 degraded 给出原因。',\n            properties: {\n              configured: { type: 'boolean', required: true },\n              used: { type: 'boolean', required: true },\n              fromCache: { type: 'boolean', required: true },\n              degraded: { oneOf: [{ type: 'string' }, { type: 'null' }], required: true },\n            },\n            additionalProperties: false,\n          },\n          hits: {\n            type: 'array',\n            required: true,\n            items: {\n              type: 'object',\n              properties: {\n                chunk: { type: 'integer', required: true },\n                page: {\n                  oneOf: [{ type: 'integer' }, { type: 'null' }],\n                  required: true,\n                  description: '片段起始页码；无页码索引时为 null。',\n                },\n                text: { type: 'string', required: true },\n              },\n              additionalProperties: false,\n            },\n          },\n          readerUrl: readerUrlSchema,\n        },\n        additionalProperties: false,\n      },\n      render: (_args, value) => {\n        const notes: string[] = []\n        if (value.compactQuery) {\n          notes.push(`（查询已按紧凑写法 \\`${value.compactQuery}\\` 一并匹配；原查询保留）`)\n        }\n        if (value.embedding.degraded) {\n          notes.push(`（嵌入检索不可用，已降级为纯关键词：${value.embedding.degraded}）`)\n        } else if (value.embedding.configured && value.embedding.used) {\n          notes.push(value.embedding.fromCache ? '（含嵌入语义召回；分块向量命中缓存）' : '（含嵌入语义召回）')\n        }\n        return [\n          {\n            type: 'text',\n            text:\n              formatHits(\n                value.hits.map((h) => ({\n                  chunk: { index: h.chunk, start: 0, end: 0, text: h.text },\n                  score: 0,\n                  page: h.page,\n                })),\n                value.totalChunks,\n                value.query,\n              ) +\n              (notes.length ? '\\n' + notes.join('\\n') : '') +\n              readerUrlLine(value.readerUrl),\n          },\n        ]\n      },\n    },\n    execute: async (args, exec) => {\n      const ref = locate(dataDir, args, exec)\n      let cached = await readTranscript(ref)\n      if (!cached) {\n        const mineru = await resolveMineruConfig(config.mineru)\n        await transcribePaper(ref, { source: 'auto', mineru })\n        cached = await readTranscript(ref)\n      }\n      if (!cached) throw new Error('转录失败，无法检索')\n      const chunks = chunkText(cached.text, 1500)\n      const k = Math.max(1, Math.min(args.k ?? 5, 8))\n      // 折叠项 1（查询侧 LaTeX 归一化）：投影侧只对 MinerU 产物做紧凑写法归一化，\n      // 因此查询侧的同名变体也**只对 MinerU 来源的论文**追加；原查询永远保留 →\n      // pdfjs/旧缓存论文既不丢命中也不引入新行为（与改造前逐字节一致）。\n      const producer = (await readTranscriptMeta(ref))?.producer ?? null\n      const variants = queryVariantsFor(producer, args.query)\n      const compact = variants.length > 1 ? variants[1]! : null\n      // 关键词快搜捞 shortlist（宽召回）→ 可选语义召回 → 既有重排 → top-k。\n      // 凭据每次现查（设置面板保存即生效）；未配置时三段都退回纯关键词，行为与改造前一致。\n      const rerankClient = await resolveRerankClient(config.typesafe)\n      const embedCfg = await resolveEmbedConfig(config.embed)\n      const wideRecall = Boolean(rerankClient) || embedCfg.enabled\n      const recallSize = wideRecall ? Math.max(k, shortlistSize) : k\n      let hits = searchChunksMulti(chunks, cached.pages, variants, recallSize)\n      // 嵌入召回：惰性（首次检索该论文才算）+ 缓存（<论文>.embeddings.json）；失败只影响本次召回。\n      const embedding = await embeddingRecallFor({\n        configured: embedCfg.enabled,\n        cachePath: embeddingsPathFor(ref.txtPath),\n        chunks,\n        pages: cached.pages,\n        query: args.query,\n        chunkSize: 1500,\n        limit: embedCfg.cfg.candidateSize ?? EMBED_DEFAULTS.candidateSize,\n        ...(embedCfg.enabled\n          ? {\n              req: {\n                baseUrl: embedCfg.cfg.baseUrl!,\n                apiKey: embedCfg.cfg.apiKey!,\n                model: embedCfg.cfg.model!,\n                ...(embedCfg.cfg.timeoutMs !== undefined ? { timeoutMs: embedCfg.cfg.timeoutMs } : {}),\n              },\n              ...(embedCfg.cfg.batchSize !== undefined ? { batchSize: embedCfg.cfg.batchSize } : {}),\n            }\n          : {}),\n      })\n      // 融合候选保持 RRF 相关性序直到最终选定 k 条，选定之后再恢复原文序展示（issue #13：\n      // 融合层若先按原文排序，下面 slice(0, k) 会按文档位置截取，把最相关的片段挤出去）。\n      const fused = embedding.hits.length > 0\n      if (fused) hits = fuseHybridCandidates(hits, embedding.hits, recallSize)\n      if (!wideRecall) hits = hits.slice(0, k)\n      if (embedding.degraded) {\n        console.warn('[dsh-paper-reader] 嵌入检索降级为纯关键词:', embedding.degraded)\n      }\n      let reranked = false\n      if (rerankClient && hits.length > k) {\n        try {\n          hits = await rerankHits(rerankClient, args.query, hits, k, config.typesafe?.deadlineMs ?? 1500)\n          reranked = true\n        } catch (e) {\n          // 超预算/网络/鉴权任何失败都退回关键词 top-k（结果已算好，零成本降级）\n          console.warn('[dsh-paper-reader] 检索重排失败，退回关键词排序:', e)\n          hits = hits.slice(0, k)\n        }\n      }\n      if (!reranked) hits = hits.slice(0, k)\n      // 展示序：融合路径在**选定 top-k 之后**恢复原文顺序（重排成功路径在 rerankHits 内部已做）；\n      // 纯关键词路径维持相关性序不变（既有行为，未配置嵌入/重排时逐字节一致）。\n      if (fused && !reranked) hits = hits.slice().sort((a, b) => a.chunk.index - b.chunk.index)\n      return {\n        paper: `${ref.topic}/${ref.name}`,\n        query: args.query,\n        totalChunks: chunks.length,\n        hits: hits.map((h) => ({ chunk: h.chunk.index, page: h.page, text: h.chunk.text })),\n        reranked,\n        compactQuery: compact,\n        embedding: {\n          configured: embedding.configured,\n          used: embedding.used,\n          fromCache: embedding.fromCache,\n          degraded: embedding.degraded,\n        },\n        readerUrl: readerUrl(ref),\n      }\n    },\n  }))\n\n  ctx.tools.register(defineTool({\n    name: 'study_progress',\n    description:\n      '读取一篇论文的学习档案：分步阅读计划（每步状态）和历次检验成绩。' +\n      '开始伴读、或用户想继续学习/查看进度时先调用；没有记录时返回空，此时应制定计划（study_update 的 set_plan）。',\n    parameters: { ...locateParams },\n    output: {\n      schema: {\n        type: 'object',\n        properties: {\n          paper: { type: 'string', required: true },\n          hasRecord: { type: 'boolean', required: true },\n          plan: {\n            type: 'array',\n            required: true,\n            items: {\n              type: 'object',\n              properties: {\n                id: { type: 'integer', required: true },\n                title: { type: 'string', required: true },\n                status: { type: 'string', required: true, enum: ['pending', 'current', 'done'] },\n                note: { type: 'string' },\n              },\n              additionalProperties: false,\n            },\n          },\n          quizzes: {\n            type: 'array',\n            required: true,\n            items: {\n              type: 'object',\n              properties: {\n                time: { type: 'string', required: true },\n                score: { type: 'integer', required: true },\n                total: { type: 'integer', required: true },\n                summary: { type: 'string' },\n              },\n              additionalProperties: false,\n            },\n          },\n          readerUrl: readerUrlSchema,\n        },\n        additionalProperties: false,\n      },\n      render: (_args, value) => [\n        {\n          type: 'text',\n          text: `《${value.paper}》学习档案：\\n` + formatStudy(\n            value.hasRecord ? { paper: value.paper, plan: value.plan, quizzes: value.quizzes } : null,\n          ) + readerUrlLine(value.readerUrl),\n        },\n      ],\n    },\n    execute: async (args, exec) => {\n      const ref = locate(dataDir, args, exec)\n      const record = await readStudy(ref)\n      return {\n        paper: `${ref.topic}/${ref.name}`,\n        hasRecord: record !== null,\n        plan: record?.plan ?? [],\n        quizzes: record?.quizzes ?? [],\n        readerUrl: readerUrl(ref),\n      }\n    },\n  }))\n\n  ctx.tools.register(defineTool({\n    name: 'study_update',\n    description:\n      '更新一篇论文的学习档案（老师用）：' +\n      'set_plan=制定阅读计划（steps 为 3~6 个分步标题，会重置计划但保留历史成绩）；' +\n      'complete_step=当前步检查已通过后才可记录完成（step_id + 可选 note 点评，自动推进到下一步；未通过不得调用）；' +\n      'record_quiz=记录一次检验成绩（score/total + 可选 summary 薄弱点小结）。',\n    parameters: {\n      action: { type: 'string', required: true, enum: ['set_plan', 'complete_step', 'record_quiz'] },\n      steps: { type: 'array', items: { type: 'string' }, description: 'set_plan 用：分步标题列表，如 \"读摘要与引言（第 1 页），说出论文要解决的问题\"。' },\n      step_id: { type: 'integer', description: 'complete_step 用：完成的步骤号。' },\n      note: { type: 'string', description: 'complete_step 用：对学生这一步表现的点评。' },\n      score: { type: 'integer', description: 'record_quiz 用：得分。' },\n      total: { type: 'integer', description: 'record_quiz 用：满分。' },\n      summary: { type: 'string', description: 'record_quiz 用：本次检验小结（考点/薄弱点）。' },\n      ...locateParams,\n    },\n    output: {\n      schema: {\n        type: 'object',\n        properties: {\n          paper: { type: 'string', required: true },\n          summary: { type: 'string', required: true, description: '更新后的档案摘要。' },\n        },\n        additionalProperties: false,\n      },\n      render: (_args, value) => [{ type: 'text', text: `《${value.paper}》档案已更新：\\n${value.summary}` }],\n    },\n    execute: async (args, exec) => {\n      const ref = locate(dataDir, args, exec)\n      let record\n      if (args.action === 'set_plan') {\n        if (!args.steps?.length) throw new Error('set_plan 需要 steps')\n        record = await setPlan(ref, args.steps)\n      } else if (args.action === 'complete_step') {\n        if (!args.step_id) throw new Error('complete_step 需要 step_id')\n        record = await completeStep(ref, args.step_id, args.note)\n      } else {\n        if (args.score === undefined || args.total === undefined) throw new Error('record_quiz 需要 score 和 total')\n        record = await recordQuiz(ref, args.score, args.total, args.summary)\n      }\n      return { paper: `${ref.topic}/${ref.name}`, summary: formatStudy(record) }\n    },\n  }))\n}\n"
    },
    {
      "path": "src/transcribe.ts",
      "content": "// transcribe.ts — PDF 转录（纯函数，不依赖 Cordis）。\n//\n// 三级策略：\n//  1. 缓存：.txt 已存在直接复用（来源由 .transcript.json 标记；缺失 = legacy，等价 pdfjs）\n//  2. 快路径：pdfjs-dist（pdf.js）本地提取文本层（文本型 PDF 毫秒级，纯 Node，无需 Python）\n//  3. MinerU 后端：本地 legacy API / mineru.net v4 云端（扫描件/OCR 兜底，见 mineru.ts）\n//\n// 产出仍然是同一套 .txt + .pages.json（page 从 1 起），另加 .transcript.json（来源标记）\n// 与 MinerU 富产物 .mineru.md/.mineru.json（Markdown + content_list，供人工核对）。\n\nimport { readFile, writeFile, rename, rm } from 'node:fs/promises'\nimport { statSync } from 'node:fs'\nimport { randomUUID } from 'node:crypto'\nimport type { PaperRef } from './library.ts'\nimport { parseCloudMineru, parseLocalMineru, MineruError, type MineruParseResult } from './mineru.ts'\nimport { MINERU_DEFAULTS, type MineruConfig, type ResolvedMineru } from './mineru-config.ts'\n\nexport interface PageSpan {\n  page: number\n  start: number\n  end: number\n}\n\n/** 工具/HTTP 出参 source：本次调用做了什么（cache 复用 / local=pdfjs / mineru-*）。 */\nexport type TranscriptSource = 'cache' | 'local' | 'mineru-local' | 'mineru-cloud'\n/** 文本产自哪个引擎（写进 .transcript.json）。 */\nexport type Producer = 'legacy' | 'pdfjs' | 'mineru-local' | 'mineru-cloud'\n/** 工具/HTTP 入参 source：auto=按配置/缓存决定，其余为显式来源。 */\nexport type SourceArg = 'auto' | 'pdfjs' | 'mineru-local' | 'mineru-cloud'\n\nexport interface Transcript {\n  text: string\n  pages: PageSpan[]\n  pageCount: number\n  chars: number\n  /** cache=复用缓存, local=本次本地 pdfjs 提取, mineru-local/mineru-cloud=本次 MinerU 解析 */\n  source: TranscriptSource\n  /** 产出这份文本的引擎（旧缓存缺标记归类 legacy） */\n  producer: Producer\n  /** 本地 = MinerU backend 值；云端 = modelVersion；非 MinerU = null */\n  backend: string | null\n}\n\n/** 扫描件/文本过短信号：文本层过少，上层据此决定 MinerU 兜底。 */\nexport class ShortTextError extends Error {\n  constructor(message: string) {\n    super(message)\n    // 显式设 name：上层可据此区分（否则 err.name 只是 'Error'，见验证报告 O3）\n    this.name = 'ShortTextError'\n  }\n}\n\n/** 扫描件信号（pdfjs 提取内部使用）。 */\nexport class ScannedPdfError extends Error {}\n\nfunction isRecord(v: unknown): v is Record<string, unknown> {\n  return typeof v === 'object' && v !== null && !Array.isArray(v)\n}\n\n// ---- 以下为 PyMuPDF 版清洗规则的逐条 TS 移植 ----\n\nconst LIGATURES: [string, string][] = [\n  ['ﬁ', 'fi'], ['ﬂ', 'fl'], ['ﬀ', 'ff'], ['ﬃ', 'ffi'], ['ﬄ', 'ffl'], ['ﬅ', 'st'],\n]\nfunction ligature(s: string): string {\n  for (const [k, v] of LIGATURES) s = s.replaceAll(k, v)\n  return s\n}\n\n/** 页眉页脚归一化：去数字标点（对应 Python re.sub(r'[\\d\\W]+','',l).lower()，保留 unicode 字母）。 */\nfunction norm(l: string): string {\n  return l.replace(/[^\\p{L}_]/gu, '').toLowerCase()\n}\n\nconst SENT_END = /[.!?:;][\"'”’)\\]]*$/\n\ninterface RawExtract {\n  pageCount: number\n  chars: number\n  text: string\n  pages: PageSpan[]\n}\n\n/**\n * pdfjs 提取文本层 → 剔页眉页脚 → 清洗 → 带偏移拼页。\n * 扫描件（文本过少）抛 ScannedPdfError，交给上层决定兜底策略。\n * pdfjs-dist 体积不小，动态 import，首次转录时才加载。\n */\nasync function extractWithPdfjs(pdfPath: string): Promise<RawExtract> {\n  const { getDocument } = await import('pdfjs-dist/legacy/build/pdf.mjs')\n  const data = new Uint8Array(await readFile(pdfPath))\n  const loadingTask = getDocument({ data, disableFontFace: true, verbosity: 0 })\n  const doc = await loadingTask.promise\n  try {\n    // 每页拼行：getTextContent 的 hasEOL 标记行尾，等价于 PyMuPDF get_text().splitlines()\n    const rawPages: string[][] = []\n    for (let i = 1; i <= doc.numPages; i++) {\n      const page = await doc.getPage(i)\n      const tc = await page.getTextContent()\n      const lines: string[] = []\n      let cur = ''\n      for (const item of tc.items) {\n        if (typeof (item as { str?: unknown }).str !== 'string') continue\n        cur += (item as { str: string }).str\n        if ((item as { hasEOL?: boolean }).hasEOL) {\n          lines.push(cur.trim())\n          cur = ''\n        }\n      }\n      if (cur.trim()) lines.push(cur.trim())\n      rawPages.push(lines.filter((l) => l))\n      page.cleanup()\n    }\n\n    // 页眉页脚识别：页首 2 行/页尾 3 行归一化（去数字标点），\n    // 在 >=1/5 页面边缘反复出现即剔除；只剔边缘行，正文相同行不受影响。\n    const thresh = Math.max(3, Math.floor(rawPages.length / 5))\n    const edge = new Map<string, number>()\n    for (const p of rawPages) {\n      for (const l of [...p.slice(0, 2), ...p.slice(-3)]) {\n        const n = norm(l)\n        edge.set(n, (edge.get(n) ?? 0) + 1)\n      }\n    }\n    const bad = new Set([...edge].filter(([, n]) => n >= thresh).map(([l]) => l))\n\n    const pageTexts: string[] = []\n    for (const p of rawPages) {\n      while (p.length && bad.has(norm(p[0]!))) p.shift()\n      while (p.length && bad.has(norm(p[p.length - 1]!))) p.pop()\n      let t = p.join('\\n')\n      t = ligature(t)\n      t = t.replace(/(\\w)-\\n(\\w)/g, '$1$2') // 页内断词愈合\n      pageTexts.push(t.trim())\n    }\n\n    const total = pageTexts.reduce((s, t) => s + t.length, 0)\n    if (total < 100 * Math.max(1, doc.numPages)) throw new ScannedPdfError()\n\n    // 段落重排拼页：PDF 分页会把一个句子拆到相邻两页（页眉页脚剔除后就挨在一起）。\n    // 上一页不以句末标点结束、且下一页以小写字母开头 → 同句延续，用空格衔接；\n    // 该页的偏移区间只覆盖它自己的文字（跨页句引用起始页）。\n    let buf = ''\n    const spans: PageSpan[] = []\n    for (let i = 0; i < pageTexts.length; i++) {\n      const t = pageTexts[i]!\n      if (!t) continue\n      if (!buf) {\n        spans.push({ page: i + 1, start: 0, end: t.length })\n        buf = t\n        continue\n      }\n      let start: number\n      if (!SENT_END.test(buf) && /^\\p{Ll}/u.test(t)) {\n        buf = buf.replace(/[ \\n]+$/, '')\n        start = buf.length + 1\n        buf = buf + ' ' + t\n      } else {\n        start = buf.length + 2\n        buf = buf + '\\n\\n' + t\n      }\n      spans.push({ page: i + 1, start, end: buf.length })\n    }\n\n    return { pageCount: doc.numPages, chars: buf.length, text: buf, pages: spans }\n  } finally {\n    await loadingTask.destroy()\n  }\n}\n\n/** 来源入参 → 目标 producer；auto 按配置 mode 决定。 */\nfunction producerForSource(source: SourceArg): Producer {\n  if (source === 'pdfjs') return 'pdfjs'\n  if (source === 'mineru-local') return 'mineru-local'\n  if (source === 'mineru-cloud') return 'mineru-cloud'\n  throw new Error(`内部错误：未知 source ${source}`)\n}\n\nfunction producerForMode(mode: MineruConfig['mode']): Producer {\n  if (mode === 'local') return 'mineru-local'\n  if (mode === 'cloud') return 'mineru-cloud'\n  return 'pdfjs'\n}\n\n/** 缓存命中判定：source='pdfjs' 命中 legacy/pdfjs；显式 mineru-* 只命中同源。 */\nfunction producerMatches(requested: Producer, actual: Producer): boolean {\n  if (requested === 'pdfjs') return actual === 'pdfjs' || actual === 'legacy'\n  return requested === actual\n}\n\n/** 读 .transcript.json 的来源标记；缺失/损坏/形状不对返回 null（归类 legacy）。 */\nexport async function readTranscriptMeta(ref: PaperRef): Promise<{ producer: Producer; backend: string | null } | null> {\n  try {\n    const raw = JSON.parse(await readFile(ref.transcriptPath, 'utf8')) as unknown\n    if (!isRecord(raw)) return null\n    const producer = raw['producer']\n    if (producer !== 'pdfjs' && producer !== 'mineru-local' && producer !== 'mineru-cloud') return null\n    const engine = isRecord(raw['engine']) ? raw['engine'] : null\n    let backend: string | null = null\n    if (engine) {\n      if (typeof engine['backend'] === 'string') backend = engine['backend']\n      else if (typeof engine['modelVersion'] === 'string') backend = engine['modelVersion']\n    }\n    return { producer, backend }\n  } catch {\n    return null\n  }\n}\n\ninterface CachedTranscript {\n  text: string\n  pages: PageSpan[] | null\n  producer: Producer\n  backend: string | null\n  /** .transcript.json.text.bytes 与 .txt 实际大小不一致 → 判定损坏（§7.5.3） */\n  corrupted: boolean\n}\n\n/** 读现有缓存 + 来源标记；txt 缺失返回 null。 */\nasync function readCached(ref: PaperRef): Promise<CachedTranscript | null> {\n  let text: string\n  try {\n    text = await readFile(ref.txtPath, 'utf8')\n  } catch {\n    return null\n  }\n  const pages = await readPages(ref)\n  let producer: Producer = 'legacy'\n  let backend: string | null = null\n  let corrupted = false\n  try {\n    const raw = JSON.parse(await readFile(ref.transcriptPath, 'utf8')) as unknown\n    if (isRecord(raw)) {\n      const p = raw['producer']\n      if (p === 'pdfjs' || p === 'mineru-local' || p === 'mineru-cloud') producer = p\n      const engine = isRecord(raw['engine']) ? raw['engine'] : null\n      if (engine) {\n        if (typeof engine['backend'] === 'string') backend = engine['backend']\n        else if (typeof engine['modelVersion'] === 'string') backend = engine['modelVersion']\n      }\n      const tb = isRecord(raw['text']) ? raw['text']['bytes'] : undefined\n      if (typeof tb === 'number' && tb !== Buffer.byteLength(text, 'utf8')) corrupted = true\n    }\n  } catch { /* transcript.json 缺失/损坏 → legacy，不判损坏 */ }\n  return { text, pages, producer, backend, corrupted }\n}\n\n/**\n * 转录一篇文献：缓存优先（来源语义见 §8），否则按 source/mode 选引擎解析并落盘。\n * @param opts.source 入参来源（默认 auto）；auto 命中缓存即复用，无缓存按配置 mode。\n * @param opts.mineru 已解析的 MinerU 配置（缺省 mode=off，行为与改造前一致）。\n */\nexport async function transcribePaper(\n  ref: PaperRef,\n  opts: { force?: boolean; source?: SourceArg; mineru?: ResolvedMineru } = {},\n): Promise<Transcript> {\n  const source = opts.source ?? 'auto'\n  const mineru: ResolvedMineru = opts.mineru ?? { config: MINERU_DEFAULTS, source: 'none' }\n  const force = opts.force === true\n  // auto 无缓存时按配置 mode 决定目标引擎；显式 source 优先于 mode（mode=off 不阻止显式来源）\n  const targetProducer = source === 'auto' ? producerForMode(mineru.config.mode) : producerForSource(source)\n\n  if (!force) {\n    const cached = await readCached(ref)\n    // 沿用 v1.2.0 的「缓存有效」门槛（.txt 字节数 > 1000）：过短的缓存视为无效，重新解析。\n    const valid = cached !== null && !cached.corrupted && Buffer.byteLength(cached.text, 'utf8') > 1000\n    if (valid) {\n      const hit = source === 'auto' ? true : producerMatches(targetProducer, cached!.producer)\n      if (hit) {\n        let pages = cached.pages\n        // 兼容升级：pdfqa 时代的缓存只有 .txt 没有页码索引。重新提取生成页码索引；\n        // 新旧文本长度接近才覆盖（视觉转录的扫描件缓存不容侵犯）。\n        if (!pages && cached.producer === 'legacy') {\n          const upgraded = await tryUpgradePageIndex(ref, cached.text.length)\n          if (upgraded) {\n            pages = upgraded.pages\n            return { text: upgraded.text, pages, pageCount: pages.length, chars: upgraded.text.length, source: 'cache', producer: 'legacy', backend: null }\n          }\n        }\n        return {\n          text: cached.text,\n          pages: pages ?? [],\n          pageCount: pages?.length ?? 0,\n          chars: cached.text.length,\n          source: 'cache',\n          producer: cached.producer,\n          backend: cached.backend,\n        }\n      }\n      // 显式 source 与缓存 producer 不命中 → 判定 stale，重新解析并覆盖（§8）\n    }\n  }\n\n  // 重新解析\n  if (targetProducer === 'pdfjs') {\n    return await parseAndStorePdfjs(ref, mineru)\n  }\n  if (targetProducer === 'mineru-local') {\n    return await parseAndStoreMineru(ref, 'mineru-local', mineru.config)\n  }\n  return await parseAndStoreMineru(ref, 'mineru-cloud', mineru.config)\n}\n\n/** 本地提取（不落盘）。文本过少抛 ShortTextError，供上层做 MinerU 兜底。 */\nasync function extractLocal(pdfPath: string): Promise<Transcript> {\n  let data: RawExtract\n  try {\n    data = await extractWithPdfjs(pdfPath)\n  } catch (err) {\n    if (err instanceof ScannedPdfError) {\n      // 文案只描述「发生了什么」，可执行指引由上层按 MinerU 是否启用补充（见 parseAndStorePdfjs）。\n      // 不再声称「视觉转录兜底尚未实现」——1.3.0 起 MinerU 就是那个兜底（验证报告 O2）。\n      throw new ShortTextError('本地提取的文本过少，该 PDF 可能是扫描件（没有可用文本层）。')\n    }\n    throw new Error(`PDF 文本提取失败：${err instanceof Error ? err.message : String(err)}`)\n  }\n  if (data.text.length < 1000) {\n    throw new ShortTextError(`转录结果过短(${data.text.length} 字符)，疑似失败，请重试`)\n  }\n  return { text: data.text, pages: data.pages, pageCount: data.pageCount, chars: data.chars, source: 'local', producer: 'pdfjs', backend: null }\n}\n\n/**\n * 原子写的临时文件路径：pid + 随机后缀。\n * 只用 pid 时，同一进程内并发写同一目标会撞名并交叉覆盖多文件提交序列（验证报告 F6）。\n */\nexport function atomicTempPath(path: string): string {\n  return `${path}.tmp-${process.pid}-${randomUUID().slice(0, 8)}`