      "content": "<!DOCTYPE html>\n<html lang=\"zh\" data-dpr-pdf=\"pending\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>论文伴读 · dsh-paper-reader</title>\n<!-- pdf.js 6.x 本地 vendor（不再走 CDN）：3.11 的字体解析对 babeldoc 嵌入的 CID 字体会回退成黑体。\n     不用 <script type=\"module\">：module 是 defer 语义（整页解析完 + 458KB 拉取编译完才执行），\n     而底部经典脚本在解析期就开跑 bootstrap()，库里有论文时先到 loadPdf，此刻 window.pdfjsLib\n     还没就绪 → \"pdfjsLib is not defined\"。改为经典脚本里动态 import()（见 ensurePdfjs），顺序有保证。 -->\n<!-- KaTeX 0.16.22 本地 vendor（数学渲染；论文伴读是**离线场景**，绝不引 CDN）。\n     经典脚本：页面解析期同步设置 window.katex；缺失时渲染路径会**降级**为原始 LaTeX（见 trRenderBody）。\n     体积与来源见 reader/vendor/katex.NOTICE.md。 -->\n<link rel=\"stylesheet\" href=\"/paper-reader/vendor/katex.min.css\">\n<script src=\"/paper-reader/vendor/katex.min.js\"></script>\n<style>\n  :root {\n    --bg: #f6f7f9; --panel: #ffffff; --border: #e2e5ea; --text: #24292f;\n    --text-2: #656d76; --accent: #0969da; --accent-soft: rgba(9,105,218,.12);\n    --hl: rgba(255, 196, 0, .55);\n  }\n  * { box-sizing: border-box; }\n  html, body { margin: 0; height: 100%; }\n  body { font: 14px/1.6 -apple-system, \"SF Pro\", \"PingFang SC\", \"Helvetica Neue\", sans-serif; background: var(--bg); color: var(--text); display: flex; flex-direction: column; }\n\n  /* ---------- 顶栏 ----------\n     flex-wrap —— 窄列（rightbar 可拖到 ~300px）下按钮放不下时换行到第二行，\n     而不是向右溢出被 iframe 裁掉（v1.3.2 前的坑：＋/适宽 被挤出可视区，用户实测） */\n  #bar { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; row-gap: 6px; padding: 8px 12px; background: var(--panel); border-bottom: 1px solid var(--border); flex: none; }\n  #bar button { font: inherit; }\n  /* flex:none —— 列被拖窄时按钮不许被压缩（否则文字竖排、按钮变窄条） */\n  /* inline-flex + 固定高：图标/文字统一垂直居中，按钮高度不再随各家字体字形漂移 */\n  .tbtn { flex: none; display: inline-flex; align-items: center; justify-content: center; gap: 5px; height: 28px; padding: 0 9px; border: 1px solid var(--border); border-radius: 6px; background: var(--panel); color: var(--text); cursor: pointer; }\n  .tbtn:hover { background: var(--bg); }\n  .tbtn.active { background: var(--accent-soft); border-color: var(--accent); color: var(--accent); }\n  .tbtn:disabled { opacity: .45; cursor: default; }\n  /* 顶栏收纳：分组分隔线 / 弹性空隙 / 被菜单替代的按钮隐藏（!important 盖过状态机的 style.display）/\n     弹出菜单本体（绝对定位于 #bar） */\n  #bar { position: relative; }\n  .bar-sep { flex: none; width: 1px; height: 16px; background: var(--border); }\n  .bar-spacer { flex: 1 1 auto; }\n  .tucked { display: none !important; }\n  .bar-menu { position: absolute; z-index: 60; min-width: 208px; padding: 4px;\n    display: flex; flex-direction: column; background: var(--panel); border: 1px solid var(--border);\n    border-radius: 8px; box-shadow: 0 8px 28px rgba(0,0,0,.22); }\n  .bar-menu[hidden] { display: none !important; }\n  .bar-menu button { all: unset; cursor: pointer; padding: 6px 10px; border-radius: 6px;\n    font-size: 12.5px; color: var(--text); }\n  .bar-menu button:hover { background: var(--bg); }\n  .bar-menu button.active { color: var(--accent); font-weight: 600; }\n  .bar-menu button:disabled { opacity: .45; cursor: default; }\n  .bar-menu hr { border: none; border-top: 1px solid var(--border); margin: 4px 6px; }\n  /* 统一 SVG 图标：stroke=currentColor，active/disabled 的变色自动继承到图标 */\n  .tbtn svg.ic { width: 16px; height: 16px; flex: none; }\n  .tbtn svg.spin { transform-origin: center; animation: dpr-spin 1s linear infinite; }\n  @keyframes dpr-spin { to { transform: rotate(360deg); } }\n  @media (prefers-reduced-motion: reduce) { .tbtn svg.spin { animation-duration: 2.4s; } }\n  #zoom-label { flex: none; min-width: 44px; text-align: center; color: var(--text-2); }\n  #bar .spacer { flex: 1; }\n  /* min-width:0 —— flex 项默认 min-width:auto 会拒绝收缩，空间不够时转而去挤按钮；\n     让标题自己截断（已有 ellipsis），按钮才能保持原样 */\n  #status { flex: 0 1 auto; min-width: 0; color: var(--text-2); font-size: 12.5px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }\n  /* 翻译进度条（只在生成中文版时出现）：细长条 + 阶段文字，宽度跟着 babeldoc 的 overall 走 */\n  #zh-prog { flex: 0 1 auto; min-width: 0; max-width: 46%; display: inline-flex; align-items: center; gap: 7px; }\n  #zh-prog[hidden] { display: none; }\n  #zh-prog .track { position: relative; flex: 1 1 auto; min-width: 48px; height: 6px; border-radius: 3px; background: var(--border); overflow: hidden; }\n  #zh-prog .fill { position: absolute; top: 0; bottom: 0; left: 0; width: 0; border-radius: 3px; background: var(--accent); transition: width .35s ease; }\n  #zh-prog .txt { flex: none; font-size: 12px; color: var(--text-2); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }\n  @media (prefers-reduced-motion: reduce) { #zh-prog .fill { transition: none; } }\n  /* PDF 文件路径：可点的只读文本（点击复制）。⚠️ 必须可收缩（flex:0 1 auto + min-width:0）——\n     它是最长的内容项，窄列时先让位给按钮、自己截断（title 悬停始终有完整路径），\n     曾经 max-width:34% + flex:none 在窄列把 ＋/适宽 挤出可视区（用户实测） */\n  #pdf-path { flex: 0 1 auto; min-width: 0; max-width: 34%; padding: 0; border: none; background: none; color: var(--text-2); font-size: 11.5px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; cursor: pointer; }\n  #pdf-path:hover { color: var(--accent); }\n  /* 窄列（<560px）：版本号让位——它只是排障辅助信息 */\n  @media (max-width: 560px) { #ver { display: none; } }\n\n  /* ---------- PDF 区 ---------- */\n  /* #split-wrap 是分屏（模式 B）的两列行容器：非分屏时只有原文列，行为与改造前一致。\n     #pdf-pane 从 #main 的直接子节点变成它的子节点——#main 的 flex 语义不变。 */\n  #main { display: flex; flex: 1; min-height: 0; position: relative; } /* relative：公式面板绝对定位的锚 */\n  #split-wrap { display: flex; flex-direction: row; gap: 8px; flex: 1; min-width: 0; position: relative; }\n  #pdf-pane { flex: 1 1 0; min-width: 0; overflow: auto; padding: 16px; }\n  /* 中文列（仅分屏出现）：与原文列同权重、各自滚动 */\n  #pdf-pane-zh { flex: 1 1 0; min-width: 0; overflow: auto; padding: 16px; display: none; }\n  #split-wrap.on > #pdf-pane-zh { display: block; }\n  /* 预渲染译文：临时让隐藏列拥有完整布局（visibility:hidden，不闪屏），供离屏渲染量宽/挂载 */\n  #split-wrap.preloading > #pdf-pane-zh {\n    display: block; position: absolute; inset: 0; visibility: hidden; pointer-events: none;\n  }\n  .pane-label { display: none; position: sticky; top: -16px; z-index: 3; background: var(--bg); color: var(--text-2);\n    font-size: 12px; font-weight: 600; padding: 2px 0 6px; }\n  #split-wrap.on .pane-label { display: block; }\n  /* safe center：页宽超过视口时退回左对齐——普通 center 会让左右同时溢出且左侧滚不到 */\n  #pdf-pages { display: flex; flex-direction: column; align-items: safe center; gap: 14px; }\n  #pdf-pages-zh { display: flex; flex-direction: column; align-items: safe center; gap: 14px; }\n  /* 翻页模式：单页垂直居中（safe center 同理，放大后顶部仍可滚到） */\n  #pdf-pages.paged, #pdf-pages-zh.paged { min-height: 100%; justify-content: safe center; gap: 0; }\n\n  /* ---------- 翻页控件 ---------- */\n  /* 翻页条：阅读区底部悬浮居中（#main 的 absolute 锚，不随内容滚动）；\n     半透明 + 毛玻璃，hover 加实避免长时间挡字；JS 的 display:''/none 契约不变 */\n  #pager { position: absolute; bottom: 14px; left: 50%; transform: translateX(-50%); z-index: 30;\n    display: flex; align-items: center; gap: 4px; flex: none; padding: 3px 6px;\n    background: color-mix(in srgb, var(--panel) 88%, transparent); backdrop-filter: blur(6px);\n    border: 1px solid var(--border); border-radius: 999px; box-shadow: 0 3px 14px rgba(0,0,0,.16); }\n  #pager:hover { background: var(--panel); }\n  /* 数字居中：text-align:right 会让单页码贴右框边、左侧空一块；\n     上 padding 多 1px —— 数字无下伸部，光字心本就偏高，对称内边距看起来反而偏上 */\n  #page-input { width: 3.5em; padding: 4px 6px 2px; border: 1px solid var(--border); border-radius: 6px; background: var(--panel); color: var(--text); font: inherit; font-size: 12.5px; line-height: 20px; text-align: center; }\n  #page-total { flex: none; color: var(--text-2); font-size: 12px; white-space: nowrap; }\n  /* 插件版本号（host 注入；未被替换时隐藏——比如旧 host 配新页面的错位场景） */\n  #ver { flex: none; font-size: 10.5px; color: var(--text-2); opacity: .65; user-select: none; }\n  .page { position: relative; background: #fff; box-shadow: 0 1px 4px rgba(0,0,0,.18); }\n  /* 懒渲染占位：只保留页面尺寸，真正滚到附近才铺 canvas/TextLayer */\n  .page.lazy::after {\n    content: '加载中…'; position: absolute; inset: 0; display: flex; align-items: center; justify-content: center;\n    color: var(--text-2); font-size: 12px; opacity: .45; pointer-events: none;\n  }\n  .page.flash { outline: 3px solid var(--hl); outline-offset: 2px; transition: outline .15s; }\n  /* textLayer CSS 必须是 pdf.js 6.x 官方规则的子集：TextLayer 只往 span 写 --font-height/--scale-x/--rotate\n     变量，font-size 和 transform 全靠这里的 calc 表达式撑开；缺了的话 span 会按 body 字号渲染，\n     盒子与 canvas 字形错位 —— 表现为选中高亮缺字符。--scale-factor 由 JS 在渲染时写入 */\n  .textLayer {\n    position: absolute; inset: 0; overflow: clip; line-height: 1; text-align: initial;\n    letter-spacing: normal; word-spacing: normal; text-size-adjust: none;\n    forced-color-adjust: none; transform-origin: 0 0; caret-color: CanvasText; z-index: 0;\n    --total-scale-factor: calc(var(--scale-factor, 1) * var(--user-unit, 1));\n    --text-scale-factor: calc(var(--total-scale-factor) * var(--min-font-size, 1));\n    --min-font-size-inv: calc(1 / var(--min-font-size, 1));\n    --scale-round-x: 1px; --scale-round-y: 1px;\n  }\n  .textLayer :is(span, br) { color: transparent; position: absolute; white-space: pre; cursor: text; transform-origin: 0 0; user-select: text; }\n  .textLayer > :not(.markedContent),\n  .textLayer .markedContent span:not(.markedContent) {\n    z-index: 1;\n    --font-height: 0;\n    font-size: calc(var(--text-scale-factor) * var(--font-height));\n    --scale-x: 1; --rotate: 0deg;\n    transform: rotate(var(--rotate)) scaleX(var(--scale-x)) scale(var(--min-font-size-inv));\n  }\n  .textLayer .markedContent { display: contents; }\n  .textLayer ::selection { background: rgba(22,93,255,.3); }\n  .textLayer br::selection { background: transparent; }\n  /* 跳转链接的片段高亮（&q= 引文定位）：常驻不淡出，用户在阅读器里任意点一下即消\n     （同代码编辑器的选中高亮语义：消失由用户触发，不由计时器触发） */\n  .textLayer span.dpr-hl { background: rgba(255,196,0,.45); border-radius: 2px; }\n  #empty { margin: 60px auto; color: var(--text-2); text-align: center; max-width: 420px; }\n\n  /* ---------- 公式引用（MinerU bbox 热区 + 列表面板）----------\n     契约 §1.3/§1.4：热区**不用** pointer-events:auto 的覆盖层——那会夺走 textLayer 的\n     mousedown/拖拽，破坏既有划词提问。这里 .eqLayer 只负责画描边（pointer-events:none），\n     命中判定在 JS 里按坐标算。 */\n  .eqLayer { position: absolute; inset: 0; pointer-events: none; z-index: 2; }\n  .eq-box { position: absolute; border-radius: 3px; }\n  .eq-box.hover { outline: 1.5px dashed rgba(9,105,218,.85); background: rgba(9,105,218,.07); }\n  .eq-box.hit { outline: 2px solid rgba(255,140,0,.9); background: rgba(255,196,0,.16); }\n  #eq-panel { position: absolute; top: 0; right: 0; bottom: 0; width: min(320px, 88%); display: none;\n    background: var(--panel); border-left: 1px solid var(--border); box-shadow: -4px 0 16px rgba(0,0,0,.08);\n    overflow: auto; z-index: 3; padding: 10px 12px; }\n  #eq-panel h3 { margin: 0 0 4px; font-size: 13px; }\n  #eq-meta { font-size: 11.5px; color: var(--text-2); margin-bottom: 6px; line-height: 1.5; }\n  .eq-page { margin: 10px 0 2px; font-size: 12px; font-weight: 600; color: var(--text-2); }\n  .eq-item { display: block; width: 100%; text-align: left; border: 1px solid var(--border); border-radius: 6px;\n    background: var(--bg); color: var(--text); padding: 6px 8px; margin: 4px 0; cursor: pointer; font: inherit; }\n  .eq-item:hover { border-color: var(--accent); }\n  .eq-item code { display: block; font-family: ui-monospace, Menlo, Consolas, monospace; font-size: 11.5px;\n    white-space: pre-wrap; word-break: break-word; margin-top: 2px; }\n  .eq-item .eq-tag { font-size: 11px; color: var(--text-2); }\n  #eq-note { font-size: 12px; color: var(--text-2); line-height: 1.6; }\n  #eq-transcribe { margin-top: 8px; }\n  #eq-toggle.muted { opacity: .55; }\n  #ask-copy { background: none; border: 1px solid var(--border); border-radius: 6px; color: var(--text-2); cursor: pointer; margin-right: auto; }\n\n  /* ---------- 在文中查找（顶栏 🔍 / Ctrl+F）----------\n     输入框与结果列表在**同一个浮窗**里：窗口可拖动、可拖边框改大小，开关只有窗口一件事，\n     不再有「输入条」和「结果面板」两套入口。页内高亮是 .findLayer 里的百分比盒子\n     （Range.getClientRects 算出来的词级矩形）：不给 span 加背景类——span 常常是一整行，\n     而且加类会动 textLayer 的换行与划词。 */\n  #find-tools { display: flex; align-items: center; gap: 6px; padding: 6px 8px; border-bottom: 1px solid var(--border); flex: none; }\n  #find-input { flex: 1; min-width: 0; border: 1px solid var(--border); border-radius: 6px; padding: 4px 8px; font: inherit;\n    font-size: 12.5px; line-height: 18px; background: var(--panel); color: var(--text); }\n  #find-input:focus { outline: none; border-color: var(--accent); }\n  #find-count { flex: none; min-width: 44px; max-width: 96px; text-align: center; font-size: 12px; color: var(--text-2);\n    font-variant-numeric: tabular-nums; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }\n  #find-count.hit { color: var(--accent); }\n  #find-count:empty { display: none; }\n  /* 查找浮窗：输入行 + 结果列表装在一起，可拖动、可拖边框改大小，默认 330×340，不占满阅读区。\n     旧版用右侧滑出面板占满整列高度，会遮住半页纸，所以改成浮窗。 */\n  #find-window { position: fixed; z-index: 46; display: none; flex-direction: column; width: 330px; height: 340px;\n    min-width: 240px; min-height: 190px; background: var(--panel); border: 1px solid var(--border);\n    border-radius: 10px; box-shadow: 0 10px 30px rgba(0,0,0,.18); overflow: hidden; }\n  #find-window.on { display: flex; }\n  #find-head { display: flex; align-items: center; gap: 6px; padding: 6px 8px; cursor: move; user-select: none;\n    border-bottom: 1px solid var(--border); font-size: 12.5px; font-weight: 600; flex: none; }\n  #find-head .spacer { flex: 1; }\n  #find-headcount { font-weight: 400; color: var(--text-2); font-variant-numeric: tabular-nums; }\n  #find-meta { padding: 6px 10px 2px; font-size: 11.5px; color: var(--text-2); line-height: 1.5; flex: none; }\n  /* 列表自己滚：头部与说明固定在窗口上沿，关按钮永远在最上面看得见 */\n  #find-list { flex: 1; overflow: auto; padding: 2px 8px 10px; }\n  #find-grip { position: absolute; right: 0; bottom: 0; width: 16px; height: 16px; cursor: nwse-resize; z-index: 2; }\n  #find-grip::after { content: ''; position: absolute; right: 3px; bottom: 3px; width: 8px; height: 8px;\n    border-right: 2px solid var(--text-2); border-bottom: 2px solid var(--text-2); border-bottom-right-radius: 3px; opacity: .55; }\n  /* 右边缘 / 下边缘也能拖：整条边都是热区，不用非得瞄准右下角那 16px */\n  #find-grip-r { position: absolute; top: 68px; right: 0; bottom: 16px; width: 6px; cursor: ew-resize; z-index: 2; }\n  #find-grip-b { position: absolute; left: 0; right: 16px; bottom: 0; height: 6px; cursor: ns-resize; z-index: 2; }\n  .tbtn.mini { height: 24px; padding: 0 6px; border-radius: 5px; }\n  .tbtn.mini svg.ic { width: 14px; height: 14px; }\n  #find-window .tbtn.mini.on { border-color: var(--accent); color: var(--accent); }\n  .find-page { margin: 10px 0 2px; font-size: 12px; font-weight: 600; color: var(--text-2); }\n  .find-item { display: block; width: 100%; text-align: left; border: 1px solid var(--border); border-radius: 6px;\n    background: var(--bg); color: var(--text); padding: 5px 8px; margin: 3px 0; cursor: pointer;\n    font: inherit; font-size: 12px; line-height: 1.5; }\n  .find-item:hover { border-color: var(--accent); }\n  .find-item.cur { border-color: var(--accent); background: var(--accent-soft); }\n  .find-item mark { background: rgba(255,196,0,.55); color: inherit; border-radius: 2px; padding: 0 1px; }\n  .findLayer { position: absolute; inset: 0; pointer-events: none; z-index: 3; }\n  .find-box { position: absolute; border-radius: 2px; background: rgba(255,214,0,.45); }\n  .find-box.cur { background: rgba(255,146,0,.55); box-shadow: 0 0 0 1.5px rgba(230,110,0,.85); }\n  /* 兜底高亮：Range 几何算不出来时给 span 加类（宁可糙一点，也不能「搜到了却看不见」） */\n  .textLayer span.find-hit { background: rgba(255,214,0,.45); border-radius: 2px; }\n  .textLayer span.find-hit.cur { background: rgba(255,146,0,.55); }\n\n  /* ---------- 笔记（划词标注 + 可移动笔记窗口） ----------\n     标注用「百分比盒子 + 底部波浪底图」而不是给 span 加 text-decoration：一个选区常跨多个 span，\n     加类会把整行都画上波浪线（与查找高亮同一条教训）。盒子层 pointer-events:none，\n     悬停/点击靠坐标命中测试，不会挡住划词选字。 */\n  .noteLayer { position: absolute; inset: 0; pointer-events: none; z-index: 4; }\n  .note-under { position: absolute; border-radius: 2px; pointer-events: none;\n    background-image: url(\"data:image/svg+xml;charset=utf-8,%3Csvg xmlns='http://www.w3.org/2000/svg' width='9' height='4'%3E%3Cpath d='M0 3 Q2.25 .6 4.5 3 T9 3' fill='none' stroke='%232f6bff' stroke-width='1.1'/%3E%3C/svg%3E\");\n    background-repeat: repeat-x; background-position: 0 100%; background-size: 9px 4px; }\n  .note-under.flash { background-color: rgba(47,107,255,.20); }\n  #note-tip { position: fixed; z-index: 58; display: none; max-width: 320px; background: var(--panel);\n    border: 1px solid var(--border); border-radius: 8px; box-shadow: 0 6px 22px rgba(0,0,0,.18);\n    padding: 8px 10px; font-size: 12px; line-height: 1.55; white-space: pre-wrap; word-break: break-word; pointer-events: none; }\n  #note-tip .tip-hint { display: block; margin-top: 4px; color: var(--text-2); font-size: 11px; }\n  /* 气泡里的「笔记 / 全局搜索」：与「译」并列的小动作按钮，不改变原提问链路 */\n  #ask-note, #ask-find { background: none; border: 1px solid var(--border); border-radius: 6px; color: var(--text-2); cursor: pointer; }\n  /* 笔记窗口：与查找窗同一套（可拖动 / 拖边框缩放 / 位置记忆）。列表与编辑器切换显示。 */\n  #note-window { position: fixed; z-index: 46; display: none; flex-direction: column; width: 330px; height: 360px;\n    min-width: 260px; min-height: 200px; background: var(--panel); border: 1px solid var(--border);\n    border-radius: 10px; box-shadow: 0 10px 30px rgba(0,0,0,.18); overflow: hidden; }\n  #note-window.on { display: flex; }\n  #note-head { display: flex; align-items: center; gap: 6px; padding: 6px 8px; cursor: move; user-select: none;\n    border-bottom: 1px solid var(--border); font-size: 12.5px; font-weight: 600; flex: none; }\n  #note-head .spacer, #note-actions .spacer { flex: 1; }\n  #note-headcount { font-weight: 400; color: var(--text-2); font-variant-numeric: tabular-nums; }\n  #note-list { flex: 1; overflow: auto; padding: 4px 8px 10px; }\n  .note-item { display: block; width: 100%; text-align: left; border: 1px solid var(--border); border-radius: 6px;\n    background: var(--bg); color: var(--text); padding: 6px 8px; margin: 5px 0; cursor: pointer; font: inherit; font-size: 12px; line-height: 1.5; }\n  .note-item:hover { border-color: var(--accent); }\n  .note-item .ni-meta { display: block; color: var(--accent); font-size: 11px; margin-bottom: 2px; }\n  .note-item .ni-meta .ni-time { float: right; color: var(--text-2); font-weight: 400; }\n  .note-item .ni-body { display: block; white-space: pre-wrap; word-break: break-word; }\n  .note-item .ni-quote { display: block; color: var(--text-2); font-size: 11px; margin-top: 3px;\n    overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }\n  #note-empty { padding: 14px 6px; color: var(--text-2); font-size: 12px; line-height: 1.6; }\n  #note-editor { display: none; flex-direction: column; flex: 1; min-height: 0; padding: 6px 8px 8px; }\n  #note-window.editing #note-list, #note-window.editing #note-empty { display: none; }\n  #note-window.editing #note-editor { display: flex; }\n  #note-quote { flex: none; max-height: 72px; overflow: auto; font-size: 11.5px; color: var(--text-2);\n    border-left: 3px solid var(--accent-soft); padding-left: 8px; margin-bottom: 6px; }\n  #note-body { flex: 1; min-height: 80px; width: 100%; resize: none; border: 1px solid var(--border); border-radius: 6px;\n    padding: 6px 8px; font: inherit; font-size: 12.5px; line-height: 1.6; background: var(--panel); color: var(--text); }\n  #note-actions { display: flex; align-items: center; gap: 6px; margin-top: 6px; flex: none; }\n  .tbtn.primary { background: var(--accent); border-color: var(--accent); color: #fff; }\n  #note-grip { position: absolute; right: 0; bottom: 0; width: 16px; height: 16px; cursor: nwse-resize; z-index: 2; }\n  #note-grip::after { content: ''; position: absolute; right: 3px; bottom: 3px; width: 8px; height: 8px;\n    border-right: 2px solid var(--text-2); border-bottom: 2px solid var(--text-2); border-bottom-right-radius: 3px; opacity: .55; }\n  #note-grip-r { position: absolute; top: 34px; right: 0; bottom: 16px; width: 6px; cursor: ew-resize; z-index: 2; }\n  #note-grip-b { position: absolute; left: 0; right: 16px; bottom: 0; height: 6px; cursor: ns-resize; z-index: 2; }\n\n  /* ---------- 选中即问浮层 ---------- */\n  #ask-scope-row { display: flex; align-items: center; gap: 6px; margin: 2px 0 4px; font-size: 12px; color: var(--text-2); }\n  #ask-scope-row select { font: inherit; font-size: 12px; padding: 2px 4px; border: 1px solid var(--border); border-radius: 5px; background: var(--panel); color: var(--text); max-width: 60%; }\n  #ask-scope-hint { opacity: .75; font-size: 11px; }\n  #cfg-pop hr { border: none; border-top: 1px solid var(--border); margin: 12px 0 8px; }\n  #cfg-theme-hint { font-size: 11.5px; color: var(--text-2); line-height: 1.5; margin-top: 4px; }\n  #ask-scope-row { display: flex; align-items: center; gap: 6px; margin: 2px 0 4px; font-size: 12px; color: var(--text-2); }\n  #ask-scope-row select { font: inherit; font-size: 12px; padding: 2px 4px; border: 1px solid var(--border); border-radius: 5px; background: var(--panel); color: var(--text); max-width: 60%; }\n  #ask-scope-hint { opacity: .75; font-size: 11px; }\n  #cfg-pop hr { border: none; border-top: 1px solid var(--border); margin: 12px 0 8px; }\n  #cfg-theme-hint { font-size: 11.5px; color: var(--text-2); line-height: 1.5; margin-top: 4px; }\n  #ask-pop { position: fixed; z-index: 50; display: none; background: var(--panel); border: 1px solid var(--border); border-radius: 10px; box-shadow: 0 6px 24px rgba(0,0,0,.16); padding: 10px; width: 320px; }\n  #ask-quote { font-size: 12px; color: var(--text-2); max-height: 64px; overflow: hidden; margin-bottom: 8px; border-left: 3px solid var(--accent-soft); padding-left: 8px; }\n  #ask-input { width: 100%; border: 1px solid var(--border); border-radius: 6px; padding: 6px 8px; font: inherit; resize: none; }\n  #ask-actions { display: flex; justify-content: flex-end; gap: 8px; margin-top: 8px; }\n  #ask-send { background: var(--accent); color: #fff; border: none; border-radius: 6px; padding: 5px 14px; cursor: pointer; }\n  #ask-send:disabled { opacity: .5; cursor: default; }\n  #ask-cancel { background: none; border: none; color: var(--text-2); cursor: pointer; }\n  /* 「译」动作按钮（加法：只在原文视图的纯文字选区出现，见 showAskPop） */\n  #ask-translate { background: none; border: 1px solid var(--border); border-radius: 6px; color: var(--accent); cursor: pointer; }\n\n  /* ---------- 划词译文气泡 ----------\n     用户明确要求：**只显示译文**，不做「插入会话」「复制」按钮 ⇒ 气泡内部零 button 元素。\n     提示（诚实降级文案）走独立的 #tr-note，绝不混进 #tr-body。 */\n  #tr-pop { position: fixed; z-index: 50; display: none; background: var(--panel); border: 1px solid var(--border);\n    border-radius: 10px; box-shadow: 0 6px 24px rgba(0,0,0,.16); padding: 10px;\n    width: min(360px, calc(100vw - 16px)); max-height: 45vh; overflow: auto; }\n  #tr-status { font-size: 12px; color: var(--text-2); }\n  #tr-status:empty { display: none; }\n  #tr-body { font-size: 13px; white-space: pre-wrap; word-break: break-word; }\n  #tr-note { font-size: 12px; color: var(--text-2); margin-top: 6px; line-height: 1.5; }\n  #tr-note:empty { display: none; }\n  /* 公式段：KaTeX 渲染进我们新建的元素（.tr-math / .tr-math-block）；渲染失败时该段落回原始 LaTeX\n     文本并加 .tr-math-fallback（可读可复制，绝不留白）。 */\n  #tr-body .tr-math-block { margin: 6px 0; overflow-x: auto; }\n  #tr-body .tr-math-block .katex-display { margin: 0; }\n  #tr-body .tr-math-fallback { font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace; font-size: 12px; color: var(--text-2); word-break: break-all; }\n\n  /* ---------- 翻译端点设置浮层 ---------- */\n  /* 阅读器在窄 iframe 里，宽度要能收缩 */\n  #cfg-pop, #theme-pop, #generate-pop { position: fixed; z-index: 60; display: none; background: var(--panel); border: 1px solid var(--border); border-radius: 10px; box-shadow: 0 6px 24px rgba(0,0,0,.16); padding: 10px; width: min(320px, calc(100vw - 32px)); }\n  #cfg-pop h3, #theme-pop h3 { margin: 0; font-size: 13px; }\n  #cfg-hint { font-size: 12px; color: var(--text-2); margin: 4px 0 2px; }\n  #cfg-pop label, #theme-pop label { display: block; font-size: 12px; color: var(--text-2); margin: 8px 0 2px; }\n  /* checkbox 例外：width:100% 会把它拉满整行、文字被挤到右边很远（实测视觉松散的根因） */\n  #cfg-pop input[type=\"checkbox\"], #theme-pop input[type=\"checkbox\"] { width: auto; }\n  #theme-pop h3 { display: flex; align-items: center; justify-content: space-between; }\n  #theme-close { all: unset; cursor: pointer; font-size: 12px; color: var(--text-2); padding: 2px 6px; border-radius: 4px; }\n  #theme-close:hover { background: var(--bg); color: var(--text); }\n  #cfg-pop input, #cfg-pop select, #theme-pop input, #theme-pop select { width: 100%; border: 1px solid var(--border); border-radius: 6px; padding: 6px 8px; font: inherit; background: var(--panel); color: var(--text); }\n  #cfg-model-hint, #cfg-source { font-size: 11.5px; color: var(--text-2); margin-top: 4px; line-height: 1.5; }\n  #cfg-source:empty { display: none; }\n  #cfg-actions, #generate-actions, #cfg-list-actions { display: flex; justify-content: flex-end; gap: 8px; margin-top: 10px; }\n  #cfg-list-actions { justify-content: flex-start; margin-top: 4px; }\n  #cfg-save, #generate-start { background: var(--accent); color: #fff; border: none; border-radius: 6px; padding: 5px 14px; cursor: pointer; }\n  #cfg-save:disabled, #generate-start:disabled { opacity: .5; cursor: default; }\n  #cfg-cancel { background: none; border: none; color: var(--text-2); cursor: pointer; }\n\n  #toast { position: fixed; left: 50%; bottom: 28px; transform: translateX(-50%); background: rgba(30,30,30,.92); color: #fff; padding: 8px 16px; border-radius: 8px; font-size: 13px; display: none; z-index: 99; max-width: 70%; }\n  /* ---------- 深色模式（方案 §A2.1；设置项 §A2.3）----------\n     ⚠️ 滤镜只挂 `canvas`，**绝不挂 `.page`**：挂 .page 会连 `.eqLayer` 的热区描边与\n     `.textLayer ::selection` 一起反转（热区框变怪色、选中高亮从蓝变橙），\n     并可能影响命中判定所在的层叠上下文。挂 canvas 时文本层/热区层/浮层颜色一律不受影响。 */\n  html[data-dpr-pdf=\"dark\"] #pdf-pages .page > canvas,\n  html[data-dpr-pdf=\"dark\"] #pdf-pages-zh .page > canvas {\n    filter: invert(1) hue-rotate(180deg)\n            brightness(var(--dpr-dark-b, 0.92)) contrast(var(--dpr-dark-c, 0.95));\n  }\n  html[data-dpr-pdf=\"dark\"] .page { background: #1b1b1c; box-shadow: none; }\n  /* 深色下阅读器自身 UI（pdfDarkChrome）：**只覆写我们的自有变量**，绝不碰 --dsw-*（那是 dsh 的） */\n  html[data-dpr-pdf=\"dark\"][data-dpr-chrome=\"on\"] {\n    color-scheme: dark;\n    --bg: #16181d; --panel: #1e2127; --border: #333a45; --text: #e6e8ec; --text-2: #9aa3b2;\n    --accent: #4c9aff; --accent-soft: rgba(76,154,255,.18); --hl: rgba(255,196,0,.45);\n  }\n  /* 首帧防白闪（§A2.5 R15）：主题判定完成前藏住页面区。判定是 <head> 里的**同步**读属性，\n     无网络、无 await ⇒ 正常路径下这个状态在首帧前就被覆盖；JS 完全不跑时阅读器本来就是空白。 */\n  html[data-dpr-pdf=\"pending\"] #pdf-pages,\n  html[data-dpr-pdf=\"pending\"] #pdf-pages-zh { visibility: hidden; }\n</style>\n</head>\n<body>\n\n<div id=\"bar\">\n  <span id=\"status\">论文伴读</span>\n  <!-- 翻译进度条：只在 babeldoc 跑着时出现（宽度=overall，文字=阶段+百分比），\n       窄列下先让位给按钮（flex:0 1 auto + min-width:0），别把控件挤出去 -->\n  <span id=\"zh-prog\" hidden><span class=\"track\"><span class=\"fill\"></span></span><span class=\"txt\"></span></span>\n  <button id=\"zh-cancel\" class=\"tbtn\" style=\"display:none\" title=\"取消当前翻译，之后可换端点重试\">取消</button>\n  <!-- 路径不再占顶栏：藏于此（tucked），悬停状态文字可见完整路径、点击状态文字复制（见下方绑定） -->\n  <button id=\"pdf-path\" class=\"tucked\" style=\"display:none\" title=\"点击复制文件路径\"></button>\n  <span class=\"bar-sep\"></span>\n  <!-- 语言视图收纳（17 控件 → 分组）：原文/中文/对照/分屏 四态 + 重译 → 「视图」下拉。\n       原按钮 DOM 保留（.tucked 隐藏）——菜单项转发它们的 click，状态机零改动。\n       「同步滚动」仍按原逻辑仅在分屏下出现（见其原注释）。 -->\n  <button id=\"view-menu-btn\" class=\"tbtn\" title=\"语言视图：原文 / 中文 / 对照 / 分屏 / 重新翻译\">视图：原文 ▾</button>\n  <button id=\"transcribe-open\" class=\"tbtn\" style=\"display:none\" title=\"按当前配置转录这篇 PDF（MinerU 关闭时用 pdf.js）\">转录</button>\n  <button id=\"zh-toggle\" class=\"tbtn tucked\" title=\"切换中文译文（没有译文时可生成）\" style=\"display:none\" data-icon=\"translate\"></button>\n  <button id=\"dual-toggle\" class=\"tbtn tucked\" title=\"用 babeldoc 的中英对照 PDF（模式 A）\" style=\"display:none\" data-icon=\"columns\">对照</button>\n  <button id=\"split-toggle\" class=\"tbtn tucked\" title=\"原文与中文版并排同步滚动（模式 B）\" style=\"display:none\" data-icon=\"split\">分屏</button>\n  <button id=\"sync-toggle\" class=\"tbtn\" title=\"同步滚动 / Sync scroll：开（两列一起滚，点击关闭）\" style=\"display:none\" data-icon=\"sync\"></button>\n  <button id=\"zh-regen\" class=\"tbtn tucked\" title=\"重新翻译：删除现有译文，用当前端点重跑（换模型后用）\" style=\"display:none\" data-icon=\"regen\"></button>\n  <span class=\"bar-sep\"></span>\n  <button id=\"zoom-out\" class=\"tbtn\" title=\"缩小\" data-icon=\"minus\"></button>\n  <span id=\"zoom-label\">100%</span>\n  <button id=\"zoom-in\" class=\"tbtn\" title=\"放大\" data-icon=\"plus\"></button>\n  <button id=\"zoom-fit\" class=\"tbtn\">适宽</button>\n  <button id=\"mode-toggle\" class=\"tbtn\" title=\"切换 滚动/翻页模式\" style=\"display:none\" data-icon=\"paged\"></button>\n  <span class=\"bar-sep\"></span>\n  <!-- 在文中查找（Ctrl+F）：入口紧挨笔记，实际输入条是浮层，不占顶栏宽度 -->\n  <button id=\"find-open\" class=\"tbtn\" title=\"在文中查找（Ctrl+F）\" style=\"display:none\" data-icon=\"search\"></button>\n  <!-- 笔记：点开是「笔记窗口」（列全部笔记 / 新建 / 编辑） -->\n  <button id=\"note-open\" class=\"tbtn\" title=\"笔记\" style=\"display:none\" data-icon=\"note\"></button>\n  <button id=\"dl-btn\" class=\"tbtn\" title=\"下载 PDF\" style=\"display:none\" data-icon=\"download\"></button>\n  <span class=\"bar-spacer\"></span>\n  <button id=\"scope-chip\" class=\"tbtn\" title=\"提问范围：本篇（点击切换 本篇/所在专题含子专题）\">范围：本篇</button>\n  <button id=\"theme-toggle\" class=\"tbtn\" title=\"PDF 深色模式：跟随 dsh 主题（点击切换 关/跟随/强制深色）\">A</button>\n  <button id=\"eq-toggle\" class=\"tbtn\" title=\"公式引用（MinerU LaTeX）\" data-icon=\"sigma\">公式</button>\n  <button id=\"cfg-open\" class=\"tbtn\" title=\"翻译端点设置\" data-icon=\"settings\"></button>\n  <span id=\"ver\" title=\"插件版本\">__DPR_VERSION__</span>\n</div>\n<!-- 顶栏收纳的弹出菜单（绝对定位于 #bar）：深色/公式/设置经用户反馈回归顶栏，只留「视图」一个下拉 -->\n<div id=\"view-menu\" class=\"bar-menu\" hidden>\n  <button data-act=\"orig\">原文</button>\n  <button data-act=\"zh\">中文（纯译文）</button>\n  <button data-act=\"dual\">对照（双语同页）</button>\n  <button data-act=\"split\">分屏（左右两列）</button>\n  <hr>\n  <button data-act=\"regen\">重新翻译…</button>\n</div>\n\n<div id=\"main\">\n  <div id=\"split-wrap\">\n    <div id=\"pdf-pane\">\n      <div id=\"pane-label\" class=\"pane-label\">原文</div>\n      <div id=\"pdf-pages\"></div>\n      <div id=\"empty\" style=\"display:none\"></div>\n    </div>\n    <div id=\"pdf-pane-zh\">\n      <div id=\"pane-label-zh\" class=\"pane-label\">中文</div>\n      <div id=\"pdf-pages-zh\"></div>\n    </div>\n  </div>\n  <!-- 翻页条挪到阅读区底部（悬浮居中，不占顶栏）：JS 的 $('pager').style.display 契约不变，\n       '' 恢复到的 CSS 默认值从 inline 改为悬浮 flex -->\n  <span id=\"pager\" style=\"display:none\">\n    <button id=\"page-prev\" class=\"tbtn\" title=\"上一页\" data-icon=\"prev\"></button>\n    <input id=\"page-input\" type=\"text\" inputmode=\"numeric\" title=\"页码，回车跳转\">\n    <span id=\"page-total\">/ ?</span>\n    <button id=\"page-next\" class=\"tbtn\" title=\"下一页\" data-icon=\"next\"></button>\n  </span>\n  <div id=\"eq-panel\">\n    <h3>公式</h3>\n    <div id=\"eq-meta\"></div>\n    <div id=\"eq-list\"></div>\n  </div>\n  <!-- 查找：输入框与结果列表在同一个浮窗里（可拖动 / 拖边框改大小 / 精简↔全部，\n       位置尺寸记在 localStorage）。头部固定，只有 #find-list 自己滚，所以关按钮永远可见。 -->\n  <div id=\"find-window\" role=\"dialog\" aria-label=\"查找\">\n    <div id=\"find-head\">\n      <span>查找</span>\n      <span id=\"find-headcount\"></span>\n      <span class=\"spacer\"></span>\n      <button id=\"find-expand\" class=\"tbtn mini\" title=\"在「精简」与「全部」之间切换\">精简</button>\n      <button id=\"find-window-close\" class=\"tbtn mini\" title=\"关闭（Esc）\">✕</button>\n    </div>\n    <div id=\"find-tools\">\n      <input id=\"find-input\" type=\"text\" placeholder=\"在文中查找…\" autocomplete=\"off\" spellcheck=\"false\">\n      <span id=\"find-count\"></span>\n      <button id=\"find-prev\" class=\"tbtn mini\" title=\"上一处（Shift+Enter）\" data-icon=\"prev\"></button>\n      <button id=\"find-next\" class=\"tbtn mini\" title=\"下一处（Enter）\" data-icon=\"next\"></button>\n    </div>\n    <div id=\"find-meta\"></div>\n    <div id=\"find-list\"></div>\n    <div id=\"find-grip-r\" title=\"拖动改变宽度\"></div>\n    <div id=\"find-grip-b\" title=\"拖动改变高度\"></div>\n    <div id=\"find-grip\" title=\"拖动调整大小\"></div>\n  </div>\n\n  <!-- 笔记窗口：与查找窗同一套交互（标题栏拖动 / 三边缩放 / 位置尺寸记忆）。\n       列表态显示全部笔记，编辑态换成「引用 + 正文 + 保存/删除」。 -->\n  <div id=\"note-window\" role=\"dialog\" aria-label=\"笔记\">\n    <div id=\"note-head\">\n      <span>笔记</span>\n      <span id=\"note-headcount\"></span>\n      <span class=\"spacer\"></span>\n      <button id=\"note-new\" class=\"tbtn mini\" title=\"把当前选中的文字做成新笔记\">＋</button>\n      <button id=\"note-window-close\" class=\"tbtn mini\" title=\"关闭（Esc）\">✕</button>\n    </div>\n    <div id=\"note-list\"></div>\n    <div id=\"note-editor\">\n      <div id=\"note-quote\"></div>\n      <textarea id=\"note-body\" placeholder=\"写下你的理解、疑问、和别处的联系…（⌘/Ctrl+Enter 保存）\"></textarea>\n      <div id=\"note-actions\">\n        <button id=\"note-delete\" class=\"tbtn mini\" title=\"删除这条笔记\">删除</button>\n        <span class=\"spacer\"></span>\n        <button id=\"note-cancel\" class=\"tbtn mini\">取消</button>\n        <button id=\"note-save\" class=\"tbtn mini primary\">保存</button>\n      </div>\n    </div>\n    <div id=\"note-grip-r\" title=\"拖动改变宽度\"></div>\n    <div id=\"note-grip-b\" title=\"拖动改变高度\"></div>\n    <div id=\"note-grip\" title=\"拖动调整大小\"></div>\n  </div>\n</div>\n\n<div id=\"ask-pop\">\n  <div id=\"ask-quote\"></div>\n  <!-- 提问范围（方案 §B3.3 入口 1）：默认「本篇」＝改造前行为；「所在专题」会带上整棵子专题的目录内容 -->\n  <div id=\"ask-scope-row\">\n    <span id=\"ask-scope-label\">范围</span>\n    <select id=\"ask-scope\" title=\"提问时只提供该范围内的目录内容\">\n      <option value=\"paper\">本篇（默认）</option>\n      <option value=\"topic\">所在专题（含子专题）</option>\n    </select>\n    <span id=\"ask-scope-hint\">范围外内容不会提供给模型</span>\n  </div>\n  <textarea id=\"ask-input\" rows=\"2\" placeholder=\"围绕选中内容提问…\"></textarea>\n  <div id=\"ask-actions\">\n    <button id=\"ask-copy\" style=\"display:none\">复制 LaTeX</button>\n    <button id=\"ask-translate\" style=\"display:none\" title=\"翻译选中内容（含公式时用 MinerU 的 LaTeX 还原）\">译</button>\n    <button id=\"ask-note\" style=\"display:none\" title=\"给这段文字加一条笔记\">笔记</button>\n    <button id=\"ask-find\" style=\"display:none\" title=\"在全文里查找这段文字\">全局搜索</button>\n    <button id=\"ask-cancel\">取消</button>\n    <button id=\"ask-send\">提问</button>\n  </div>\n</div>\n\n<!-- 划词译文气泡：只有译文 + 状态行 + 一行诚实提示，**零按钮**（用户明确不要插入会话/复制） -->\n<div id=\"tr-pop\">\n  <div id=\"tr-status\"></div>\n  <div id=\"tr-body\"></div>\n  <div id=\"tr-note\"></div>\n</div>\n\n<div id=\"cfg-pop\">\n  <h3>翻译端点</h3>\n  <div id=\"cfg-hint\">选预设供应商，或选「自定义」填任意 OpenAI 兼容端点（通义 / 本地 vLLM 等）。OpenCode Go 需先在 OpenCode Console 订阅并复制 API Key。保存前会先测试连接。</div>\n  <div id=\"cfg-source\"></div>\n  <label for=\"cfg-saved\">已保存端点</label>\n  <select id=\"cfg-saved\"></select>\n  <div id=\"cfg-list-actions\">\n    <button id=\"cfg-new\" class=\"tbtn\">新增端点</button>\n    <button id=\"cfg-delete\" class=\"tbtn\">删除当前</button>\n  </div>\n  <label for=\"cfg-provider\">供应商</label>\n  <select id=\"cfg-provider\"></select>\n  <label for=\"cfg-url\">端点 URL</label>\n  <input id=\"cfg-url\" type=\"text\" placeholder=\"https://api.deepseek.com/v1\" autocomplete=\"off\">\n  <label for=\"cfg-key\">API Key</label>\n  <input id=\"cfg-key\" type=\"password\" placeholder=\"sk-...\" autocomplete=\"new-password\">\n  <label for=\"cfg-model\">模型</label>\n  <input id=\"cfg-model\" type=\"text\" placeholder=\"deepseek-chat\" autocomplete=\"off\" list=\"cfg-model-list\">\n  <datalist id=\"cfg-model-list\"></datalist>\n  <div id=\"cfg-model-hint\">glm-5.x / k3 / deepseek-flash 是推理型模型，服务端已自动关闭思考；选自定义端点时建议用非推理模型，否则会慢好几倍。</div>\n  <div id=\"cfg-actions\">\n    <button id=\"cfg-cancel\">取消</button>\n    <button id=\"cfg-save-new\">另存为新端点</button>\n    <button id=\"cfg-save\">保存</button>\n  </div>\n</div>\n\n<div id=\"generate-pop\">\n  <h3>选择翻译模型</h3>\n  <div id=\"generate-hint\">本次整篇翻译使用哪个已保存端点？Key 只会显示掩码。</div>\n  <label for=\"generate-endpoint\">模型 / API Key</label>\n  <select id=\"generate-endpoint\"></select>\n  <div id=\"generate-actions\">\n    <button id=\"generate-manage\" class=\"tbtn\">管理端点</button>\n    <button id=\"generate-cancel\" class=\"tbtn\">取消</button>\n    <button id=\"generate-start\">开始翻译</button>\n  </div>\n</div>\n\n<!-- PDF 深色模式（方案 §A2.3 入口 2）：与 dsh 设置面板**共用同一个后端配置**（/api/theme/config），\n     两处不各存一份；改动即时生效，无需点保存。独立于设置面板——「A」按钮专属配置。 -->\n<div id=\"theme-pop\">\n  <h3>PDF 深色模式 <button id=\"theme-close\" title=\"关闭\" aria-label=\"关闭\">✕</button></h3>\n  <label for=\"cfg-theme-mode\">模式</label>\n  <select id=\"cfg-theme-mode\">\n    <option value=\"follow\">跟随 dsh 主题（默认）</option>\n    <option value=\"off\">关闭（PDF 保持原色）</option>\n    <option value=\"light\">强制浅色</option>\n    <option value=\"dark\">强制深色</option>\n  </select>\n  <label for=\"cfg-theme-strength\">强度（越往下越柔和）</label>\n  <select id=\"cfg-theme-strength\">\n    <option value=\"0\">最黑</option>\n    <option value=\"1\">近黑（默认）</option>\n    <option value=\"2\">柔和</option>\n    <option value=\"3\">纸感</option>\n  </select>\n  <label for=\"cfg-theme-chrome\" style=\"display:flex;align-items:center;gap:6px\">\n    <input id=\"cfg-theme-chrome\" type=\"checkbox\"> 阅读器界面也切深色\n  </label>\n  <div id=\"cfg-theme-hint\">整页反色方案：图片/照片会褪色偏色；导出的 PDF 始终是原文。（悬停查看实测细节）</div>\n</div>\n\n<!-- 笔记悬停提示：鼠标停在被标注文字上显示笔记内容 -->\n<div id=\"note-tip\"></div>\n\n<div id=\"toast\"></div>\n\n<script>\n'use strict';\n/* 深色首帧判定（方案 §A2.2 的四级降级链 + §A2.5「朝亮色回退」）——必须在首帧**之前**同步完成，\n   否则会出现「先白后黑」的白闪（Firefox/pdf.js #18680 同款公开案例）。放在模块脚本最前面：\n   解析期同步执行、早于首帧，且**不新增第二个 <script> 块**（test/reader-script.mjs 的提取约定）。\n   ① 宿主 body[data-ds-dark-theme] ② 宿主 html[data-ds-theme-source] ③ 自身 prefers-color-scheme\n   ④ 以上全失败 ⇒ **判亮色**（宁可该黑没黑，绝不误黑）；任何异常同样朝亮色回退，绝不冒泡。 */\nvar __dprDarkMq = null;   // 复用的 (prefers-color-scheme: dark) MediaQueryList（只建一个，见下）\n(function firstFrameTheme() {\n  var mode = 'light';\n  try { if (!__dprDarkMq && window.matchMedia) __dprDarkMq = window.matchMedia('(prefers-color-scheme: dark)'); } catch (e) { /* 无 matchMedia：走降级链下一级 */ }\n  try {\n    var pref = 'follow';\n    try { pref = localStorage.getItem('dpr.pdfTheme') || 'follow'; } catch (e) { pref = 'follow'; }\n    if (pref === 'dark') mode = 'dark';\n    else if (pref === 'off' || pref === 'light') mode = 'light';\n    else {\n      var d = null;\n      try { d = window.parent && window.parent !== window ? window.parent.document : null; } catch (e) { d = null; }\n      var src = null;\n      try { src = d && d.documentElement ? d.documentElement.getAttribute('data-ds-theme-source') : null; } catch (e) { src = null; }\n      if (d && d.body && d.body.hasAttribute && d.body.hasAttribute('data-ds-dark-theme')) mode = 'dark';\n      else if (src === 'dark') mode = 'dark';\n      else if (src === 'light') mode = 'light';\n      else if (__dprDarkMq && __dprDarkMq.matches) mode = 'dark';\n    }\n  } catch (e) { mode = 'light'; }\n  try { if (document.documentElement && document.documentElement.setAttribute) document.documentElement.setAttribute('data-dpr-pdf', mode); } catch (e) { /* DOM 异常：保持 pending，不影响其余功能 */ }\n})();\n/* ================= 基础 ================= */\nconst $ = (id) => document.getElementById(id);\n/* 顶栏图标：统一的 24×24 描边图标集（stroke=currentColor，active/disabled 变色自动跟随按钮）。\n   曾经混用 Unicode 字符（↻/⤓/▣/⚙/＋…）——各自渲染自不同字体，粗细、大小、基线互不一致。 */\nconst ICONS = {\n  translate: '<path d=\"m5 8 6 6\"/><path d=\"m4 14 6-6 2-3\"/><path d=\"M2 5h12\"/><path d=\"M7 2h1\"/><path d=\"m22 22-5-10-5 10\"/><path d=\"M14 18h6\"/>',\n  regen: '<path d=\"M3 12a9 9 0 0 1 9-9 9.75 9.75 0 0 1 6.74 2.74L21 8\"/><path d=\"M21 3v5h-5\"/><path d=\"M21 12a9 9 0 0 1-9 9 9.75 9.75 0 0 1-6.74-2.74L3 16\"/><path d=\"M8 16H3v5\"/>',\n  download: '<path d=\"M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4\"/><polyline points=\"7 10 12 15 17 10\"/><line x1=\"12\" x2=\"12\" y1=\"15\" y2=\"3\"/>',\n  paged: '<path d=\"M12 7v14\"/><path d=\"M3 18a1 1 0 0 1-1-1V4a1 1 0 0 1 1-1h5a4 4 0 0 1 4 4 4 4 0 0 1 4-4h5a1 1 0 0 1 1 1v13a1 1 0 0 1-1 1h-6a3 3 0 0 0-3 3 3 3 0 0 0-3-3z\"/>',\n  scroll: '<path d=\"M19 17V5a2 2 0 0 0-2-2H4\"/><path d=\"M8 21h12a2 2 0 0 0 2-2v-1a1 1 0 0 0-1-1H11a1 1 0 0 0-1 1v1a2 2 0 1 1-4 0V5a2 2 0 1 0-4 0v2a1 1 0 0 0 1 1h3\"/>',\n  prev: '<path d=\"m15 18-6-6 6-6\"/>',\n  next: '<path d=\"m9 18 6-6-6-6\"/>',\n  settings: '<path d=\"M12.22 2h-.44a2 2 0 0 0-2 2v.18a2 2 0 0 1-1 1.73l-.43.25a2 2 0 0 1-2 0l-.15-.08a2 2 0 0 0-2.73.73l-.22.38a2 2 0 0 0 .73 2.73l.15.1a2 2 0 0 1 1 1.72v.51a2 2 0 0 1-1 1.74l-.15.09a2 2 0 0 0-.73 2.73l.22.38a2 2 0 0 0 2.73.73l.15-.08a2 2 0 0 1 2 0l.43.25a2 2 0 0 1 1 1.73V20a2 2 0 0 0 2 2h.44a2 2 0 0 0 2-2v-.18a2 2 0 0 1 1-1.73l.43-.25a2 2 0 0 1 2 0l.15.08a2 2 0 0 0 2.73-.73l.22-.39a2 2 0 0 0-.73-2.73l-.15-.08a2 2 0 0 1-1-1.74v-.5a2 2 0 0 1 1-1.74l.15-.09a2 2 0 0 0 .73-2.73l-.22-.38a2 2 0 0 0-2.73-.73l-.15.08a2 2 0 0 1-2 0l-.43-.25a2 2 0 0 1-1-1.73V4a2 2 0 0 0-2-2z\"/><circle cx=\"12\" cy=\"12\" r=\"3\"/>',\n  minus: '<path d=\"M5 12h14\"/>',\n  plus: '<path d=\"M5 12h14\"/><path d=\"M12 5v14\"/>',\n  sigma: '<path d=\"M18 7V5H6l6 7-6 7h12v-2\"/>',\n  columns: '<rect width=\"18\" height=\"18\" x=\"3\" y=\"3\" rx=\"2\"/><path d=\"M12 3v18\"/>',\n  split: '<rect width=\"8\" height=\"18\" x=\"3\" y=\"3\" rx=\"2\"/><rect width=\"8\" height=\"18\" x=\"13\" y=\"3\" rx=\"2\"/>',\n  sync: '<path d=\"m17 2 4 4-4 4\"/><path d=\"M3 11v-1a4 4 0 0 1 4-4h14\"/><path d=\"m7 22-4-4 4-4\"/><path d=\"M21 13v1a4 4 0 0 1-4 4H3\"/>',\n  syncOff: '<path d=\"m18.84 12.25 1.72-1.71h-.02a5.004 5.004 0 0 0-.12-7.07 5.006 5.006 0 0 0-6.95 0l-1.72 1.71\"/><path d=\"m5.17 11.75-1.71 1.71a5.004 5.004 0 0 0 .12 7.07 5.006 5.006 0 0 0 6.95 0l1.71-1.71\"/><line x1=\"8\" x2=\"8\" y1=\"2\" y2=\"5\"/><line x1=\"2\" x2=\"5\" y1=\"8\" y2=\"8\"/><line x1=\"16\" x2=\"16\" y1=\"19\" y2=\"22\"/><line x1=\"19\" x2=\"22\" y1=\"16\" y2=\"16\"/>',\n  spin: '<path d=\"M21 12a9 9 0 1 1-6.219-8.56\"/>',\n  search: '<circle cx=\"11\" cy=\"11\" r=\"7\"/><path d=\"m20.5 20.5-3.9-3.9\"/>',\n  close: '<path d=\"M18 6 6 18\"/><path d=\"m6 6 12 12\"/>',\n  note: '<path d=\"M12 20h9\"/><path d=\"M16.5 3.5a2.12 2.12 0 0 1 3 3L7 19l-4 1 1-4Z\"/>',\n  ask: '<path d=\"M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z\"/>',\n};\nconst iconHtml = (name) => `<svg class=\"ic${name === 'spin' ? ' spin' : ''}\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\">${ICONS[name]}</svg>`;\n// 静态按钮按 data-icon 注入一次；动态按钮（翻译/重翻/模式切换）在状态变化时用同一函数换图标\n// #pager：翻页条挪到阅读区底部（#main 内）后也要扫到，否则上一页/下一页图标空白\ndocument.querySelectorAll('#bar [data-icon], #pager [data-icon], #find-window [data-icon], #note-window [data-icon]').forEach((b) => b.insertAdjacentHTML('afterbegin', iconHtml(b.dataset.icon)));\nconst api = (p, opts) => fetch('/paper-reader/api' + p, opts).then(async (r) => {\n  if (!r.ok) {\n    // 服务端错误体有两种：{error}（参数/权限）与 {reason}（zh/generate 的未启动原因，带完整说明）\n    const body = await r.json().catch(() => ({}));\n    const err = new Error(body.error || body.reason || ('HTTP ' + r.status));\n    err.code = body.code;   // 机器可读码（如 no-endpoint）——让调用方靠它分支，别去匹配中文文案\n    err.status = r.status;\n    // 划词翻译的 502 带上游状态码：客户端据此出 §3.7② 的分档文案（拒绝/限流/端点错误），\n    // 而不是去 match 服务端的自由文案。\n    err.upstreamStatus = body.upstreamStatus;\n    throw err;\n  }\n  return r.json();\n});\nfunction toast(msg, ms = 3200) {\n  const t = $('toast'); t.textContent = msg; t.style.display = 'block';\n  clearTimeout(toast._t); toast._t = setTimeout(() => t.style.display = 'none', ms);\n}\nfunction esc(s) { return s.replace(/[&<>\"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;' }[c])); }\n\n/* ================= 深色模式（方案 §A2）=================\n   路线：canvas 上打 CSS 滤镜 `invert(1) hue-rotate(180deg)` + 亮度/对比档（实测不破坏几何/选区/热区，\n   见 §A2.1 与 .probe/darkmode-subtopic/e-filter-mechanics-probe.mjs）。\n   主题来源（四级降级链，§A2.2）：① 宿主 body[data-ds-dark-theme] ② 宿主 html[data-ds-theme-source]\n   ③ 自身 prefers-color-scheme ④ 全失败 ⇒ **亮色**（宁可该黑没黑，绝不误黑）。\n   配置是**服务端唯一一份**（/api/theme/config），阅读器只做镜像（localStorage）+ 跨文档同步。 */\nconst DARK_STRENGTHS = [[1, 1], [0.92, 0.95], [0.85, 0.9], [0.8, 0.85]];\nconst THEME_PREF_KEY = 'dpr.pdfTheme';\nconst THEME_MIRROR_KEY = 'dpr.pdfThemeCfg';\nlet dprTheme = { mode: 'follow', strength: 1, chrome: true, curve: { brightness: 0.92, contrast: 0.95 } };\n\n/** 宿主（dsh）当前的亮暗：读不到一律返回 null（跨源/沙箱/未写入 ⇒ 交下一级降级）。 */\nfunction hostThemeSource() {\n  let d = null;\n  try { d = window.parent !== window ? window.parent.document : null; } catch (e) { return null; }\n  if (!d) return null;\n  try {\n    if (d.body && d.body.hasAttribute && d.body.hasAttribute('data-ds-dark-theme')) return 'dark';\n  } catch (e) { /* 继续下一级 */ }\n  try {\n    const src = d.documentElement && d.documentElement.getAttribute('data-ds-theme-source');\n    if (src === 'dark' || src === 'light') return src;\n  } catch (e) { /* 继续下一级 */ }\n  return null;\n}\n\n/** 生效的 PDF 亮暗（配置优先，follow 才探测宿主）。 */\nfunction effectivePdfTheme() {\n  const pref = dprTheme.mode;\n  if (pref === 'dark') return 'dark';\n  if (pref === 'off' || pref === 'light') return 'light';\n  const host = hostThemeSource();\n  if (host) return host;\n  if (__dprDarkMq && __dprDarkMq.matches) return 'dark';\n  return 'light';\n}\n\nfunction applyPdfTheme() {\n  const mode = effectivePdfTheme();\n  try {\n    const root = document.documentElement;\n    if (root) {\n      if (typeof root.setAttribute === 'function') {\n        root.setAttribute('data-dpr-pdf', mode);\n        root.setAttribute('data-dpr-chrome', dprTheme.chrome ? 'on' : 'off');\n      }\n      if (root.style && typeof root.style.setProperty === 'function') {\n        root.style.setProperty('--dpr-dark-b', String(dprTheme.curve.brightness));\n        root.style.setProperty('--dpr-dark-c', String(dprTheme.curve.contrast));\n      }\n    }\n  } catch (e) { /* DOM 不可用（测试桩/极端宿主）：只跳过视觉属性写入 */ }\n  const btn = $('theme-toggle');\n  if (btn) {\n    btn.classList.toggle('active', mode === 'dark');\n    const src = dprTheme.mode === 'follow' ? `跟随 dsh（当前 ${mode === 'dark' ? '深色' : '浅色'}）` : dprTheme.mode === 'off' ? '关闭' : `强制${dprTheme.mode === 'dark' ? '深色' : '浅色'}`;\n    btn.title = `PDF 深色模式：${src}（点击切换 关/跟随/强制深色）`;\n  }\n}\n\n/** 本地镜像：让 <head> 的首帧判定（无网络）拿到上一次的偏好。 */\nfunction mirrorTheme() {\n  try {\n    localStorage.setItem(THEME_PREF_KEY, dprTheme.mode);\n    localStorage.setItem(THEME_MIRROR_KEY, JSON.stringify({ mode: dprTheme.mode, strength: dprTheme.strength, chrome: dprTheme.chrome, curve: dprTheme.curve }));\n  } catch (e) { /* 无痕模式等：镜像失败不影响本次会话 */ }\n}\n\nfunction setThemeLocal(cfg) {\n  if (cfg.mode) dprTheme.mode = cfg.mode;\n  if (typeof cfg.strength === 'number') dprTheme.strength = cfg.strength;\n  if (typeof cfg.chrome === 'boolean') dprTheme.chrome = cfg.chrome;\n  if (cfg.curve) dprTheme.curve = { brightness: cfg.curve.brightness, contrast: cfg.curve.contrast };\n  else dprTheme.curve = { brightness: DARK_STRENGTHS[dprTheme.strength][0], contrast: DARK_STRENGTHS[dprTheme.strength][1] };\n  mirrorTheme();\n  applyPdfTheme();\n  syncThemeControls();\n}\n\nfunction syncThemeControls() {\n  const m = $('cfg-theme-mode'); if (m) m.value = dprTheme.mode;\n  const st = $('cfg-theme-strength'); if (st) st.value = String(dprTheme.strength);\n  const ch = $('cfg-theme-chrome'); if (ch) ch.checked = dprTheme.chrome;\n  // 模式关闭/强制浅色时，深色相关选项没有生效面：禁用置灰，不留「改了却看似生效」的误导\n  if (st) st.disabled = dprTheme.mode === 'off' || dprTheme.mode === 'light';\n  if (ch) ch.disabled = dprTheme.mode === 'off' || dprTheme.mode === 'light';\n  const hint = $('cfg-theme-hint');\n  if (hint) hint.title = '深色是整页反色 + 色相回正：图片/照片会明显褪色偏色（实测纯红 [255,0,0] → 浅粉 [229,134,134]，不是真负片）；下载/导出的 PDF 始终是原文，不受影响。';\n  const chip = $('scope-chip'); if (chip) chip.textContent = '范围：' + (askScopeMode() === 'topic' ? '所在专题' : '本篇');\n}\n\n/** 写后端（两处 UI 共用同一个配置；失败只 toast，不回滚本地显示——以服务端为准的语义靠下次拉取纠正）。 */\nasync function saveTheme(patch) {\n  try {\n    const r = await api('/theme/config', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify(patch) });\n    setThemeLocal({ mode: r.pdfTheme, strength: r.pdfDarkStrength, chrome: r.pdfDarkChrome, curve: r.curve });\n  } catch (e) { toast('深色设置保存失败：' + e.message, 5000); }\n}\n\nasync function loadThemeConfig() {\n  try {\n    const r = await api('/theme/config');\n    setThemeLocal({ mode: r.pdfTheme, strength: r.pdfDarkStrength, chrome: r.pdfDarkChrome, curve: r.curve });\n  } catch (e) {\n    // 服务端不可用：用镜像（没有镜像就按 follow 探测宿主）——降级，不让深色能力整体失灵\n    try {\n      const mir = JSON.parse(localStorage.getItem(THEME_MIRROR_KEY) || 'null');\n      if (mir && mir.mode) setThemeLocal(mir);\n    } catch (e2) { applyPdfTheme(); }\n  }\n}\n\n// 先用镜像+宿主探测立即上色（首帧就有正确属性），配置到货后再校正\n(function initThemeFromMirror() {\n  try {\n    const mir = JSON.parse(localStorage.getItem(THEME_MIRROR_KEY) || 'null');\n    if (mir && mir.mode) { dprTheme = { ...dprTheme, ...mir }; }\n    else { const p = localStorage.getItem(THEME_PREF_KEY); if (p) dprTheme.mode = p; }\n  } catch (e) { /* 忽略损坏镜像 */ }\n  try { applyPdfTheme() } catch (e) { /* 视觉增强失败绝不影响阅读 */ }\n})();\n\n// 宿主主题变化（dsh 切主题）→ 立刻重算；同一文档内只需挂一次 MutationObserver\n(function watchHostTheme() {\n  let d = null;\n  try { d = window.parent !== window ? window.parent.document : null; } catch (e) { d = null; }\n  if (!d || typeof MutationObserver !== 'function') return;\n  try {\n    const ob = new MutationObserver(() => applyPdfTheme());\n    ob.observe(d.body || d.documentElement, { attributes: true, attributeFilter: ['data-ds-dark-theme', 'data-ds-theme-source'] });\n    if (d.documentE