t.closest('#cfg-actions')) closeCfgPop();\n});\n$('cfg-cancel').onclick = closeCfgPop;\n\nasync function saveCfg(saveAsNew) {\n  // retry/force/translate 先捞出来：closeCfgPop 会把这三个待确认态清零\n  const btn = saveAsNew ? $('cfg-save-new') : $('cfg-save'), label = btn.textContent;\n  const retry = cfgRetryGenerate, force = cfgRetryForce, retryTr = cfgRetryTranslate;\n  btn.disabled = true; btn.textContent = '测试中…';\n  let saved;\n  try {\n    // 服务端先打一发极小的 chat/completions 验证 url/key/model，通过才落盘\n    saved = await api('/translate/config', {\n      method: 'POST',\n      headers: { 'content-type': 'application/json' },\n      body: JSON.stringify({\n        id: saveAsNew ? 'new' : cfgEditingId,\n        baseUrl: $('cfg-url').value.trim(),\n        apiKey: $('cfg-key').value.trim(),\n        model: $('cfg-model').value.trim(),\n      }),\n    });\n  } catch (e) {\n    toast('保存失败：' + e.message, 8000);\n    return;\n  } finally {\n    btn.disabled = false; btn.textContent = label;\n  }\n  closeCfgPop();\n  await refreshZhState();\n  if (retry) startGenerate(force, saved.id);  // 用刚保存的端点继续，不让旧 active 抢回去\n  else if (retryTr) translateSelection(); // 划词翻译发现没配端点 → 填完自动重试这一次翻译（§3.7①）\n  else toast('翻译端点已保存');\n}\n$('cfg-save').onclick = () => saveCfg(false);\n$('cfg-save-new').onclick = () => saveCfg(true);\n\n/* ================= PDF 渲染(pdf.js:缩放 + devicePixelRatio 高清,移植自 pdfqa) ================= */\n/* pdf.js 6.x 本地 vendor：动态 import（缓存的 Promise），loadPdf 先 await 再用——\n   底部经典脚本解析期就开跑 bootstrap()，必须由这里保证「pdf.js 就绪后才渲染」；\n   失败（vendor 404 / MIME 拒绝）抛带 URL 的可读错误，而不是莫名其妙的 ReferenceError。 */\nlet pdfjsReadyP = null;\nfunction ensurePdfjs() {\n  if (!pdfjsReadyP) {\n    pdfjsReadyP = import('/paper-reader/vendor/pdf.min.mjs').then(\n      (m) => {\n        window.pdfjsLib = m;\n        m.GlobalWorkerOptions.workerSrc = '/paper-reader/vendor/pdf.worker.min.mjs';\n        return m;\n      },\n      (e) => {\n        pdfjsReadyP = null; // 失败后清缓存：瞬时故障不至于让本页签永久坏掉，下次 loadPdf 重试\n        throw n