e != null) {\n    const e = pages.get(anchor.page)\n    if (e) pane.scrollTop = (e.div.offsetTop || 0) + (anchor.ratio || 0) * (e.div.offsetHeight || 0)\n  } else if (!opts.startPage) {\n    pane.scrollTop = 0 // 新文献首帧：上一页的滚动位置不得带过来\n  }\n  if (opts.observe !== false) {\n    setupLazyObserver(lv)\n    observePages(container)\n  }\n  const start = Math.min(Math.max(1, anchor?.page || opts.startPage || curPage), doc.numPages)\n  await ensureLazyPage(start)\n}\n\n/** 当前页是不是懒视图里的占位：跳转/查找前先把它画出来。 */\nasync function ensurePageReadyForJump(n) {\n  if (!lazyView) return\n  const i = Math.min(Math.max(1, (n | 0) || 1), lazyView.doc.numPages)\n  await ensureLazyPage(i)\n}\n\n/** 翻页模式：只渲染 curPage 一页（按需渲染，天然无长文档性能问题）。 */\nasync function renderPaged(opts = {}) {\n  if ($('pdf-pane').clientHeight === 0 && !opts.pane) { pendingRerender = true; return; } // 同 renderAllPages：跳过并标记，恢复后补画\n  teardownLazy()\n  const doc = opts.doc || pdfDoc;\n  const container = opts.container || $('pdf-pages');\n  const scale = opts.scale ?? zoomScale;\n  const docKey = opts.docKey || (zhVariant ? 'zh' : 'orig');\n  if (!doc) return;\n  const pageNo = Math.min(Math.max(1, opts.page ?? curPage), doc.numPages);\n  const token = ++renderToken;\n  if (!opts.noUi) {\n    curPage = pageNo;\n    container.innerHTML = '';\n    clearEqGeometry(); // 同上：翻页模式下换页/缩放时，旧页几何与 hover 残留必须一起作废（否则命中整体偏移）\n    container.classList.add('paged');\n    $('zoom-label').textContent = Math.round(scale / 1.5 * 100) + '%';\n    updatePager();\n  } else {\n    container.innerHTML = '';\n    container.classList.add('paged');\n  }\n  const page = await getPageForRender(doc, pageNo, token);\n  if (!page || token !== renderToken) return;\n  const viewport = page.getViewport({ scale });\n  const div = makePageNode(pageNo, viewport, docKey);\n  container.appendChild(div);\n  await paintPage(page, div, viewport, token);\n}\n\n/** 滚动模式当前页探测：视口竖直中线带（±45%）压到哪页，哪页就是当前页。\n    每次全量重渲后重建（页节点全换）。翻页控件与模式切换共享 curPage。 */\nlet pageObserver = null;\nfunction observePages(container = $('pdf-pages')) {\n  pageObserver?.disconnect();\n  pageObserver = new IntersectionObserver((entries) => {\n    for (const en of entries) {\n      if (en.isIntersecting) {\n        curPage = +en.target.dataset.page || curPage;\n        updatePager();\n      }\n    }\n  }, { root: $('pdf-pane'), rootMargin: '-45% 0px -45% 0px', threshold: 0 });\n  container.querySelectorAll('.page').forEach((d) => pageObserver.observe(d));\n}\n\nfunction setZoom(newScale) { if (!pdfDoc) return Promise.resolve(); zoomScale = Math.min(4.5, Math.max(0.6, newScale)); return rerender().catch(() => {}) }\n// 默认适宽：rightbar 窄列里 1.5 倍缩放会把页面撑出视口（中英对照双栏页宽≈2×，更明显）\nlet fitMode = true;\nconst fitBtn = $('zoom-fit');\nfitBtn.classList.add('active');\nfunction exitFitMode() { fitMode = false; fitBtn.classList.remove('active'); }\n/** 适宽的可用宽度（分屏时按**较窄的那一列**算，保证两列页高一致）。每列 padding 16px×2。 */\nfunction fitPaneWidth() {\n  if (viewMode === 'split') {\n    const avail = [$('pdf-pane').clientWidth - 32, $('pdf-pane-zh').clientWidth - 32].filter((w) => w > 0)\n    if (!avail.length) return 0\n    return Math.min(...avail)\n  }\n  return $('pdf-pane').clientWidth - 32\n}\nfunction fitToWidth() {\n  if (!pdfDoc) return Promise.resolve() // resize 可能先于首次 loadPdf 触发（布局换位/条带注入会改容器尺寸）\n  const paneWidth = fitPaneWidth()\n  if (paneWidth <= 0) return Promise.resolve() // 隐藏期间尺寸为 0，算出的缩放无意义\n  const doc = pdfDoc\n  return doc.getPage(1).then((p) => {\n    if (pdfDoc !== doc) return // 期间换了文档：旧文档的适宽结果必须丢弃\n    return setZoom(paneWidth / p.getViewport({ scale: 1 }).width)\n  }).catch(() => { /* 文档已被新的 loadPdf 释放 */ })\n}\n$('zoom-in').onclick = () => { exitFitMode(); setZoom(zoomScale + 0.25); };\n$('zoom-out').onclick = () => { exitFitMode(); setZoom(zoomScale - 0.25); };\nfitBtn.onclick = () => { if (!pdfDoc) return; fitMode = true; fitBtn.classList.add('active'); fitBtn.blur(); fitToWidth(); };\nwindow.addEventListener('resize', () => {\n  if (viewMode === 'split' && window.innerWidth < SPLIT_MIN_WIDTH) {\n    // 分屏被缩到硬闸门以下：回落原文 + 同一提示（§4.2）\n    toast('面板太窄，请把阅读器拉宽后再用分屏对照', 4000);\n    setViewMode('orig');\n    return;\n  }\n  if (fitMode) fitToWidth(); // setZoom → rerender，顺带消化 pendingRerender\n  else if (pendingRerender && pdfDoc) { pendingRerender = false; rerender().catch(() => {}); } // 隐藏期间欠下的重渲，恢复尺寸后补画\n});\n\n/** 原文列的页节点：分屏时中文列有**同样的 page 号**，不加限定会取到中文列（C18/R7）。\n *  统一收敛到 `#pdf-pages` 之下——四个引文高亮/跳转入口共用。 */\nfunction origPageNode(n) {\n  return document.querySelector(`#pdf-pages .page[data-page=\"${n}\"]`);\n}\n\n/* ================= 翻页模式：页码控件 + 模式切换 + 键盘 ================= */\nfunction flashPage() {\n  const div = origPageNode(curPage);\n  if (!div) return;\n  div.classList.add('flash');\n  setTimeout(() => div.classList.remove('flash'), 1600);\n}\n\n/** 页码控件刷新：输入框（未聚焦时才回写，别打断正在敲页码的人）/总页数/首末页禁用。 */\nfunction updatePager() {\n  const total = pdfDoc ? pdfDoc.numPages : 0;\n  $('page-total').textContent = '/ ' + (total || '?');\n  const input = $('page-input');\n  if (document.activeElement !== input) input.value = total ? curPage : '';\n  $('page-prev').disabled = pageMode === 'paged' && curPage <= 1;\n  $('page-next').disabled = pageMode === 'paged' && curPage >= total;\n}\n\n/** 跳到第 n 页（夹取）：paged 重渲单页+闪烁；scroll 平滑滚到该页。 */\nasync function goPage(n) {\n  if (!pdfDoc) return;\n  const p = Math.min(Math.max(1, (n | 0) || 1), pdfDoc.numPages);\n  if (pageMode === 'paged') {\n    if (p === curPage) { flashPage(); return; }\n    curPage = p;\n    await rerender();\n    flashPage();\n  } else {\n    curPage = p;\n    jumpToPage(p);\n    if (lazyView) void ensureLazyPage(p);\n  }\n}\n\n$('page-prev').onclick = () => goPage(curPage - 1);\n$('page-next').onclick = () => goPage(curPage + 1);\nfunction commitPageInput() {\n  const v = parseInt($('page-input').value, 10);\n  if (Number.isFinite(v) && v >= 1) goPage(v);\n  else updatePager(); // 非法输入：恢复当前页显示\n}\n// Enter 走 blur 统一提交；Escape 只恢复显示不跳页（标志位让 blur 知道这是放弃编辑）\nlet pageInputEscaped = false;\n$('page-input').addEventListener('keydown', (e) => {\n  if (e.key === 'Enter') { e.preventDefault(); e.target.blur(); }\n  else if (e.key === 'Escape') { pageInputEscaped = true; e.target.blur(); }\n});\n$('page-input').addEventListener('blur', () => {\n  if (pageInputEscaped) { pageInputEscaped = false; updatePager(); return; }\n  commitPageInput();\n});\n\n/** 模式切换：paged→scroll 先全量渲染再跳回当前页；scroll→paged 用观察器最近回写的 curPage。\n    图标显示「当前模式」：书本 = 单页翻页（active）/ 卷轴 = 连续滚动。 */\nfunction updateModeToggle() {\n  const btn = $('mode-toggle');\n  btn.innerHTML = iconHtml(pageMode === 'paged' ? 'paged' : 'scroll');\n  btn.classList.toggle('active', pageMode === 'paged');\n  btn.title = pageMode === 'paged' ? '当前：单页翻页，点击切回连续滚动' : '当前：连续滚动，点击切到单页翻页';\n  updatePager();\n}\n$('mode-toggle').onclick = async () => {\n  if (!pdfDoc) return;\n  pageMode = pageMode === 'paged' ? 'scroll' : 'paged';\n  localStorage.setItem('dpr.pageMode', pageMode);\n  updateModeToggle();\n  if (pageMode === 'paged') {\n    await rerender();          // 分屏时转 renderSplit（两列同渲 curPage）\n    flashPage();\n  } else {\n    await rerender();          // 非分屏时等价于 renderAllPages\n    jumpToPage(curPage);\n  }\n};\nupdateModeToggle();\n\n// 键盘翻页（仅 paged）：输入框聚焦/带修饰键时不抢；Space 在单页模式下无滚动量，拿来做下一页\ndocument.addEventListener('keydown', (e) => {\n  if (pageMode !== 'paged' || !pdfDoc) return;\n  const tag = (e.target.tagName || '').toUpperCase();\n  if (tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT' || e.metaKey || e.ctrlKey || e.altKey) return;\n  if (e.key === 'ArrowRight' || e.key === 'PageDown' || e.key === ' ') { e.preventDefault(); goPage(curPage + 1); }\n  else if (e.key === 'ArrowLeft' || e.key === 'PageUp') { e.preventDefault(); goPage(curPage - 1); }\n  else if (e.key === 'Home') { e.preventDefault(); goPage(1); }\n  else if (e.key === 'End') { e.preventDefault(); goPage(pdfDoc.numPages); }\n});\n\nfunction jumpToPage(n) {\n  if (pageMode === 'paged') { goPage(n); return; }\n  const div = origPageNode(n);   // 引文跳转只作用于原文列（分屏时中文列不得被滚到）\n  if (!div) return;\n  div.scrollIntoView({ behavior: 'smooth', block: 'start' });\n  div.classList.add('flash');\n  setTimeout(() => div.classList.remove('flash'), 1600);\n}\n\n/* 片段定位高亮（跳转链接的 &q= 引文）：在指定页 textLayer 里找 q、高亮并滚到它。\n   归一化时忽略空白/连字符/软连字符、大小写 —— 论文跨行断词（dis-tributed）也能命中。\n   找不到（如用户在中文界面而 q 是英文原文）返回 false，调用方退回仅跳页。 */\nfunction clearHighlights() {\n  document.querySelectorAll('.textLayer span.dpr-hl').forEach((sp) => sp.classList.remove('dpr-hl'));\n  clearEqHit(); // 公式命中描边与引文高亮同生共死（用户在别处点一下即清）\n}\n// 高亮的消失交给用户：阅读器里任意点一下即清（mousedown 比 click 早，划选文字的那一下也算）\ndocument.addEventListener('mousedown', clearHighlights);\n\nfunction highlightSnippet(page, q) {\n  const spans = [...(origPageNode(page)?.querySelectorAll('.textLayer span:not(.markedContent)') ?? [])];\n  if (!spans.length || !q) return false;\n  let hay = '';\n  const startOf = [];\n  for (const sp of spans) { startOf.push(hay.length); hay += sp.textContent; }\n  // 归一化串 + 回原串的索引映射（归一化改变长度，不能直接用原索引）\n  const map = [];\n  let nh = '';\n  for (let i = 0; i < hay.length; i++) {\n    const c = hay[i].toLowerCase();\n    if (/\\s/.test(c) || c === '-' || c === '­') continue;\n    nh += c; map.push(i);\n  }\n  const needle = q.toLowerCase().replace(/[\\s\\-­]+/g, '');\n  const at = needle ? nh.indexOf(needle) : -1;\n  if (at < 0) return false;\n  const from = map[at], to = map[at + needle.length - 1] + 1;\n  const hit = spans.filter((sp, i) => startOf[i] < to && startOf[i] + sp.textContent.length > from);\n  if (!hit.length) return false;\n  clearHighlights();\n  for (const sp of hit) sp.classList.add('dpr-hl');\n  hit[0].scrollIntoView({ behavior: 'smooth', block: 'center' });\n  return true;\n}\n\n/* 统一跳转入口：先等目标页渲染出来（fit 模式下 loadPdf 返回时页面可能还在渲），\n   有 q 就尝试片段高亮，否则整页跳转 + 边框闪烁。\n   paged 模式目标页不在 DOM 里（只渲当前页），轮询永远等不到 → 直接设页渲染。 */\nasync function jumpTo(page, q) {\n  const p0 = Math.max(1, (page | 0) || 1);\n  if (pageMode === 'paged') {\n    if (!pdfDoc) return;\n    const p = Math.min(p0, pdfDoc.numPages);\n    if (p !== curPage) { curPage = p; await rerender(); }\n    if (!(q && highlightSnippet(p, q))) flashPage();\n    return;\n  }\n  for (let i = 0; i < 100; i++) {\n    if (pdfDoc && origPageNode(Math.min(p0, pdfDoc.numPages))) {\n      const p = Math.min(p0, pdfDoc.numPages);\n      if (lazyView) await ensureLazyPage(p);\n      if (!(q && highlightSnippet(p, q))) jumpToPage(p);\n      return;\n    }\n    await new Promise((r) => setTimeout(r, 100));\n  }\n}\n\n/* ================= 公式引用（MinerU LaTeX，契约 §1） =================\n   PDF 文本层里的公式是乱码（`𝑧𝑧1 𝑧𝑧2`），鼠标选中拿不到可用内容；真相源是 MinerU\n   content_list 的 equation 块（LaTeX + bbox）。bbox 坐标系实测为「页面归一化坐标 ×1000」\n   （x÷页宽、y÷页高，各自归一），映射直接用渲染时的同一个 viewport，因此与缩放无关：\n       x = bbox[0]/1000*viewport.width ，y = bbox[1]/1000*viewport.height\n   热区外扩 6pt（实测最坏欠覆盖 4.60pt；6pt 覆盖全部 17/17 公式块）。 */\nconst EQ_PAD = 6;                 // pt（= scale 1 时的 CSS px），随 zoomScale 放大\nlet eqIndex = { source: 'none', equations: [], reason: 'no-mineru-artifact', bboxSpace: 'normalized-1000' };\nconst EQ_BY_PAGE = new Map();     // pageNo → [{eq,x0,y0,x1,y1,w,h,pad}]\nlet eqHoverId = null;\n\n/** 页节点被整体重建（renderAllPages / renderPaged 里 `container.innerHTML = ''`）时调用：\n    旧页的几何必须一起作废，否则命中测试会打到已卸载的页/上一档缩放的矩形（翻页模式下表现为\n    「点击整体偏移」）；顺手清掉跨页残留的 hover 态 —— eqHoverId 不清的话，setEqHover(id) 会在\n    `id === eqHoverId` 时提前 return，换页后鼠标停在公式上也不再出现虚线描边。 */\nfunction clearEqGeometry() {\n  EQ_BY_PAGE.clear();\n  eqHoverId = null;\n  clearEqHit();\n}\n\n/** 去掉 MinerU 文本外层 `$$`：`$$\\n\\\\pi…\\n$$` → `\\pi…` */\nfunction eqLatex(raw) {\n  return String(raw == null ? '' : raw).replace(/^\\s*\\$\\$?/, '').replace(/\\$\\$?\\s*$/, '').trim();\n}\n/** 进会话的引用串：保留 `$$` 定界（模型对数学最友好） */\nfunction eqCite(eq) { return '$$ ' + eqLatex(eq.latex) + ' $$'; }\n\n/**\n * MinerU **生效 mode**（GET /mineru/config 的 mode 字段）：'off' | 'local' | 'cloud' | null(未知)。\n * 它是「重新转录」按钮的门控依据——`source:'auto'` 会按 mode 选引擎，而 mode==='off' 时\n * auto 落到 pdf.js，pdf.js 重解析会**删掉** <文献>.mineru.md/.mineru.json 富产物\n * （src/transcribe.ts）；宁可少一个按钮，也不给一个会反噬的按钮。\n */\nlet mineruMode = null;\nasync function loadMineruMode() {\n  try {\n    const c = await api('/mineru/config');\n    mineruMode = c && typeof c.mode === 'string' ? c.mode : null;\n  } catch { mineruMode = null; }   // 取不到按「未知」处理（照常给按钮，行为与旧版一致）\n}\n\nfunction loadFormulas() {\n  return (async () => {\n    eqIndex = { source: 'none', equations: [], reason: 'no-mineru-artifact', bboxSpace: 'normalized-1000' };\n    if (!current) { renderEqPanel(); return; }\n    await loadMineruMode();\n    const q = `topic=${encodeURIComponent(current.topic)}&name=${encodeURIComponent(current.name)}`;\n    try {\n      const idx = await api('/formulas?' + q);\n      if (idx && Array.isArray(idx.equations)) eqIndex = idx;\n    } catch (e) {\n      // 接口异常绝不打崩阅读器：降级成「无公式」，划词提问照常\n      eqIndex = { source: 'none', equations: [], reason: 'bad-artifact', warning: e.message, bboxSpace: 'normalized-1000' };\n    }\n    const btn = $('eq-toggle');\n    btn.classList.toggle('muted', eqIndex.equations.length === 0);\n    btn.title = eqIndex.equations.length\n      ? `公式引用：${eqIndex.equations.length} 个（点击 PDF 上的公式即可引用其 LaTeX）`\n      : '公式引用：本论文还没有 MinerU 解析产物';\n    renderEqPanel();\n  })();\n}\n\n/** 热区只在「原文视图 + 有 bbox」时开启：译文版（-zh/-dual）页面几何与原文不同。 */\nfunction eqHotEnabled() {\n  return zhVariant === null && eqIndex.equations.some((e) => e.bbox);\n}\n\nfunction eqGeom(eq, viewport) {\n  if (!eq.bbox) return null;\n  const space = eqIndex.bboxSpace === 'page-units'; // 兜底分支（云端版本差异，见需求 R3）\n  const kx = space ? zoomScale : viewport.width / 1000;\n  const ky = space ? zoomScale : viewport.height / 1000;\n  const x = eq.bbox[0] * kx;\n  const y = eq.bbox[1] * ky;\n  const w = (eq.bbox[2] - eq.bbox[0]) * kx;\n  const h = (eq.bbox[3] - eq.bbox[1]) * ky;\n  if (!(w > 0) || !(h > 0)) return null;\n  return {\n    eq, x, y, w, h, pad: EQ_PAD * zoomScale,\n    x0: Math.max(0, x), y0: Math.max(0, y),\n    x1: Math.min(viewport.width, x + w), y1: Math.min(viewport.height, y + h),\n  };\n}\n\n/** 为已渲染的一页铺热区层（只画描边，不接事件）。\n *  **只在原文列铺**：分屏（模式 B）时中文列的页号与原文列相同，而 EQ_BY_PAGE 是全局的，\n *  照铺会让中文列的点击命中原文几何（C18/R7）。文档作用域从页节点自身读——唯一铺层点的\n *  调用签名被既有断言钉死为 `paintEqLayer(div, viewport, +div.dataset.page)`\n *  （test/merge-verify-t3.test.mjs 的 checkSolePaintPoint），不能再加第 4 个参数。 */\nfunction paintEqLayer(pageDiv, viewport, pageNo) {\n  const old = pageDiv.querySelector('.eqLayer');\n  if (old) old.remove();\n  const items = [];\n  const doc = pageDiv.dataset.doc || 'orig';\n  if (doc !== 'orig') return;   // 中文列：不建层、不写 EQ_BY_PAGE\n  if (eqHotEnabled()) {\n    const lay = document.createElement('div');\n    lay.className = 'eqLayer';\n    lay.style.width = viewport.width + 'px';\n    lay.style.height = viewport.height + 'px';\n    for (const eq of eqIndex.equations) {\n      if (eq.page !== pageNo) continue;\n      const g = eqGeom(eq, viewport);\n      if (!g) continue;\n      items.push(g);\n      const b = document.createElement('div');\n      b.className = 'eq-box';\n      b.dataset.eqId = eq.id;\n      b.style.left = g.x0 + 'px';\n      b.style.top = g.y0 + 'px';\n      b.style.width = Math.max(1, g.x1 - g.x0) + 'px';\n      b.style.height = Math.max(1, g.y1 - g.y0) + 'px';\n      lay.appendChild(b);\n    }\n    pageDiv.appendChild(lay);\n  }\n  EQ_BY_PAGE.set(pageNo, items);\n}\n\n/**\n * 命中判定（契约 §1.4）：\n *   1) 未外扩矩形包含点击点 → 取面积最小者（并列取阅读序靠前）；\n *   2) 否则取外扩后包含该点、且到未外扩矩形距离最小者（并列同上）；\n *   3) 都没有 → 不是公式点击。\n * 为什么必须严格：实测同一页相邻公式块竖直间隙最小只有 0.8pt，6pt 外扩后必然重叠。\n */\nfunction hitTestFormula(e) {\n  if (!eqHotEnabled()) return null;\n  const el = e.target;\n  const pageDiv = el && el.closest ? el.closest('.page[data-page]') : null;\n  if (!pageDiv) return null;\n  // 中文列（分屏）不得命中：它的页号与原文列相同，几何却属于原文页面（C18/R7）\n  if (pageDiv.dataset.doc && pageDiv.dataset.doc !== 'orig') return null;\n  const items = EQ_BY_PAGE.get(+pageDiv.dataset.page);\n  if (!items || !items.length) return null;\n  const box = pageDiv.getBoundingClientRect();\n  const px = e.clientX - box.left;\n  const py = e.clientY - box.top;\n  let best = null;\n  for (const it of items) {\n    if (px >= it.x0 && px <= it.x1 && py >= it.y0 && py <= it.y1) {\n      if (!best || it.w * it.h < best.w * best.h) best = it;\n    }\n  }\n  if (best) return best;\n  let bestD = Infinity;\n  for (const it of items) {\n    if (px < it.x0 - it.pad || px > it.x1 + it.pad || py < it.y0 - it.pad || py > it.y1 + it.pad) continue;\n    const dx = px < it.x0 ? it.x0 - px : (px > it.x1 ? px - it.x1 : 0);\n    const dy = py < it.y0 ? it.y0 - py : (py > it.y1 ? py - it.y1 : 0);\n    const d = dx * dx + dy * dy;\n    if (d < bestD - 1e-6) { bestD = d; best = it; }\n    else if (Math.abs(d - bestD) <= 1e-6 && best && it.w * it.h < best.w * best.h) best = it;\n  }\n  return best;\n}\n\nfunction setEqHover(id) {\n  if (id === eqHoverId) return;\n  eqHoverId = id;\n  document.querySelectorAll('.eq-box.hover').forEach((el) => el.classList.remove('hover'));\n  if (id) {\n    const el = document.querySelector(`.eq-box[data-eq-id=\"${id}\"]`);\n    if (el) el.classList.add('hover');\n  }\n}\n\nfunction clearEqHit() { document.querySelectorAll('.eq-box.hit').forEach((el) => el.classList.remove('hit')); }\n\nfunction markEqHit(eq) {\n  clearEqHit();\n  const el = document.querySelector(`.eq-box[data-eq-id=\"${eq.id}\"]`);\n  if (el) el.classList.add('hit');\n}\n\n/** 引用一个公式：热区点击与面板条目共用这一条链路（契约 §1.5）。 */\nfunction citeFormula(eq, x, y) {\n  askSelection = {\n    text: eqCite(eq),\n    page: eq.page,\n    kind: 'equation',\n    latex: eqLatex(eq.latex),\n    equationIndex: eq.index,\n  };\n  markEqHit(eq);\n  const tag = `第 ${eq.page} 页 · 公式 ${eq.index}`;\n  const body = eqLatex(eq.latex).replace(/\\s+/g, ' ');\n  showAskPop({ quote: body ? `${tag}：${body}` : tag, x, y });\n}\n\nfunction renderEqPanel() {\n  const meta = $('eq-meta');\n  const list = $('eq-list');\n  const eqs = eqIndex.equations;\n  list.innerHTML = '';\n  if (eqs.length) {\n    const src = [eqIndex.producer || 'MinerU', eqIndex.backend].filter(Boolean).join(' · ');\n    meta.textContent = `${eqs.length} 个公式 · ${src}${eqIndex.warning ? '（' + eqIndex.warning + '）' : ''}`;\n  } else {\n    meta.textContent = '';\n  }\n  if (zhVariant !== null) {\n    const n = document.createElement('div');\n    n.id = 'eq-note';\n    n.textContent = '当前是译文视图：没有公式位置信息（bbox 只对原文页面成立），切回原文即可点击公式。';\n    list.appendChild(n);\n  }\n  if (!eqs.length) {\n    const n = document.createElement('div');\n    n.id = 'eq-note';\n    n.textContent = eqIndex.reason === 'bad-artifact'\n      ? 'MinerU 产物损坏或不可读，已忽略（不影响阅读与划词提问）。'\n      : eqIndex.reason === 'no-equations'\n        ? '这篇论文没有解析出公式块（MinerU 产物存在，但 content_list 里没有 equation）。'\n        : mineruMode === 'off'\n          ? '未启用 MinerU：请到 dsh 设置 → 论文伴读 → MinerU 解析后端 选择「本地」或「云端」并保存，然后回到这里点「重新转录」。'\n          : '未找到 MinerU 解析产物。在 dsh 设置 → 论文伴读 → MinerU 解析后端 启用后点下面按钮重新转录。';\n    list.appendChild(n);\n    // 门控：mode==='off' 时不渲染按钮（auto 会落到 pdf.js 并删掉已有的 MinerU 富产物）；\n    // mode 未知（接口不可用）时照旧给按钮，保持与旧版一致的行为。\n    const canRetranscribe = (eqIndex.reason === 'no-mineru-artifact' || eqIndex.reason === 'no-equations') && mineruMode !== 'off';\n    if (canRetranscribe) {\n      const b = document.createElement('button');\n      b.id = 'eq-transcribe';\n      b.className = 'tbtn';\n      b.textContent = '用 MinerU 重新转录';\n      b.onclick = () => transcribeWithMineru(b);\n      list.appendChild(b);\n    }\n    return;\n  }\n  const byPage = new Map();\n  for (const eq of eqs) {\n    if (!byPage.has(eq.page)) byPage.set(eq.page, []);\n    byPage.get(eq.page).push(eq);\n  }\n  for (const [page, arr] of byPage) {\n    const h = document.createElement('div');\n    h.className = 'eq-page';\n    h.textContent = `第 ${page} 页`;\n    list.appendChild(h);\n    for (const eq of arr) {\n      const item = document.createElement('button');\n      item.type = 'button';\n      item.className = 'eq-item';\n      item.dataset.eqId = eq.id;\n      const tag = document.createElement('span');\n      tag.className = 'eq-tag';\n      tag.textContent = `公式 ${eq.index}${eq.bbox ? '' : ' · 无位置信息'}`;\n      const code = document.createElement('code');\n      code.textContent = eqLatex(eq.latex) || '(空)';\n      item.appendChild(tag);\n      item.appendChild(code);\n      item.onclick = () => {\n        const r = item.getBoundingClientRect();\n        citeFormula(eq, r.left, r.bottom + 6);\n      };\n      list.appendChild(item);\n    }\n  }\n}\n\nfunction transcribeResultText(t) {\n  const chars = typeof t.chars === 'number' ? `（${t.chars} 字符）` : '';\n  const engine = t.producer === 'mineru-local' || t.producer === 'mineru-cloud' ? 'MinerU' : 'pdf.js';\n  if (t.source === 'cache') return `已有 ${engine} 转录缓存，直接复用${chars}`;\n  return `${engine} 转录完成${chars}`;\n}\n\n$('transcribe-open').onclick = async () => {\n  if (!current) return;\n  const ref = { ...current };\n  const btn = $('transcribe-open');\n  const samePaper = () => current && current.topic === ref.topic && current.name === ref.name;\n  btn.disabled = true;\n  btn.textContent = '转录中…';\n  $('status').textContent = '转录中（可能需要几十秒）…';\n  try {\n    const t = await api('/transcribe', {\n      method: 'POST',\n      headers: { 'content-type': 'application/json' },\n      // 与公式面板的重转录共用后端选择：local/cloud 走 MinerU，off 走 pdf.js；\n      // 顶栏入口只在无缓存时出现，因此不强制覆盖已有转录。\n      body: JSON.stringify({ ...ref, force: false, source: 'auto' }),\n    });\n    if (!samePaper()) return;\n    currentHasTranscript = true;\n    statusMeta = `${ref.name} · ${t.pageCount ?? '?'} 页`;\n    $('status').textContent = statusMeta;\n    syncTranscribeButton();\n    toast(transcribeResultText(t));\n    await loadFormulas();\n    if (pdfDoc) await rerender();\n  } catch (e) {\n    if (samePaper()) {\n      $('status').textContent = statusMeta;\n      toast('转录失败：' + e.message, 6000);\n    }\n  } finally {\n    if (samePaper()) {\n      btn.disabled = false;\n      btn.textContent = '转录';\n      syncTranscribeButton();\n    }\n  }\n};\n\nasync function transcribeWithMineru(btn) {\n  if (!current) return;\n  const old = btn.textContent;\n  btn.disabled = true;\n  btn.textContent = '转录中（可能需要几十秒）…';\n  try {\n    await api('/transcribe', {\n      method: 'POST',\n      headers: { 'content-type': 'application/json' },\n      // source:'auto' = 按**当前生效 mode** 选引擎（local → 本地 MinerU；cloud → mineru.net 云端；\n      // off → pdf.js）。硬编码 'mineru-local' 会让配了云端的用户点一次失败一次（上游评审第 6 条）。\n      // 按钮本身在 mode==='off' 时不渲染（见 renderEqPanel 的门控），所以走到这里 mode 必为 local/cloud。\n      body: JSON.stringify({ ...current, force: true, source: 'auto' }),\n    });\n    toast('MinerU 转录完成');\n    await loadFormulas();\n    // 新索引到手：按**当前模式**重渲一次把热区铺上去（翻页模式下必须仍是 renderPaged，\n    // 否则会把全量页渲出来、摘掉 #pdf-pages 的 paged 类，与顶栏模式切换按钮的 active 状态脱节）\n    if (pdfDoc) await rerender();\n  } catch (e) {\n    toast('MinerU 转录失败：' + e.message, 6000);\n  } finally {\n    if (document.body.contains(btn)) { btn.disabled = false; btn.textContent = old; }\n  }\n}\n\n$('eq-toggle').onclick = () => {\n  const open = $('eq-panel').style.display !== 'block';\n  $('eq-panel').style.display = open ? 'block' : 'none';\n  $('eq-toggle').classList.toggle('active', open);\n};\n\n/* ================= 顶栏收纳：视图 / 更多 弹出菜单 =================\n   语言视图四态（译/对照/分屏）+ 重译收进「视图」下拉，深色/公式/设置收进「⋯」。\n   原按钮 DOM 保留（.tucked 隐藏）：菜单项转发它们的 click，状态机\n   （updateViewButtons / refreshZhState）零改动；菜单渲染只**读**原按钮态，\n   不在菜单里维护第二份状态。 */\nfunction closeBarMenus() {\n  $('view-menu').hidden = true;\n}\nfunction viewMenuLabel() {\n  if (viewMode === 'split') return '分屏';\n  if (viewMode === 'dual') return '对照';\n  if (viewMode === 'zh') return '中文';\n  return '原文';\n}\nfunction syncViewMenu() {\n  const btn = $('view-menu-btn'); if (!btn) return;\n  const label = viewMenuLabel();\n  btn.textContent = '视图：' + label + ' ▾';\n  btn.classList.toggle('active', label !== '原文');\n  const items = {\n    zh: [zhVariant !== null, $('zh-toggle').disabled, $('zh-toggle').title],\n    dual: [viewMode === 'dual', $('dual-toggle').disabled, $('dual-toggle').title],\n    split: [viewMode === 'split', $('split-toggle').disabled, $('split-toggle').title],\n  };\n  for (const [act, [active, disabled, title]] of Object.entries(items)) {\n    const el = $('view-menu').querySelector('[data-act=\"' + act + '\"]');\n    if (!el) continue;\n    el.classList.toggle('active', !!active);\n    el.disabled = !!disabled;\n    if (title) el.title = title;\n  }\n  const origEl = $('view-menu').querySelector('[data-act=\"orig\"]');\n  if (origEl) origEl.classList.toggle('active', label === '原文');\n  // 重译：与 refreshZhState 的 canRegen 同判据（有译文且空闲）\n  const regenEl = $('view-menu').querySelector('[data-act=\"regen\"]');\n  if (regenEl) {\n    regenEl.disabled = !((zhState.zh || zhState.dual) && !zhState.busy);\n    regenEl.title = $('zh-regen').title;\n  }\n}\n\nfunction openBarMenu(menuId, btnId) {\n  closeBarMenus();\n  syncViewMenu();\n  const menu = $(menuId), btn = $(btnId);\n  menu.hidden = false;\n  const br = $('bar').getBoundingClientRect(), r = btn.getBoundingClientRect();\n  // 锚在**按钮正下方**而非 #bar 底部：窄窗口下顶栏 flex-wrap 换行会把 bar 撑到数百像素高，\n  // 「bar 底部 + 6px」把菜单顶到视口外（实测 399px 宽 iframe → 菜单 y=960 > 视口 954，开了但看不见）\n  menu.style.top = (r.bottom - br.top + 6) + 'px';\n  menu.style.left = Math.max(4, Math.min(r.left - br.left, br.width - menu.offsetWidth - 4)) + 'px';\n}\n$('view-menu-btn').onclick = (e) => {\n  e.stopPropagation();\n  if ($('view-menu').hidden) openBarMenu('view-menu', 'view-menu-btn'); else closeBarMenus();\n};\n$('view-menu').onclick = (e) => {\n  const b = e.target.closest('button'); if (!b) return;\n  closeBarMenus();\n  const act = b.dataset.act;\n  if (act === 'orig') void setViewMode('orig');\n  else if (act === 'zh') $('zh-toggle').click();\n  else if (act === 'dual') $('dual-toggle').click();\n  else if (act === 'split') $('split-toggle').click();\n  else if (act === 'regen') $('zh-regen').click();\n};\ndocument.addEventListener('click', (e) => {\n  if (e.target.closest('.bar-menu') || e.target.closest('#view-menu-btn')) return;\n  closeBarMenus();\n});\ndocument.addEventListener('keydown', (e) => { if (e.key === 'Escape') closeBarMenus(); });\n\nlet lastMove = { x: -1, y: -1 };\ndocument.addEventListener('mousemove', (e) => {\n  if (!eqHotEnabled()) { setEqHover(null); return; }\n  if (Math.abs(e.clientX - lastMove.x) < 2 && Math.abs(e.clientY - lastMove.y) < 2) return;\n  lastMove = { x: e.clientX, y: e.clientY };\n  const hit = hitTestFormula(e);\n  setEqHover(hit ? hit.eq.id : null);\n});\n\n/* ================= 选中即问（文字 + 公式共用一条链路） ================= */\nconst askPop = $('ask-pop');\nlet askSelection = null;\n// 拖拽起点：公式「点击」判定要求 mousedown→mouseup 位移很小（拖选文字不算点击）\nlet downPt = null;\n\n/** 弹层共用的展示动作（文字引用与公式引用都走这里）。 */\nfunction showAskPop(o) {\n  $('ask-quote').textContent = o.quote.length > 140 ? o.quote.slice(0, 140) + '…' : o.quote;\n  $('ask-input').value = '';\n  $('ask-copy').style.display = askSelection && askSelection.kind === 'equation' ? 'inline-block' : 'none';\n  // 「译」只在「纯文字选区 + 原文视图 + **原文列** + 长度可翻译」时出现。\n  // 分屏（模式 B）时 zhVariant 刻意保持 null（C17），中文列也满足那个条件 —— 但中文列的字符\n  // 在 collectSelectionChars 里会被整体跳过（几何只对原文页成立）⇒ chunks 为空、只会弹\n  // 「选区已失效」。所以这里按列禁用（R-07：e.target/doc 判别），不给误导性文案。\n  $('ask-translate').style.display =\n    askSelection && askSelection.kind === 'text' && zhVariant === null\n      && (askSelection.doc ?? 'orig') === 'orig'\n      && askSelection.text.length <= MAX_SELECTION_CHARS\n      ? 'inline-block' : 'none';\n  // 笔记 / 全局搜索：只对文字选区出现（公式引用没有可标注/可搜索的正文）\n  const textSel = !!(askSelection && askSelection.kind === 'text');\n  $('ask-note').style.display = textSel ? 'inline-block' : 'none';\n  $('ask-find').style.display = textSel ? 'inline-block' : 'none';\n  hideTrPop(); // 新选区/新引用出现即收起上一个译文气泡（同一锚点必然重叠）\n  invalidateTranslate(); // R-01：新选区/新引用必须让在飞请求失效，否则旧译文会盖到新锚点上\n  askPop.style.display = 'block';\n  // 夹在 iframe 视口内（rightbar 窄列里也要能用）\n 