ontinue; }\n    // \\(…\\) 行内 / \\[…\\] 独立成行：与 $ 一样，必须找到闭合才认（否则按字面字符处理）\n    if (s[i] === '\\\\' && (s[i + 1] === '(' || s[i + 1] === '[')) {\n      const display = s[i + 1] === '[';\n      const closeSeq = display ? '\\\\]' : '\\\\)';\n      let j = i + 2;\n      let close = -1;\n      while (j < s.length) {\n        if (s[j] === '\\\\') {\n          if (s[j + 1] === (display ? ']' : ')')) { close = j; break; }\n          j += 2; continue;\n        }\n        if (!display && s[j] === '\\n') break;   // 行内不跨行（同 $…$ 的口径）\n        j += 1;\n      }\n      const tex = close === -1 ? '' : s.slice(i + 2, close);\n      if (close !== -1 && tex.trim() && looksLikeMath(tex)) {\n        flush();\n        out.push({ kind: 'math', text: tex, display, delim: closeSeq });\n        i = close + 2;\n        continue;\n      }\n      buf += s.slice(i, i + 2); i += 2; continue;   // 不闭合/不像数学 → 原样当文本\n    }\n    if (s[i] !== '$') { buf += s[i]; i += 1; continue; }\n    const display = s[i + 1] === '$';\n    const open = display ? 2 : 1;\n    let j = i + open;\n    let close = -1;\n    while (j < s.length) {\n      if (s[j] === '\\\\') { j += 2; continue; }\n      if (display ? (s[j] === '$' && s[j + 1] === '$') : (s[j] === '$')) { close = j; break; }\n      if (!display && s[j] === '\\n') break;          // 行内公式不跨行\n      j += 1;\n    }\n    if (close === -1) { buf += s.slice(i, i + open); i += open; continue; }\n    const tex = s.slice(i + open, close);\n    if (!tex.trim() || !looksLikeMath(tex)) { buf += s.slice(i, close + open); i = close + open; continue; }\n    flush();\n    out.push({ kind: 'math', text: tex, display, delim: open === 2 ? '$$' : '$' });\n    i = close + open;\n  }\n  flush();\n  return out;\n}\n\n/* 模式解析：MinerU 的**展示公式**常带 `\\tag{}`（KaTeX 硬规则：\\tag 只允许展示模式），而服务端\n   `assembleSource` 会把展示公式统一包成**行内 `$…$`** ⇒ 按 `display:false` 渲染必失败（pr7 诊断 P1：\n   35/37 真实 equation 命中）。这里先按切分结果探测，失败再按**另一种模式**探测：\n   只有真的行内渲染不了时才升级成展示模式 ⇒ **零误伤**（不会把普通行内公式变成块级）。\n   两种都失败返回 null，交给