k ? 'div' : 'span');\n    el.className = block ? 'tr-math tr-math-block' : 'tr-math';\n    let ok = mode !== null;\n    if (ok) { try { renderMathSegment(el, seg.text, mode); } catch { ok = false; } }\n    if (!ok) {\n      el.className = 'tr-math tr-math-fallback';\n      const delim = seg.delim ?? (seg.display ? '$$' : '$');\n      el.textContent = delim + seg.text + delim;        // 降级：原始 LaTeX 原样可见、可复制\n      failed.push(n);\n    }\n    host.appendChild(el);\n  }\n  return failed;\n}\n\n/** #tr-note 文案（**仍是纯文本**）：原有提示 + 渲染失败提示，如「第 2、5 个公式未能渲染（已按原样显示 LaTeX）」。 */\nfunction trComposeNote(note, failed) {\n  const base = String(note ?? '');\n  if (!failed || !failed.length) return base;\n  const which = failed.length === 1 ? `第 ${failed[0]} 个公式` : `第 ${failed.join('、')} 个公式`;\n  const hint = `${which}未能渲染（已按原样显示 LaTeX）`;\n  return base ? `${base} ${hint}` : hint;\n}\n\n/** 展示译文气泡。**绝不 innerHTML 模型输出**：文本段 textContent，数学段交 trRenderBody 渲染进新建元素。\n *  定位照 openCfgPop：先显示再量尺寸，不写死宽高常量。 */\nfunction showTrPop(status, body, note) {\n  $('tr-status').textContent = status || '';\n  const failed = trRenderBody(body || '');\n  $('tr-note').textContent = trComposeNote(note, failed);\n  trPop.style.display = 'block';\n  let rect = { left: 16, bottom: 16 };\n  try { if (askSelection && askSelection.range) rect = askSelection.range.getBoundingClientRect(); } catch { /* 选区失效用兜底锚点 */ }\n  trPop.style.left = Math.max(8, Math.min(rect.left, window.innerWidth - trPop.offsetWidth - 8)) + 'px';\n  trPop.style.top = Math.max(8, Math.min(rect.bottom + 8, window.innerHeight - trPop.offsetHeight - 8)) + 'px';\n}\n\n/** 归属判定（§3.3① 冻结规则）：**字符矩形中心点落在 equation 盒内**（不用「有任何交叠」——\n *  实测 2/18 例会把下一行正文吞进来）；并列取面积最小者（与既有热区点击 hitTestFormula 同规则）。 */\nfunction formulaBoxByCenter(rect, items) {\n  if (!items || !items.length) return null;\n  const cx = (rect[0] + rect[2]) / 2, cy = (rect[1] + rect[3]) / 2;\n  let best = null;\n  for (const it of items) {\n    if (cx >= it.x0 && cx <= it.x1 && cy >= it.y0 && cy <= it.y1) {\n      if (!best || it.w * it.h < best.w * best.h) best = it;\n    }\n  }\n  return best;\n}\n\n/** 当前页几何（paintEqLayer 写进 EQ_BY_PAGE 的 items）。仅在原文视图 + 有 bbox 时可用。 */\nfunction eqItemsFor(pageNo) {\n  if (!eqHotEnabled()) return null;\n  return EQ_BY_PAGE.get(pageNo) || null;\n}\n\n/** 字符序列 → chunk 序列（§3.2-6 冻结切法）。\n *  chars: [{ch, page, rect}]（rect 为页面局部 px；缺失/退化的字符按纯文本处理）\n *  规则：同页 + 同归属 + 无换行的最大连续段；换行是 text 段的结尾字符；公式段整体丢弃乱码、\n *  换成紧凑 LaTeX（`$` 定界在服务端加）。 */\nfunction buildChunks(chars, itemsByPage) {\n  const out = [];\n  let cur = null;\n  const flush = () => { if (cur) out.push(cur); cur = null; };\n  for (const c of chars) {\n    // 命中物是热区几何 {eq, x0, y0, x1, y1, …}（见 eqGeom）；公式本体在 .eq 上\n    const hit = c.rect ? formulaBoxByCenter(c.rect, itemsByPage ? itemsByPage(c.page) : null) : null;\n    const entry = hit ? hit.eq : null;\n    const kind = entry ? 'formula' : 'text';\n    if (c.ch === '\\n' && kind === 'text') {\n      if (cur && cur.kind === 'text') { cur.text += '\\n'; flush(); }\n      else { flush(); out.push({ page: c.page, kind: 'text', text: '\\n' }); }\n      continue;\n    }\n    if (cur && cur.page === c.page && cur.kind === kind && (kind === 'text' || cur.eqId === entry.id)) {\n      if (kind === 'text') cur.text += c.ch;\n      continue; // formula：同一条公式的后续字符直接丢弃（LaTeX 是原子的）\n    }\n    flush();\n    cur = kind === 'formula'\n      ? { page: c.page, kind: 'formula', latex: eqLatex(entry.latex), eqId: entry.id }\n      : { page: c.page, kind: 'text', text: c.ch };\n  }\n  flush();\n  // 规模闸门：段数 ≤200、单段 text ≤4000、总长 ≤8000（超限从尾部截断，并让调用方提示）\n  const capped = [];\n  let total = 0;\n  for (const c of out) {\n    const payload = c.kind === 'text' ? c.text : c.latex;\n    if (capped.length >= MAX_CHUNKS) break;\n    const room = MAX_TOTAL_CHARS - total;\n    if (room <= 0) break;\n    let s = payload;\n    const cap = c.kind === 'text' ? Math.min(MAX_SELECTION_CHARS, room) : room;\n    if (s.length > cap) {\n      // 截断回退到码点边界：slice 按 UTF-16 码元计数，切开代理对（数学斜体 𝑋 等）会让\n      // 翻译请求带孤立代理项、上游整轮 400（issue #9 同类）。宁可短 1 个码元。\n      let cut = cap;\n      const before = s.charCodeAt(cut - 1);\n      if (before >= 0xd800 && before <= 0xdbff && cut > 1) cut -= 1;\n      s = s.slice(0, cut);\n    }\n    if (!s) continue;\n    total += s.length;\n    capped.push(c.kind === 'text' ? { page: c.page, kind: 'text', text: s } : { page: c.page, kind: 'formula', latex: s });\n  }\n  return capped;\n}\n\n/** 选区覆盖的文本节点（按文档序）。手写递归而不是 createTreeWalker：\n *  选区只需要「起点与终点之间的文本节点」，而 TreeWalker 在部分 webview/测试桩里缺实现。 */\nfunction textNodesUnder(node) {\n  const out = [];\n  const stack = [node];\n  while (stack.length) {\n    const n = stack.pop();\n    if (!n) continue;\n    if (n.nodeType === 3) { out.push(n); continue; }\n    const kids = n.childNodes ? [...n.childNodes] : [];\n    for (let i = kids.length - 1; i >= 0; i--) stack.push(kids[i]);\n  }\n  return out;\n}\n\n/** 选区内每个字符 + 它的页面局部矩形（页面局部 = rect 减 pageDiv 的 bounding rect；\n *  `.page` 上没有 CSS transform，缩放体现在 viewport 尺寸里 ⇒ 与滚动/翻页/缩放都无关，\n *  与既有 hitTestFormula 用的是同一套坐标）。 */\nfunction collectSelectionChars(range) {\n  const root = range.commonAncestorContainer;\n  if (!root) return [];\n  const nodes = textNodesUnder(root).filter((n) => {\n    if (typeof range.intersectsNode === 'function') { try { return range.intersectsNode(n); } catch { return true; } }\n    return n === range.startContainer || n === range.endContainer;\n  });\n  const out = [];\n  for (const node of nodes) {\n    const data = node.data ?? '';\n    let start = 0, end = data.length;\n    if (node === range.startContainer) start = range.startOffset;\n    if (node === range.endContainer) end = range.endOffset;\n    const parent = node.parentElement;\n    const pageDiv = parent && parent.closest ? parent.closest('.page[data-doc]') : null;\n    if (!pageDiv) continue;\n    const doc = pageDiv.dataset.doc || 'orig';\n    if (doc !== 'orig') continue;            // 分屏时中文列不参与公式归属（同一套几何只对原文成立）\n    const pageNo = +pageDiv.dataset.page || 0;\n    const box = pageDiv.getBoundingClientRect();\n    const cr = document.createRange();\n    for (let i = start; i < end; i++) {\n      let rect = null;\n      try {\n        cr.setStart(node, i); cr.setEnd(node, i + 1);\n        const r = cr.getBoundingClientRect();\n        if (r && r.width > 0 && r.height > 0) {\n          rect = [r.left - box.left, r.top - box.top, r.right - box.left, r.bottom - box.top];\n        }\n      } catch { rect = null; }              // 换行伪影/失效 Range：退化成纯文本字符\n      out.push({ ch: data[i], page: pageNo, rect });\n    }\n  }\n  return out;\n}\n\n/** #tr-note 的诚实降级文案（§3.8 文案表，优先级自上而下）。\n *  ⚠️ 与需求表的一处**有意偏离**（已在实现报告里回报队长）：该表把 `unavailable` 排在\n *  `formulaSkipped>0` 之前，但过短选区（如只选一个 `F`）会同时命中两者，按表顺序会显示\n *  「没能定位到原文公式」——而验收项 A13 要求显示「选区太短，公式未还原」。这里让\n *  「什么都没还原 + 有过短 chunk」先报「选区太短」：它更准确，也不会误导用户以为译文是准的。 */\nfunction trNote(resp) {\n  const reason = eqIndex && eqIndex.reason;\n  if (eqIndex && eqIndex.source === 'none' && reason === 'no-mineru-artifact') {\n    return '⚠ 该论文未用 MinerU 转录：原文里的公式在文本层不可读，译文可能不准（顶栏 ∑ 公式 → 「用 MinerU 重新转录」）';\n  }\n  if (reason === 'no-equations') return '⚠ MinerU 产物里没有公式块：公式可能不准';\n  if (reason === 'bad-artifact') return '⚠ MinerU 产物损坏或不可读，已忽略：公式可能不准';\n  if (resp.formulaLost > 0) return `⚠ 有 ${resp.formulaLost} 个公式未原样保留，请对照原文`;\n  if (resp.formulaSkipped > 0 && resp.formulaApplied === 0) return '⚠ 选区太短，公式未还原';\n  if (resp.formulaStatus === 'unavailable' && resp.hasBlockIndex) return '⚠ 没能定位到原文公式，译文可能不准';\n  if (resp.formulaStatus === 'partial') return '⚠ 部分公式未能还原，译文可能不准';\n  if (resp.formulaSkipped > 0) return '⚠ 选区太短，公式未还原';\n  return '';   // applied / formulaTotal===0：不显示任何提示\n}\n\n/** 失败反馈（§3.7② 表，逐条）。返回 {status, toast}：气泡状态行与 toast 的措辞不同处照表分开。 */\nfunction trFailure(e) {\n  if (e && e.clientTimeout) return { status: '翻译超时，请重试', toast: '翻译超时，请重试' };\n  if (e && e.code === 'timeout') return { status: '翻译超时，请重试', toast: '翻译超时，请重试' };\n  if (e && e.code === 'network') return { status: '翻译失败：无法连接端点', toast: '翻译失败：无法连接端点' };\n  const up = e && e.upstreamStatus;\n  if (up === 401 || up === 403) return { status: '翻译失败：端点拒绝（请检查 API key）', toast: `翻译失败：端点拒绝（HTTP ${up}）` };\n  if (up === 429) return { status: '翻译失败：请求过于频繁，稍后再试', toast: '翻译失败：请求过于频繁，稍后再试' };\n  if (typeof up === 'number' && up >= 500) return { status: '翻译失败：端点错误（HTTP 5xx）', toast: '翻译失败：端点错误（HTTP 5xx）' };\n  const m = '翻译失败：' + ((e && e.message) || '未知原因');\n  return { status: m, toast: m };\n}\n\n/** 划词翻译入口（#ask-translate.onclick）。 */\nasync function translateSelection() {\n  // 中文列（分屏，doc==='zh'）不参与：几何只对原文页成立（R-07；按钮本身也不会显示）\n  if (!current || !askSelection || askSelection.kind !== 'text' || zhVariant !== null) return;\n  if ((askSelection.doc ?? 'orig') !== 'orig') return;\n  if (trBusy) return;\n  const range = askSelection.range;\n  if (!range || !range.startContainer || range.startContainer.isConnected === false) {\n    toast('页面已重绘，请重新选择', 4000);   // R5：绝不缓存矩形，也不静默失败\n    return;\n  }\n  // 用户点按钮时浏览器可能已把选区清掉：先把存下来的 Range 放回去，rects 才取得到\n  const sel = window.getSelection();\n  if (sel && sel.isCollapsed && typeof sel.addRange === 'function') {\n    try { sel.removeAllRanges(); sel.addRange(range); } catch { /* 失效选区：下面按空选区处理 */ }\n  }\n  let text = '';\n  try { text = String(range.toString() || ''); } catch { text = ''; }\n  if (!text.trim()) { toast('选区已失效，请重新选择', 4000); return; }\n  const chars = collectSelectionChars(range);\n  const chunks = buildChunks(chars, eqItemsFor);\n  if (!chunks.length) { toast('选区已失效，请重新选择', 4000); return; }\n  if (chars.length > MAX_SELECTION_CHARS) toast(`选区过长，只翻译前 ${MAX_SELECTION_CHARS} 字符`, 4000);\n\n  askPop.style.display = 'none';       // 同一锚点必然重叠 ⇒ 气泡「变成」译文气泡（§3.1）\n  showTrPop('翻译中…', '', '');\n  trBusy = true;\n  const seq = ++trSeq;\n  const ac = new AbortController();\n  let clientTimeout = false;\n  const timer = setTimeout(() => { clientTimeout = true; ac.abort(); }, TR_CLIENT_TIMEOUT_MS);\n  // 诊断可读性：记录本次送出的 chunk 规模（不含文本内容、不含 key）\n  const charsSent = chunks.reduce((n, c) => n + (c.kind === 'text' ? c.text.length : c.latex.length), 0);\n  try {\n    const resp = await api('/translate-selection', {\n      method: 'POST', headers: { 'content-type': 'application/json' },\n      body: JSON.stringify({ ...current, chunks }),\n      signal: ac.signal,\n    });\n    if (seq !== trSeq) return;          // 过期保护：用户已换选区/换文献\n    showTrPop('', resp.translation, trNote(resp));\n  } catch (e) {\n    if (seq !== trSeq) return;\n    if (clientTimeout) e.clientTimeout = true;\n    if (e && e.code === 'no-endpoint') {\n      // 未配置端点：打开既有设置浮层，保存成功后自动重试这次翻译（§3.7①）\n      showTrPop('未配置翻译端点', '', '在上面的设置里填好端点并保存，会自动重试这次翻译');\n      cfgRetryTranslate = true;\n      openCfgPop(false);\n      return;\n    }\n    const f = trFailure(e);\n    showTrPop(f.status, '', '');\n    toast(f.toast + `（选区 ${charsSent} 字符）`, 8000);\n  } finally {\n    clearTimeout(timer);\n    if (seq === trSeq) trBusy = false;\n  }\n}\n\n$('ask-translate').onclick = () => translateSelection();\ndocument.addEventListener('mousedown', (e) => { if (!trPop.contains(e.target)) hideTrPop(); });\ndocument.addEventListener('keydown', (e) => { if (e.key === 'Escape') hideTrPop(); });\n\n/* =====================================================================================\n   分屏对照（模式 B）：原文 PDF ↔ -zh.pdf 并排同步滚动 —— §4.2/§4.4\n   · 两列各自一个 pdf.js 文档；全局 pdfDoc **保持指向原文**（既有逻辑零改动）\n   · zhVariant 保持 null ⇒ eqHotEnabled()/公式面板/适宽分支继续按「原文」工作（C17）\n   · 热区只在原文列铺（paintEqLayer 按 pageDiv.dataset.doc 早退）、只在原文列命中（C18/R7）\n   ===================================================================================== */\nconst SPLIT_MIN_WIDTH = 640;   // 冻结：面板太窄不做分屏（§4.2）\nlet pdfDocZh = null;\nlet splitLoadSeq = 0;   // 分屏中文文档的加载序号：旧请求晚到时释放，不覆盖新文档\nlet splitSyncing = false;\nlet splitRaf = 0;\nlet splitWarned = false;\n\nconst rafFn = (fn) => (typeof window.requestAnimationFrame === 'function' ? window.requestAnimationFrame(fn) : setTimeout(fn, 0));\nconst crafFn = (id) => { if (typeof window.cancelAnimationFrame === 'function') window.cancelAnimationFrame(id); else clearTimeout(id); };\n\n/** 纯函数：滚动位置 → 「顶部页号 + 页内比例」（§4.2 锚点）。\n *  pages: [{page, offsetTop, offsetHeight}]，按 DOM 序。 */\nfunction anchorOf(pages, scrollTop) {\n  if (!pages || !pages.length) return null;\n  let page = pages[pages.length - 1];\n  for (const p of pages) { if (p.offsetTop + p.offsetHeight > scrollTop) { page = p; break; } }\n  return { page: page.page, ratio: (scrollTop - page.offsetTop) / Math.max(1, page.offsetHeight) };\n}\n\n/** 纯函数：锚点 → 目标列 scrollTop。页数相同（实测常态 19/19）走同页号；不同则按比例映射，\n *  并让调用方给出「页数不一致」的一次性提示。 */\nfunction syncTargetOf(anchor, targetPages, srcPageCount) {\n  if (!anchor || !targetPages || !targetPages.length) return null;\n  const n = targetPages.length;\n  let mismatch = false;\n  let idx = targetPages.findIndex((p) => p.page === anchor.page);\n  if (idx < 0) {\n    mismatch = true;\n    idx = Math.min(n - 1, Math.max(0, Math.round((anchor.page - 1) * n / Math.max(1, srcPageCount | 0))));\n  } else if (srcPageCount && srcPageCount !== n) {\n    mismatch = true;\n  }\n  const p = targetPages[idx];\n  return { top: p.offsetTop + anchor.ratio * p.offsetHeight, mismatch };\n}\n\n/** 一列的页几何（DOM 序）。 */\nfunction columnPages(box) {\n  return [...box.children].filter((c) => c.className === 'page')\n    .map((d) => ({ page: +d.dataset.page || 1, offsetTop: d.offsetTop, offsetHeight: d.offsetHeight }));\n}\n\nconst splitCols = () => [\n  { pane: $('pdf-pane'), box: $('pdf-pages') },\n  { pane: $('pdf-pane-zh'), box: $('pdf-pages-zh') },\n];\n\n/* =====================================================================================\n   同步滚动开关（模式 B 的可选项）—— 两处入口（分屏控件旁 + dsh 设置面板）、全局记忆、默认开\n   · 持久化键 `dpr.syncScroll`（'1'/'0'）：**故意不带 topic/name**，也**不在**\n     `dpr.variant.` / `dpr.sessionN.` 两个前缀里 —— lib/client.js 的改名搬家（migrateLsKeys）\n     只搬那两个前缀，所以论文/专题改名既不会搬它、更不会丢它（全局键本来就没有跟着某篇走的身份）。\n     取值缺省 = 开：与改造前「两列被 rAF 强行同步」的既有行为一致，老用户观感不变。\n   · 设置面板在**另一个文档**里（阅读器是同源 iframe）：两处靠 localStorage 的 storage 事件互通\n     （它只对**其他**文档触发，天然不会回声）——任一处改动，另一处立即反映。\n   · 关掉只关「持续联动」：进分屏/重渲时的一次性对齐（alignSplit）仍然执行，否则两列会停在不同页。\n   ===================================================================================== */\nconst SYNC_SCROLL_KEY = 'dpr.syncScroll';\nlet syncScroll = readSyncPref();\n/** 最后一次被用户滚过的那一列（关同步时也记）：重开同步时以它为基准对齐 —— 用户停在哪儿就对齐到哪儿。 */\nlet splitLeadPane = null;\n\n/** 读偏好：只有显式的 '0' 算关，其余（含缺失/脏值）都算开。 */\nfunction readSyncPref() {\n  try { return localStorage.getItem(SYNC_SCROLL_KEY) !== '0'; } catch { return true; }   // 隐私模式读不了 → 默认开\n}\nfunction persistSyncPref() {\n  try { localStorage.setItem(SYNC_SCROLL_KEY, syncScroll ? '1' : '0'); } catch { /* 隐私模式写不了：本次会话内仍然生效 */ }\n}\n\n/** 开关控件（分屏控件旁）：**只在分屏（模式 B）下可见** —— 模式 A（-dual.pdf 一个 PDF 里并排嵌好）\n *  与原文/译文视图都只有一个滚动条，本开关没有意义；隐藏而不是留个死控件。 */\nfunction updateSyncToggle() {\n  const b = $('sync-toggle');\n  if (!b) return;\n  b.style.display = viewMode === 'split' ? '' : 'none';\n  // 状态换图标（与 mode-toggle 的 paged/scroll、zh-toggle 的 translate/spin 同法）：\n  // data-icon 跟着渲染出来的图标走，图标本身由 iconHtml 统一给出（class=\"ic\"、size、aria-hidden）\n  const icon = syncScroll ? 'sync' : 'syncOff';\n  b.dataset.icon = icon;\n  b.innerHTML = iconHtml(icon);\n  b.classList.toggle('active', syncScroll);\n  b.title = syncScroll\n    ? '同步滚动 / Sync scroll：开（两列一起滚，点击关闭）'\n    : '同步滚动 / Sync scroll：关（两列各自独立滚动，点击打开并对齐回当前页）';\n}\n\n/** 唯一写入口（按钮点击 / 设置面板的 storage 事件都走这里）：落持久化 → 刷新控件 → 打开时立刻对齐。 */\nfunction setSyncScroll(on, { persist = true, realign = true } = {}) {\n  syncScroll = !!on;\n  if (persist) persistSyncPref();\n  updateSyncToggle();\n  if (syncScroll && realign) alignSplit(currentLeadCol());\n}\n\n/** 重开同步时的基准列：用户最后滚过的那一列；没滚过（或那列已不在）就用原文列。 */\nfunction currentLeadCol() {\n  const cols = splitCols();\n  return cols.find((c) => c.pane === splitLeadPane) || cols[0];\n}\n\n/** 一次性对齐：把**跟随列**滚到基准列当前锚点对应的位置。\n *  与 onSplitScroll 的区别是**不看 syncScroll** —— 进分屏 / 重渲 / 重开同步都必须先把两列摆到同一页，\n *