ge);\n}\n\n/** 中文列这次重渲前是否有一个「和即将渲染的形态可比」的位置：重渲前的页数必须等于这次要渲染的页数\n *  （还没渲过 / 页数变了 / 翻页↔滚动切换都不可比 —— 那些情况沿用统一对齐，见 renderSplit 尾注）。 */\nfunction zhOwnAnchorUsable(box, doc, paged) {\n  const before = columnPages(box).length;\n  if (before === 0) return false;\n  return before === (doc ? (paged ? 1 : doc.numPages) : 0);\n}\n\n/** 分屏全量渲染入口：两列同时渲（滚动=各列全量、翻页=两列同渲 curPage）。 */\nasync function renderSplit() {\n  teardownLazy()\n  if (viewMode !== 'split') return rerender();\n  const origDoc = pdfDoc;\n  const zhDoc = pdfDocZh;\n  if (!origDoc) return;\n  const pane = $('pdf-pane');\n  if (pane.clientHeight === 0) { pendingRerender = true; return; } // 与既有渲染入口同一条守卫\n  const token = ++renderToken;\n  const scale = zoomScale;\n  const origBox = $('pdf-pages'), zhBox = $('pdf-pages-zh');\n  const range = pane.scrollHeight - pane.clientHeight;\n  const anchorRatio = range > 0 ? pane.scrollTop / range : 0;\n  // F1：清空前**各自**记下两列的锚点（此刻旧页节点还在）。同步关着时两列各回各的 ——\n  // 关掉同步的全部意义就是「两列读不同位置」，zoom / dppx / resize 一下不该把这个意图抹掉。\n  const zhPane = $('pdf-pane-zh');\n  const origAnchor = captureScrollAnchor(pane, origBox);\n  const zhAnchor = captureScrollAnchor(zhPane, zhBox);\n  const paged = pageMode === 'paged';\n  const zhOwn = zhOwnAnchorUsable(zhBox, zhDoc, paged);\n  origBox.innerHTML = '';\n  zhBox.innerHTML = '';\n  clearEqGeometry();   // 旧页几何 + 跨列残留的 hover/hit 描边一起作废\n  $('zoom-label').textContent = Math.round(scale / 1.5 * 100) + '%';\n  origBox.classList.toggle('paged', paged);\n  zhBox.classList.toggle('paged', paged);\n  curPage = Math.min(Math.max(1, curPage), origDoc.numPages);\n  updatePager();\n  const origList = paged ? [curPage] : Array.from({ length: origDoc.numPages }, (_, i) => i + 1);\n  await renderColumn(origDoc, 'orig', origBox, origList, token, scale);\n  if (token !== renderToken) return;\n  if (zhDoc) {\n    const zhPage = Math.min(Math.max(1, curPage), zhDoc.numPages);\n    const zhList = paged ? [zhPage] : Array.from({ length: zhDoc.numPages }, (_, i) => i + 1);\n    await renderColumn(zhDoc, 'zh', zhBox, zhList, token, scale);\n    if (token !== renderToken) return;\n  }\n  // 锚点恢复：重渲后两列各自回到重渲前的位置。\n  //  · 同步开着 / 刚进分屏（中文列还没有可比的位置）：**既有语义一字不动** —— 原文列按滚动比例回位，\n  //    中文列统一对齐到原文列（「进分屏的一次性对齐不看开关」是评审已裁定必要的行为，保持）；\n  //  · 同步关着且中文列有**同形态**的重渲前位置（F1 修法）：两列各回各的锚点 —— 不能让一次\n  //    zoom / dppx / resize 把「两列读不同位置」的意图抹掉。\n  if (!paged) {\n    if (syncScroll || !zhOwn) {\n      const newRange = pane.scrollHeight - pane.clientHeight;\n      pane.scrollTop = anchorRatio * Math.max(0, newRange);\n      splitSyncing = false;\n      alignSplit(splitCols()[0]);\n    } else {\n      restoreScrollAnchor(pane, origBox, origAnchor);\n      restoreScrollAnchor(zhPane, zhBox, zhAnchor);\n      splitSyncing = false;\n      crafFn(splitRaf);     // 作废可能在飞的对齐/联动回调：别让它下一帧再把中文列拉回原文列\n      splitRaf = 0;\n    }\n  }\n  observePages();      // 只观察原文列（#pdf-pages .page 的 id 限定必须保持）\n}\n\n/** 进入分屏（或 openPaper 恢复分屏）：拉原文 + -zh.pdf 两个文档，两列同渲。 */\nasync function openSplit() {\n  if (!current || !zhState.zh) return;\n  if (window.innerWidth < SPLIT_MIN_WIDTH) {\n    toast('面板太窄，请把阅读器拉宽后再用分屏对照', 4000);\n    if (viewMode === 'split') await setViewMode('orig');\n    return;\n  }\n  // pdf.js 必须先就绪（与 loadPdf 同一条通道）：openPaper 恢复「分屏」时页脚的经典脚本还在解析期，\n  // 动态 import 尚未完成 —— 直接触 pdfjsLib 会 ReferenceError，表现为\n  // 「打开中文版失败：pdfjsLib is not defined，已退回原文」+ 持久化写空（t3 报告 F3，6 次跑 5 次失败）。\n  await ensurePdfjs();\n  await resetViewCache(); // 分屏走独立的两列渲染；单文档缓存全部释放，避免同一文档两份\n  activeKey = 'orig';\n  $('split-wrap').classList.add('on');\n  $('pdf-pane-zh').style.display = '';\n  splitWarned = false;\n  $('empty').style.display = 'none';\n  $('pager').style.display = '';\n  $('mode-toggle').style.display = '';\n  const seq = ++splitLoadSeq;\n  if (pdfDocZh) { await destroyPdfDoc(pdfDocZh); pdfDocZh = null; }\n  let task = null;\n  try {\n    task = pdfjsLib.getDocument({ url: pdfUrl('zh') });\n    const doc = await task.promise;\n    if (seq !== splitLoadSeq) { try { await task.d