      "path": "src/scope.ts",
      "content": "// scope.ts — 「按范围提问」的三段式上下文装配（纯函数，不依赖 Cordis）。\n//\n// 冻结方案：docs/darkmode-subtopic-plan.md §B3。用户原话是「提问时只给出该范围的目录内容」，\n// 所以三段的定义是（全部由**服务端**按范围装配，客户端只传 scope，不传正文）：\n//   ① **目录清单**（必给，≤ MAX_MANIFEST）：范围内每篇论文一行（路径 / 页数 / 产物 / 学习档案状态）。\n//      —— 「只给该范围」就体现在这里：范围外一篇都不出现。\n//   ② **正文**（按需）：kind='paper' 时给该篇正文（≤ MAX_PER_DOC，超限显式截断）；\n//      kind='topic' 时**不做「全塞」**（实测真实库两篇论文正文合计 550 KiB，是上限的 14 倍），\n//      改用问题在**范围内**做一次检索，每篇取 top-k 作为代表。\n//   ③ **检索命中**：带 `<论文相对路径> 第 N 页` 的片段（页码走 pages.json 的 offset 映射）。\n//\n// 截断**必须显式**：每篇标注 full / truncated / omitted-no-room，并在末尾追加一行「已给 X 篇，\n// 另有 Y 篇因上下文上限未展开」。\n\nimport { readFileSync, statSync } from 'node:fs'\nimport { join } from 'node:path'\nimport { listPapers, paperRefFor, resolvePaper, type PaperRef } from './library.ts'\nimport { ManageError, resolveTopicDir, validateTopicPath } from './library-manage.ts'\nimport { chunkText, cutToCodePoint, searchChunks, type Chunk } from './search.ts'\nimport type { PageSpan } from './transcribe.ts'\n\n/** 方案 §B3.2 冻结的五个上限（导出以便断言）。 */\nexport const MAX_CONTEXT_CHARS = 40_000\nexport const MAX_PER_DOC = 8_000\nexport const MAX_MANIFEST = 2_000\nexport const MAX_PAPERS_IN_SCOPE = 12\nexport const MAX_HITS_PER_PAPER = 3\n/** 正文/命中装配时给「段标题 + 末尾说明行」预留的余量：保证 `block.length` 也不越 MAX_CONTEXT_CHARS。 */\nconst BLOCK_RESERVE = 400\n/** 论文正文的来源优先级（MinerU 的版面重排质量最好） */\nexport const BODY_SOURCES = ['.mineru.md', '.txt'] as const\n\n/* cutToCodePoint 已对账：统一用 search.ts 的导出（issue #9——码元截断切开代理对\n * 会让孤立代理项进会话历史，之后每轮请求 400），不再保留本文件的等价实现。\n * re-export 维持 scope 模块原有导出面（测试 GC1/VER-G4 依赖）。 */\nexport { cutToCodePoint } from './search.ts'\n\nexport type AskScope =\n  | { kind: 'paper'; topic?: string; name?: string }\n  | { kind: 'topic'; topic: string }\n\nexport type ScopeKind = AskScope['kind']\n\n/** 一篇论文在本次上下文里的展开状态（截断必须显式，不许静默）。 */\nexport type Coverage = 'full' | 'truncated' | 'omitted-no-room' | 'no-body' | 'omitted-duplicate'\n\nexport interface ScopePaper {\n  topic: string\n  name: string\n  /** `专题路径/篇名` —— 提示里出现的唯一标识 */\n  path: string\n  pages: number | null\n  artifacts: string[]\n  study: string\n  coverage: Coverage\n  /** 正文来源：mineru.md / txt / null */\n  source: string | null\n  chars: number\n}\n\nexport interface ScopeContext {\n  scope: AskScope\n  scopePath: string\n  /** 范围说明块（插在既有 `文献：…` 之后、`用户的问题：` 之前） */\n  block: string\n  papers: ScopePaper[]\n  manifestChars: number\n  bodyChars: number\n  hitChars: number\n  totalChars: number\n  omitted: number\n  /** 逐篇的「为什么没展开」：与 omitted 对应，绝不静默丢（如同名论文在多处）。 */\n  omittedNotes: string[]\n  /** 台账：`papers[]` 里 coverage='full' 的篇数（与逐篇明细**同源**，见代码里的 setCov）。 */\n  full: number\n  /** 台账：`papers[]` 里 coverage='truncated' 的篇数。**只算论文正文/片段**，\n   *  清单被 MAX_MANIFEST 截断不算在这里（那是 `manifestTruncated`）——否则「统计与明细打架」。 */\n  truncated: number\n  /** 目录清单本身是否被 MAX_MANIFEST 截断（提示块里仍有显式文案）。 */\n  manifestTruncated: boolean\n}\n\nfunction readText(file: string, limit: number): string | null {\n  try {\n    const st = statSync(file)\n    if (!st.isFile() || st.size === 0) return null\n    return cutToCodePoint(readFileSync(file, 'utf8'), limit)\n  } catch {\n    return null\n  }\n}\n\nfunction readPages(pagesPath: string): PageSpan[] | null {\n  try {\n    const raw = JSON.parse(readFileSync(pagesPath, 'utf8')) as { pages?: PageSpan[] }\n    return Array.isArray(raw.pages) ? raw.pages : null\n  } catch {\n    return null\n  }\n}\n\nfunction pageCountOf(pagesPath: string): number | null {\n  try {\n    const raw = JSON.parse(readFileSync(pagesPath, 'utf8')) as { pageCount?: number }\n    return typeof raw.pageCount === 'number' ? raw.pageCount : null\n  } catch {\n    return null\n  }\n}\n\n/** 该篇的正文来源：按优先级取第一个存在且非空的（并给名字，便于提示里说明来源）。 */\nexport function bodyFor(ref: PaperRef): { source: string; text: string } | null {\n  const base = ref.pdfPath.slice(0, -4)\n  for (const suffix of BODY_SOURCES) {\n    const text = readText(base + suffix, Number.MAX_SAFE_INTEGER)\n    if (text && text.length > 0) return { source: suffix, text }\n  }\n  return null\n}\n\n/** 逐篇的产物/学习档案摘要（只给元信息与路径，**不给正文**）。 */\nfunction describePaper(ref: PaperRef): { artifacts: string[]; study: string } {\n  const base = ref.pdfPath.slice(0, -4)\n  const artifacts: string[] = []\n  for (const s of ['.pdf', '.txt', '.pages.json', '.transcript.json', '.mineru.md', '.mineru.json', '.embeddings.json']) {\n    try {\n      const st = statSync(base + s)\n      if (st.isFile()) artifacts.push(`${s}(${st.size}B)`)\n    } catch { /* 不存在 */ }\n  }\n  const study = readStudyBrief(base + '.study.json')\n  return { artifacts, study }\n}\n\nfunction readStudyBrief(file: string): string {\n  try {\n    const raw = JSON.parse(readFileSync(file, 'utf8')) as { plan?: Array<{ status?: string }>; quizzes?: unknown[] }\n    if (!Array.isArray(raw.plan)) return '无'\n    const done = raw.plan.filter((s) => s.status === 'done').length\n    const quiz = Array.isArray(raw.quizzes) ? raw.quizzes.length : 0\n    return `计划 ${done}/${raw.plan.length} 步完成，检验 ${quiz} 次`\n  } catch {\n    return '无'\n  }\n}\n\n/** 无法唯一定位、因而没有进正文的论文（**必须**在结果里如实标注，不许静默丢）。 */\nexport interface ScopeSkip {\n  topic: string\n  name: string\n  path: string\n  reason: string\n}\n\nexport interface ScopeResolution {\n  refs: PaperRef[]\n  skipped: ScopeSkip[]\n  /** kind='topic' 时规范化后的专题路径（已校验存在）；kind='paper' 为 null。 */\n  topic: string | null\n}\n\n/**\n * 把范围内的论文解析成 PaperRef 列表（kind='paper' 只有一篇；不带 topic/name 时 = 当前这篇）。\n *\n * PR #8 评审 G（如实提示）在这里落三件事：\n *  ① `kind='topic'` 先**校验专题存在**（404 ManageError：`host.ts` 的 isManageError 分支会给出\n *     明确 404），不再装配出「空的但看起来正常」的范围 + 200 假成功；\n *  ② `listPapers` 已递归整棵子树、给出**精确的** (topic, name)，据此用 `paperRefFor` 直接构造引用\n *     ——不再逐篇 `resolvePaper`（那会按**名字**重扫子树：既有 N+1 开销，同名论文还会被解析成\n *     「命中多篇」而**静默消失**）；\n *  ③ 同名论文出现在不同深度时无法按名字唯一确定 ⇒ 进 `skipped`（带路径与原因），由调用方\n *     计入 omitted 并在提示里点名，绝不静默丢。\n */\nexport function resolveScopePapers(dataDir: string, scope: AskScope, current: PaperRef): ScopeResolution {\n  if (scope.kind === 'paper') {\n    const args: { topic?: string; name?: string } = {}\n    if (scope.topic !== undefined) args.topic = scope.topic\n    if (scope.name !== undefined) args.name = scope.name\n    // `{kind:'paper'}` 不带 topic/name = 「本篇」（默认范围的语义）；带则按给定的那篇\n    if (args.topic === undefined && args.name === undefined) return { refs: [current], skipped: [], topic: null }\n    return { refs: [resolvePaper(dataDir, args)], skipped: [], topic: null }\n  }\n  // 专题/子专题：**整棵子树**内的全部论文（listPapers 已递归；论文目录不递归）。\n  // 先过存在性/边界校验：已改名/删除的专题必须 404，不能假装「范围是空的」。\n  const topicPath = validateTopicPath(scope.topic, false)\n  resolveTopicDir(dataDir, topicPath) // 不存在的专题 ⇒ ManageError('not-found', 404)\n  const list = listPapers(dataDir, topicPath)\n  const pathsByName = new Map<string, string[]>()\n  for (const p of list) {\n    const paths = pathsByName.get(p.name) ?? []\n    paths.push(`${p.topic}/${p.name}`)\n    pathsByName.set(p.name, paths)\n  }\n  const refs: PaperRef[] = []\n  const skipped: ScopeSkip[] = []\n  for (const p of list) {\n    const path = `${p.topic}/${p.name}`\n    const sameName = pathsByName.get(p.name) ?? [path]\n    if (sameName.length > 1) {\n      skipped.push({\n        topic: p.topic,\n        name: p.name,\n        path,\n        reason: `同名论文在多处（${sameName.join('、')}），无法唯一定位，已跳过（可改用单篇范围指定）`,\n      })\n      continue\n    }\n    refs.push(paperRefFor(dataDir, p.topic, p.name))\n  }\n  return { refs, skipped, topic: topicPath }\n}\n\n/** 兼容旧入口：只取可唯一定位的论文（省略项见 `resolveScopePapers().skipped`）。 */\nexport function scopePapers(dataDir: string, scope: AskScope, current: PaperRef): PaperRef[] {\n  return resolveScopePapers(dataDir, scope, current).refs\n}\n\n/**\n * 装配三段式上下文。纯读，无副作用。\n * `question` 用于 kind='topic' 时的范围内检索（每篇 top-k）。\n */\nexport function buildScopeContext(dataDir: string, current: PaperRef, scope: AskScope, question: string): ScopeContext {\n  const resolved = resolveScopePapers(dataDir, scope, current)\n  const refs = resolved.refs\n  const scopePath = scope.kind === 'paper'\n    ? `${refs[0]?.topic ?? current.topic}/${refs[0]?.name ?? current.name}`\n    : (resolved.topic ?? scope.topic)\n  const papers: ScopePaper[] = []\n  const omittedNotes: string[] = []\n  let omitted = 0\n  let noRoom = 0\n  let full = 0\n  let truncated = 0\n  let manifestTruncated = false\n\n  // ── ① 目录清单（必给，≤ MAX_MANIFEST）──\n  const manifestLines: string[] = [`本次提问范围：${scopePath}（${scope.kind === 'paper' ? '单篇论文' : '该专题及其全部子专题'}）`]\n  for (const [i, ref] of refs.entries()) {\n    const { artifacts, study } = describePaper(ref)\n    const pages = pageCountOf(ref.pagesPath)\n    const label = `${ref.topic}/${ref.name}`\n    if (i >= MAX_PAPERS_IN_SCOPE) {\n      omitted++\n      noRoom++\n      papers.push({ topic: ref.topic, name: ref.name, path: label, pages, artifacts, study, coverage: 'omitted-no-room', source: null, chars: 0 })\n      continue\n    }\n    // 范围内的**每一篇**都进 papers[]（含清单里也是全量）：coverage 先给占位，\n    // 正文阶段再按「给了正文 / 被截断 / 没正文 / 没位置」更新 —— 否则统计与断言只覆盖被省略的那几篇。\n    papers.push({ topic: ref.topic, name: ref.name, path: label, pages, artifacts, study, coverage: 'no-body', source: null, chars: 0 })\n    manifestLines.push(`- ${label}｜${pages != null ? `${pages} 页` : '页数未知'}｜${artifacts.join(' ')}｜学习档案：${study}`)\n  }\n  // 同名论文在多处：按名字无法唯一定位 ⇒ **显式**进清单与 omitted（带原因），绝不静默丢\n  for (const s of resolved.skipped) {\n    omitted++\n    omittedNotes.push(`${s.path}：${s.reason}`)\n    papers.push({ topic: s.topic, name: s.name, path: s.path, pages: null, artifacts: [], study: '未展开', coverage: 'omitted-duplicate', source: null, chars: 0 })\n    manifestLines.push(`- ${s.path}｜未展开：${s.reason}`)\n  }\n  // 清单超上限时按行截断（仍显式说明）。**不计入 truncated**：`truncated` 只统计\n  // `papers[].coverage==='truncated'`（评审 G 次级：台账必须与逐篇明细逐条对得上）。\n  let manifest = manifestLines.join('\\n')\n  if (manifest.length > MAX_MANIFEST) {\n    manifest = cutToCodePoint(manifest, MAX_MANIFEST) + '\\n…（清单已截断至上限）'\n    manifestTruncated = true\n  }\n\n  // ── ② 正文 + ③ 检索命中 ──\n  // 预算口径（PR #8 评审 G）：**实际追加多少就计多少**。`used` 从清单长度起算，正文/命中片段\n  // 逐条累加；`BLOCK_RESERVE` 给段标题与末尾说明行留余量 ⇒ `totalChars` 与 `block.length` 都\n  // 不会越过 MAX_CONTEXT_CHARS。命中片段只在第 ③ 段出现一次（不再与正文重复同一段文本）。\n  const bodyParts: string[] = []\n  const hitParts: string[] = []\n  let used = manifest.length\n  const budget = (): number => Math.max(0, MAX_CONTEXT_CHARS - used - BLOCK_RESERVE)\n  const recOf = (label: string): ScopePaper | undefined => papers.find((p) => p.path === label)\n  /**\n   * 逐篇 coverage 与**台账**的唯一写入口（评审 G 次级：`papers[].coverage` 与\n   * `truncated`/`full`/`omitted` 必须同源，否则统计与明细会打架）。\n   * `chars` 定义：该篇**内容**（正文/命中片段文本，不含段标题与说明句）实际进入 block 的字数。\n   */\n  const setCov = (rec: ScopePaper | undefined, cov: Coverage, source: string | null, chars: number): void => {\n    if (!rec) return\n    rec.coverage = cov\n    rec.source = source\n    rec.chars = chars\n    if (cov === 'full') full++\n    else if (cov === 'truncated') truncated++\n  }\n\n  if (scope.kind === 'paper') {\n    const ref = refs[0]\n    if (ref) {\n      const body = bodyFor(ref)\n      const label = `${ref.topic}/${ref.name}`\n      const rec = recOf(label)\n      if (!body) {\n        setCov(rec, 'no-body', null, 0)\n      } else if (body.text.length <= MAX_PER_DOC && body.text.length < budget()) {\n        const head = `\\n=== ${label}（正文来源 ${body.source}） ===\\n`\n        bodyParts.push(head + body.text)\n        used += head.length + body.text.length\n        setCov(rec, 'full', body.source, body.text.length)\n      } else {\n        const limit = Math.max(0, Math.min(MAX_PER_DOC, budget() - 200))\n        const slice = cutToCodePoint(body.text, limit)\n        const head = `\\n=== ${label}（正文来源 ${body.source}；全文 ${body.text.length} 字，已截断至 ${slice.length} 字） ===\\n`\n        if (head.length + slice.length > budget()) {\n          // 连段标题都放不下：如实标 omitted（不硬塞超预算内容）\n          setCov(rec, 'omitted-no-room', null, 0)\n          omitted++\n          noRoom++\n        } else {\n          bodyParts.push(head + slice)\n          used += head.length + slice.length\n          setCov(rec, 'truncated', body.source, slice.length)\n        }\n      }\n    }\n  } else {\n    // 专题/子树：正文**不做全塞**，每篇用问题做一次范围内检索取 top-k（命中片段即第 ③ 段）。\n    for (const ref of refs) {\n      const label = `${ref.topic}/${ref.name}`\n      const rec = recOf(label)\n      if (!rec || rec.coverage === 'omitted-no-room') continue\n      if (budget() < 400) { setCov(rec, 'omitted-no-room', null, 0); omitted++; noRoom++; continue }\n      const body = bodyFor(ref)\n      if (!body) { setCov(rec, 'no-body', null, 0); continue }\n      const chunks: Chunk[] = chunkText(body.text)\n      const pages = readPages(ref.pagesPath)\n      const hits = searchChunks(chunks, pages, question, MAX_HITS_PER_PAPER)\n      if (hits.length === 0) {\n        // 检索无命中：给开头一段作代表（显式标注），否则模型对这篇一无所知。\n        // 评审 G 次级（基线 scope.ts:253）：这里曾**无条件**标 'truncated' + truncated++，\n        // 短正文其实整篇都给完了却报「已截断」——现在按「是否真的切掉了正文」判定。\n        const limit = Math.max(0, Math.min(MAX_PER_DOC, budget() - 300))\n        const slice = cutToCodePoint(body.text, limit)\n        const wholeBody = slice.length >= body.text.length\n        if ((!wholeBody && limit < 200) || slice.length === 0) {\n          setCov(rec, 'omitted-no-room', null, 0)\n          omitted++\n          noRoom++\n          continue\n        }\n        // 文案也必须诚实：整篇给完就别再说「开头片段」\n        const text = `（本问题在该文中无关键词命中，以下是${wholeBody ? '全文' : '开头片段'}）\\n${slice}`\n        const header = `\\n=== ${label}（正文来源 ${body.source}） ===\\n`\n        bodyParts.push(header + text)\n        used += header.length + text.length\n        setCov(rec, wholeBody ? 'full' : 'truncated', body.source, slice.length)\n        continue\n      }\n      // 命中片段（带页码）：每篇 top-k，逐条按「全局预算 + 每篇 MAX_PER_DOC」追加并计费。\n      // `chars` 只算片段正文（不含 `--- 路径 第 N 页 ---` 标题），与「块内实际字数」对齐。\n      let docUsed = 0\n      let docChars = 0\n      let allHits = true\n      for (const h of hits) {\n        const where = h.page != null ? ` 第 ${h.page} 页` : ''\n        const header = `\\n--- ${label}${where} ---\\n`\n        const room = Math.min(MAX_PER_DOC - docUsed, budget() - header.length - 40)\n        if (room < 200) { allHits = false; break }\n        const slice = cutToCodePoint(h.chunk.text, Math.min(1200, room))\n        if (slice.length < h.chunk.text.length) allHits = false\n        const frag = header + slice\n        hitParts.push(frag)\n        used += frag.length\n        docUsed += frag.length\n        docChars += slice.length\n      }\n      if (docUsed === 0) { setCov(rec, 'omitted-no-room', null, 0); omitted++; noRoom++; continue }\n      setCov(rec, allHits ? 'full' : 'truncated', body.source, docChars)\n    }\n  }\n\n  const body = bodyParts.join('\\n')\n  const hits = hitParts.join('\\n')\n  const totalChars = manifest.length + body.length + hits.length\n  // omitted 提示句**只出现一次**（曾在 tail 与 block 里各输出一遍）\n  const omittedLines: string[] = []\n  if (omitted > 0) {\n    const shown = papers.length - omitted\n    if (noRoom > 0) omittedLines.push(`（清单：本次已给 ${shown} 篇，另有 ${noRoom} 篇因上下文上限未展开，可缩小范围或指定论文）`)\n    const dup = resolved.skipped.length\n    if (dup > 0) omittedLines.push(`（另有 ${dup} 篇同名论文在多处出现、无法唯一定位，已跳过：${resolved.skipped.map((s) => s.path).join('、')}）`)\n  }\n  const tail: string[] = []\n  if (scope.kind === 'topic') {\n    tail.push(`本次提问的范围是 \\`${scopePath}\\`（含子专题）；如需范围外的论文请显式说明。范围外内容未提供。`)\n  }\n  tail.push(`（当前阅读的是 \\`${current.topic}/${current.name}\\`；本次提问范围是 \\`${scopePath}\\`。）`)\n\n  const block = [\n    `【提问范围】${scopePath}`,\n    '【范围内目录清单】',\n    manifest,\n    omittedLines.join('\\n'),\n    body ? '【范围内正文】' : '',\n    body,\n    hits ? '【范围内检索命中（带页码）】' : '',\n    hits,\n    tail.join('\\n'),\n  ].filter((x) => x !== '').join('\\n')\n\n  return {\n    scope,\n    scopePath,\n    block,\n    papers,\n    manifestChars: manifest.length,\n    bodyChars: body.length,\n    hitChars: hits.length,\n    totalChars,\n    omitted,\n    omittedNotes,\n    full,\n    truncated,\n    manifestTruncated,\n  }\n}\n"
    },
    {
      "path": "src/embed.ts",
      "content": "// embed.ts — OpenAI 兼容嵌入端点客户端 + 分块嵌入缓存 + 混合召回（纯函数，不依赖 Cordis）。\n//\n// 形状对齐 rerank.ts：**可选增强、默认关闭、失败降级**而不是抛给用户。与重排的分工：\n//   - 重排（rerank.ts）：对关键词 shortlist **定序**（候选已经捞回来了）；\n//   - 嵌入（本文件）：**全量召回**——关键词一个词都没命中的语义相近片段也能进候选。\n// 两者可同时启用，顺序固定：关键词候选 ∪ 嵌入候选 → RRF 融合 →（配了 Jev/TypeSafe 则）既有重排 → top-k。\n//\n// 缓存：`<论文>.embeddings.json`，键 = {model, dimensions, 内容哈希}；命中时**不请求分块嵌入**。\n// 隐私：分块文本会发往配置的端点（README 有明确提示）；缓存与错误信息里都不出现 apiKey。\n\nimport { createHash } from 'node:crypto'\nimport { mkdir, readFile, rename, rm, writeFile } from 'node:fs/promises'\nimport { dirname } from 'node:path'\nimport { pageForOffset, type Chunk, type SearchHit } from './search.ts'\nimport type { PageSpan } from './transcribe.ts'\nimport { sanitizeDetail } from './mineru.ts'\n\nexport interface EmbedConfig {\n  /** OpenAI 兼容端点根（如 https://api.openai.com/v1 或本地 http://127.0.0.1:1234/v1）；不配 = 嵌入关闭 */\n  baseUrl?: string\n  /** API key；省略时回退环境变量 DSH_EMBED_API_KEY，都没有则嵌入关闭 */\n  apiKey?: string\n  /** 嵌入模型名（必填才启用） */\n  model?: string\n  /** 单次请求超时毫秒，默认 30000 */\n  timeoutMs?: number\n  /** 每批提交的分块数，默认 10（见 EMBED_DEFAULTS 注释） */\n  batchSize?: number\n  /** 语义召回候选数（进融合的语义候选上限），默认 20 */\n  candidateSize?: number\n}\n\nexport const EMBED_DEFAULTS = {\n  /**\n   * 保守默认：主流 OpenAI 兼容端点的单批上限参差——阿里云百炼 text-embedding-v3/v4 是 10 条、\n   * qwen3.7-text-embedding 是 20 条（issue #14），OpenAI 官方则宽松得多。取已知最严格的 10：\n   * 对宽松端点只是多几个小请求，对严格端点则是「开箱即用 vs 首次检索必失败」的差别。\n   * 端点允许更大批量时可在设置面板 / profile 调高。\n   */\n  batchSize: 10,\n  timeoutMs: 30_000,\n  candidateSize: 20,\n} as const\n\n/** 嵌入链路错误的统一类型：调用方据此**整体降级**为纯关键词，不把它抛给用户。 */\nexport class EmbedError extends Error {\n  constructor(message: string) {\n    super(message)\n    this.name = 'EmbedError'\n  }\n}\n\nexport interface EmbedCacheFile {\n  v: 1\n  /**\n   * 产出这批向量的**端点**（F-E2）：缓存键的一部分，与查询向量备忘的键对齐。\n   * 换端点（哪怕 model 名与维度都一样）也判定失效重算——否则会静默复用上一端点的向量，\n   * 表现为「检索结果莫名其妙」，极难排查。\n   */\n  baseUrl: string\n  model: string\n  dimensions: number\n  contentHash: string\n  createdAt: string\n  vectors: number[][]\n}\n\n/** `<论文>.txt` → `<论文>.embeddings.json`（与 .txt/.pages.json 同目录同前缀）。 */\nexport function embeddingsPathFor(txtPath: string): string {\n  return txtPath.replace(/\\.txt$/i, '') + '.embeddings.json'\n}\n\n/**\n * 分块集合的内容哈希（缓存失效条件之一）：分块大小 + 分块数 + 每块长度 + 每块文本，顺序敏感。\n * `.txt` 变了 / 分块大小变了 / 重新转录了 → 哈希变 → 缓存判定失效并重算。\n */\nexport function chunkSetHash(chunks: Chunk[], chunkSize = 1500): string {\n  const h = createHash('sha256')\n  h.update(`chunkSize:${chunkSize};count:${chunks.length}\\n`)\n  for (const c of chunks) h.update(`${c.text.length}:${c.text}\\n`)\n  return h.digest('hex')\n}\n\nfunction isRecord(v: unknown): v is Record<string, unknown> {\n  return typeof v === 'object' && v !== null && !Array.isArray(v)\n}\n\nfunction isFiniteNumber(v: unknown): v is number {\n  return typeof v === 'number' && Number.isFinite(v)\n}\n\n/**\n * 校验嵌入响应：形状（条数一致）、维度一致、**必须都是有限数**（NaN/Infinity/字符串一律拒绝）。\n * 同时容忍两种常见形状：OpenAI 的 `{index, embedding}` 与部分本地实现直接给的数组。\n */\nexport function validateEmbeddings(raw: unknown, expected: number, where: string): number[][] {\n  if (!Array.isArray(raw)) throw new EmbedError(`${where}：data 不是数组`)\n  if (raw.length !== expected) throw new EmbedError(`${where}：返回 ${raw.length} 条嵌入，期望 ${expected} 条`)\n  const out: number[][] = []\n  let dim = -1\n  for (const row of raw) {\n    const vec: unknown = Array.isArray(row) ? row : isRecord(row) ? row['embedding'] : undefined\n    if (!Array.isArray(vec)) throw new EmbedError(`${where}：条目缺少 embedding 数组`)\n    if (vec.length === 0) throw new EmbedError(`${where}：嵌入维度为 0`)\n    for (const v of vec) {\n      if (!isFiniteNumber(v)) throw new EmbedError(`${where}：嵌入含非数值/NaN，已拒绝`)\n    }\n    if (dim === -1) dim = vec.length\n    else if (vec.length !== dim) throw new EmbedError(`${where}：同批嵌入维度不一致（${dim} vs ${vec.length}）`)\n    out.push(vec as number[])\n  }\n  return out\n}\n\nexport interface EmbedRequest {\n  baseUrl: string\n  apiKey: string\n  model: string\n  timeoutMs?: number\n  signal?: AbortSignal\n  /** 测试注入用；默认全局 fetch。 */\n  fetchImpl?: typeof fetch\n}\n\n/** 端点 URL：允许用户直接填到 `/embeddings`，否则拼在根后面。 */\nexport function embeddingsUrl(baseUrl: string): string {\n  const base = baseUrl.replace(/\\/+$/, '')\n  return /\\/embeddings$/i.test(base) ? base : `${base}/embeddings`\n}\n\nfunction networkMessage(err: unknown): string {\n  if (err instanceof Error) {\n    const cause = err.cause instanceof Error ? `：${err.cause.message}` : ''\n    return `${err.name === 'TimeoutError' ? '请求超时' : err.message}${cause}`\n  }\n  return String(err)\n}\n\n/**\n * 一次 `/embeddings` 调用（一批文本）。任何失败都抛 EmbedError（调用方整体降级）。\n * 错误文案里的端点响应体片段一律经 sanitizeDetail(…, apiKey) 脱敏。\n */\nexport async function requestEmbeddings(req: EmbedRequest, texts: string[]): Promise<number[][]> {\n  if (texts.length === 0) return []\n  const timeoutMs = req.timeoutMs ?? EMBED_DEFAULTS.timeoutMs\n  const fetchImpl = req.fetchImpl ?? fetch\n  const signals: AbortSignal[] = [AbortSignal.timeout(timeoutMs)]\n  if (req.signal) signals.push(req.signal)\n  let res: Response\n  try {\n    res = await fetchImpl(embeddingsUrl(req.baseUrl), {\n      method: 'POST',\n      headers: { 'content-type': 'application/json', authorization: `Bearer ${req.apiKey}` },\n      body: JSON.stringify({ model: req.model, input: texts, encoding_format: 'float' }),\n      signal: signals.length === 1 ? signals[0]! : AbortSignal.any(signals),\n    })\n  } catch (err) {\n    throw new EmbedError(`嵌入端点请求失败：${sanitizeDetail(networkMessage(err), req.apiKey)}`)\n  }\n  const body = await res.text().catch(() => '')\n  if (!res.ok) {\n    const detail = sanitizeDetail(body.slice(0, 200), req.apiKey)\n    throw new EmbedError(`嵌入端点返回 HTTP ${res.status}${detail ? `：${detail}` : ''}`)\n  }\n  let parsed: unknown\n  try {\n    parsed = JSON.parse(body)\n  } catch {\n    throw new EmbedError('嵌入端点返回的不是合法 JSON')\n  }\n  return validateEmbeddings(isRecord(parsed) ? parsed['data'] : undefined, texts.length, '嵌入端点响应')\n}\n\n// ── 缓存 ────────────────────────────────────────────────────────────────\n\n/** 读缓存：文件缺失/损坏/形状不对一律 null（与其余 *.json 读策略一致）。 */\nexport async function readEmbedCache(path: string): Promise<EmbedCacheFile | null> {\n  try {\n    const data = JSON.parse(await readFile(path, 'utf8')) as unknown\n    if (!isRecord(data)) return null\n    const vectors = data['vectors']\n    if (!Array.isArray(vectors)) return null\n    if (typeof data['model'] !== 'string' || typeof data['contentHash'] !== 'string') return null\n    if (!Number.isInteger(data['dimensions'])) return null\n    return {\n      v: 1,\n      // 旧缓存没有 baseUrl 字段 → 记为空串 → 与任何真实 baseUrl 都不相等 → 判定失效重算（一次性的预期失效）\n      baseUrl: typeof data['baseUrl'] === 'string' ? data['baseUrl'] : '',\n      model: data['model'],\n      dimensions: data['dimensions'] as number,\n      contentHash: data['contentHash'],\n      createdAt: typeof data['createdAt'] === 'string' ? data['createdAt'] : '',\n      vectors: vectors as number[][],\n    }\n  } catch {\n    return null\n  }\n}\n\n/** 原子写缓存（临时文件 + rename），避免半截 JSON 被当成有效缓存。 */\nexport async function writeEmbedCache(path: string, cache: EmbedCacheFile): Promise<void> {\n  await mkdir(dirname(path), { recursive: true })\n  const tmp = `${path}.tmp-${process.pid}-${Math.random().toString(36).slice(2, 10)}`\n  await writeFile(tmp, JSON.stringify(cache), 'utf8')\n  await rename(tmp, path)\n}\n\n/** 删除缓存（模型/维度失效或用户显式清理时用）。 */\nexport async function clearEmbedCache(path: string): Promise<void> {\n  await rm(path, { force: true })\n}\n\n// ── 惰性计算 + 缓存命中 ─────────────────────────────────────────────────\n\nexport interface EnsureVectorsOptions {\n  cachePath: string\n  chunks: Chunk[]\n  chunkSize?: number\n  req: EmbedRequest\n  /** 查询向量的维度（已知时传入）：与缓存记录不一致 → 判定缓存失效并重算。 */\n  expectedDimensions?: number\n  batchSize?: number\n}\n\nexport interface EnsureVectorsResult {\n  vectors: number[][]\n  dimensions: number\n  /** true = 全部向量来自缓存（**没有**发分块嵌入请求） */\n  fromCache: boolean\n}\n\n/**\n * 惰性计算分块嵌入：缓存有效则直接复用（零分块请求），否则按 batchSize 分批请求。\n * 缓存键 = `{baseUrl, model, dimensions, 内容哈希}`（F-E2：baseUrl 与查询向量备忘对齐，\n * 换端点必须重算）；缓存有效性 = v=1 ∧ baseUrl 一致 ∧ model 一致 ∧ 内容哈希一致 ∧ 条数一致\n * ∧ 维度一致（含 expectedDimensions）∧ 全为有限数。\n * 任一批次失败都抛 EmbedError（调用方整体降级），**不写缓存** —— 绝不产生半截缓存。\n */\nexport async function ensureChunkVectors(o: EnsureVectorsOptions): Promise<EnsureVectorsResult> {\n  const model = o.req.model\n  const hash = chunkSetHash(o.chunks, o.chunkSize ?? 1500)\n  const cached = await readEmbedCache(o.cachePath)\n  const cacheOk =\n    cached !== null &&\n    cached.baseUrl === o.req.baseUrl &&\n    cached.model === model &&\n    cached.contentHash === hash &&\n    cached.vectors.length === o.chunks.length &&\n    cached.dimensions > 0 &&\n    cached.vectors.every((v) => Array.isArray(v) && v.length === cached.dimensions && v.every(isFiniteNumber)) &&\n    (o.expectedDimensions === undefined || o.expectedDimensions === cached.dimensions)\n  if (cacheOk) return { vectors: cached.vectors, dimensions: cached.dimensions, fromCache: true }\n  if (o.chunks.length === 0) return { vectors: [], dimensions: o.expectedDimensions ?? 0, fromCache: false }\n\n  const batchSize = Math.max(1, o.batchSize ?? EMBED_DEFAULTS.batchSize)\n  const vectors: number[][] = []\n  let dimensions = -1\n  for (let i = 0; i < o.chunks.length; i += batchSize) {\n    const part = o.chunks.slice(i, i + batchSize)\n    const got = await requestEmbeddings(o.req, part.map((c) => c.text))\n    for (const v of got) {\n      if (dimensions === -1) dimensions = v.length\n      else if (v.length !== dimensions) throw new EmbedError(`分批嵌入维度不一致（${dimensions} vs ${v.length}）`)\n      vectors.push(v)\n    }\n  }\n  if (o.expectedDimensions !== undefined && dimensions !== o.expectedDimensions) {\n    throw new EmbedError(`嵌入维度与查询向量不一致（${dimensions} vs ${o.expectedDimensions}），本次语义召回已放弃`)\n  }\n  await writeEmbedCache(o.cachePath, {\n    v: 1,\n    baseUrl: o.req.baseUrl,\n    model,\n    dimensions,\n    contentHash: hash,\n    createdAt: new Date().toISOString(),\n    vectors,\n  })\n  return { vectors, dimensions, fromCache: false }\n}\n\n/**\n * 进程内查询向量备忘：同一查询重复检索（同一模型/端点）时**零网络请求**。\n * 键含 endpoint+model，换模型/换端点自动失效；只留最近 32 条，不落盘（查询文本不进缓存文件）。\n */\nconst queryMemo = new Map<string, number[]>()\nconst QUERY_MEMO_MAX = 32\n\nfunction memoKey(req: EmbedRequest, text: string): string {\n  return `${req.baseUrl}|${req.model}|${text}`\n}\n\n/** 清空查询向量备忘（测试/换模型时用）。 */\nexport function clearEmbedQueryMemo(): void {\n  queryMemo.clear()\n}\n\n/** 查询向量（带进程内备忘）。 */\nexport async function embedQuery(req: EmbedRequest, text: string): Promise<number[]> {\n  const key = memoKey(req, text)\n  const hit = queryMemo.get(key)\n  if (hit) return hit\n  const [vec] = await requestEmbeddings(req, [text])\n  if (!vec) throw new EmbedError('嵌入端点未返回查询向量')\n  queryMemo.set(key, vec)\n  if (queryMemo.size > QUERY_MEMO_MAX) {\n    const oldest = queryMemo.keys().next().value\n    if (oldest !== undefined) queryMemo.delete(oldest)\n  }\n  return vec\n}\n\n// ── 召回与融合 ──────────────────────────────────────────────────────────\n\n/** 余弦相似度；维度不同/零向量一律返回 0（不抛错，避免脏数据中断检索）。 */\nexport function cosineSimilarity(a: number[], b: number[]): number {\n  if (a.length === 0 || a.length !== b.length) return 0\n  let dot = 0\n  let na = 0\n  let nb = 0\n  for (let i = 0; i < a.length; i++) {\n    const x = a[i]!\n    const y = b[i]!\n    dot += x * y\n    na += x * x\n    nb += y * y\n  }\n  if (na === 0 || nb === 0) return 0\n  return dot / (Math.sqrt(na) * Math.sqrt(nb))\n}\n\n/** 语义召回：按余弦取前 limit 块（相似度 ≤ 0 视为噪声，不进候选）。 */\nexport function embeddingRecall(\n  chunks: Chunk[],\n  pages: PageSpan[] | null,\n  queryVector: number[],\n  vectors: number[][],\n  limit: number,\n): SearchHit[] {\n  const scored: SearchHit[] = []\n  const n = Math.min(chunks.length, vectors.length)\n  for (let i = 0; i < n; i++) {\n    const sim = cosineSimilarity(queryVector, vectors[i]!)\n    if (sim > 0) {\n      scored.push({ chunk: chunks[i]!, score: Math.round(sim * 1000) / 1000, page: pageForOffset(pages, chunks[i]!.start) })\n    }\n  }\n  scored.sort((a, b) => b.score - a.score || a.chunk.index - b.chunk.index)\n  return scored.slice(0, Math.max(1, limit))\n}\n\n/**\n * RRF 融合（Reciprocal Rank Fusion，k=60）：关键词候选 ∪ 语义候选 → 按**名次**加权求和 → 去重。\n * 为什么用名次而不是原始分数：关键词分（词频×词长）与余弦相似度量纲完全不同，直接相加没有意义。\n *\n * **返回序 = RRF 相关性序**（issue #13）：调用方必须先按本序截取 top-k，再按 chunk.index 排展示序。\n * 这里绝不预先按原文排序——否则上层 `slice(0, k)` 会按文档位置而非相关性截取，丢掉更相关的片段。\n *\n * **实际语义（F-E1 如实记录，算法有意如此，不是 bug）**：\n *   - 只吃名次、**完全不看分数大小**：关键词第 i 名与语义第 j 名的贡献分别是 1/(60+i) 与 1/(60+j)，\n *     所以语义第 j 名会压过关键词第 i 名（当 j < i）——两列候选会**交替占用**最终 top-k 名额；\n *   - 「关键词优先」只在**精确同分**时生效（两列名次相同、分数相等时关键词那列排前面）；\n *   - 两列都命中的片段获得两份贡献，自然排最前。\n * 这正是「嵌入作为召回、与关键词候选交替占位」的预期形态：关键词检索仍在跑并持续贡献候选，\n * 并未被替换。**注意**：本机没有真实嵌入端点可用于调参，故不引入「按分数插值 / 名额保底」\n * 这类无法验证的融合策略；若将来要改（例如给关键词列加权或保底名额），需先回报队长并补可验证证据。\n */\nexport function fuseHybridCandidates(keyword: SearchHit[], semantic: SearchHit[], limit: number): SearchHit[] {\n  const RRF_K = 60\n  const byRank = (hits: SearchHit[]) => hits.slice().sort((a, b) => b.score - a.score || a.chunk.index - b.chunk.index)\n  const kw = byRank(keyword)\n  const sem = byRank(semantic)\n  const byChunk = new Map<number, SearchHit>()\n  const score = new Map<number, number>()\n  const fromKeyword = new Set<number>()\n  kw.forEach((h, i) => {\n    byChunk.set(h.chunk.index, h)\n    fromKeyword.add(h.chunk.index)\n    score.set(h.chunk.index, (score.get(h.chunk.index) ?? 0) + 1 / (RRF_K + i + 1))\n  })\n  sem.forEach((h, i) => {\n    if (!byChunk.has(h.chunk.index)) byChunk.set(h.chunk.index, h)\n    score.set(h.chunk.index, (score.get(h.chunk.index) ?? 0) + 1 / (RRF_K + i + 1))\n  })\n  const picked = [...byChunk.keys()]\n    .sort((a, b) => {\n      const d = (score.get(b) ?? 0) - (score.get(a) ?? 0)\n      if (d !== 0) return d\n      const ka = fromKeyword.has(a)\n      const kb = fromKeyword.has(b)\n      if (ka !== kb) return ka ? -1 : 1\n      return a - b\n    })\n    .slice(0, Math.max(1, limit))\n    .map((idx) => byChunk.get(idx)!)\n  return picked // 保持 RRF 相关性序；展示用的原文序由调用方在**选定 top-k 之后**再排（issue #13）\n}\n\n/**\n * 端点按模型限制单批条数时的典型拒绝文案特征（如百炼：`batch size is invalid, it should\n * not be larger than 20`）。命中就附一句可操作建议——降级原因必须能指导用户自救，\n * 不能只甩端点原文（issue #14）。只做提示，不做自动拆批重试：错误文案各家不一，\n * 盲目匹配重试反而可能对着任意 400 反复打请求。\n */\nexport function batchLimitHint(message: string): string | null {\n  const re = /batch\\s*size|too\\s+many\\s+(inputs?|texts?|items?)|input.{0,40}(larger|exceed|limit|maximum)|(larger|exceed|maximum).{0,40}batch/i\n  return re.test(message) ? '端点可能限制了单批嵌入条数：在「嵌入模型检索」设置里调低批大小（或 profile config.embed 的 batchSize）后重试' : null\n}\n\n// ── 检索侧入口：惰性 + 缓存 + 降级（tools.ts 只调这一个函数）─────────────\n\nexport interface EmbedRecallOptions {\n  /** 是否配齐了凭据（false = 默认关闭，直接返回空候选、零请求、零降级标注） */\n  configured: boolean\n  cachePath: string\n  chunks: Chunk[]\n  pages: PageSpan[] | null\n  query: string\n  chunkSize?: number\n  /** configured=true 时必填 */\n  req?: EmbedRequest\n  limit?: number\n  batchSize?: number\n  signal?: AbortSignal\n}\n\nexport interface EmbedRecallResult {\n  hits: SearchHit[]\n  /** 配置齐全（= 用户确实开了嵌入检索） */\n  configured: boolean\n  /** 真的用上了语义召回 */\n  used: boolean\n  /** 分块向量来自缓存（本次**没有**分块嵌入请求） */\n  fromCache: boolean\n  /** 配了但没成功时的如实降级原因（未配置时为 null） */\n  degraded: string | null\n}\n\n/**\n * 惰性语义召回：查询向量（带进程内备忘）+ 分块向量（带磁盘缓存）→ 余弦 top-N。\n * 任何失败（不可达/超时/HTTP 错误/形状或维度非法/非数值）都**吞成 degraded 原因**，\n * 返回空候选让调用方继续用关键词结果——绝不抛错中断检索。\n */\nexport async function embeddingRecallFor(o: EmbedRecallOptions): Promise<EmbedRecallResult> {\n  if (!o.configured || !o.req) {\n    return { hits: [], configured: false, used: false, fromCache: false, degraded: null }\n  }\n  try {\n    const queryVector = await embedQuery(o.req, o.query)\n    const { vectors, fromCache } = await ensureChunkVectors({\n      cachePath: o.cachePath,\n      chunks